import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { BrandDNA, Campaign } from './types';

interface AppState {
  currentBrand: BrandDNA | null;
  brands: BrandDNA[];
  campaigns: Campaign[];
  setBrand: (brand: BrandDNA) => void;
  addBrand: (brand: BrandDNA) => void;
  addCampaign: (campaign: Campaign) => void;
  updateCampaign: (campaignId: string, updates: Partial<Campaign>) => void;
  reset: () => void;
}

export const useStore = create<AppState>()(
  persist(
    (set) => ({
      currentBrand: null,
      brands: [],
      campaigns: [],
      setBrand: (brand) => set({ currentBrand: brand }),
      addBrand: (brand) => set((state) => ({ 
        brands: [brand, ...state.brands.filter(b => b.id !== brand.id)],
        currentBrand: brand
      })),
      addCampaign: (campaign) => set((state) => ({
        campaigns: [campaign, ...state.campaigns]
      })),
      updateCampaign: (id, updates) => set((state) => ({
        campaigns: state.campaigns.map(c => c.id === id ? { ...c, ...updates } : c)
      })),
      reset: () => set({ currentBrand: null, brands: [], campaigns: [] })
    }),
    {
      name: 'coredna2-storage',
    }
  )
);

import { GoogleGenAI, Type } from "@google/genai";
import { BrandDNA, CampaignAsset } from "../types";

// NOTE: In a real production app, this key should be proxied via backend.
// For this demo, we assume the user might provide it or it's in env.
const API_KEY = process.env.API_KEY || ''; 

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai && API_KEY) {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  }
  return ai;
};

export const checkApiKey = () => !!API_KEY;

export const extractBrandDNA = async (url: string, description: string): Promise<BrandDNA> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Analyze the brand based on this URL: ${url} and this user description: "${description}".

    Act as a world-class Brand Strategist. Extrapolate the "Core DNA" of this entity.
    If the URL is generic or not crawlable, infer the most likely brand attributes based on the name and description.

    Return the result in JSON format matching this structure:
    {
      "name": "Brand Name",
      "tagline": "Catchy tagline",
      "mission": "Mission statement",
      "coreValues": ["Value 1", "Value 2", "Value 3"],
      "tone": {
        "adjectives": ["Adj1", "Adj2"],
        "description": "Full tone description",
        "personality": "Archetype (e.g. Sage, Hero)"
      },
      "visualIdentity": {
        "primaryColor": "Hex Code",
        "secondaryColor": "Hex Code",
        "fontPairing": "Font names",
        "styleKeywords": ["Modern", "Clean"]
      },
      "targetAudience": ["Segment 1", "Segment 2"],
      "confidenceScore": 85 (integer 0-100)
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        // Using strict schema helps, but for this demo, standard JSON mode is sufficient and more flexible
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);

    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      ...data
    } as BrandDNA;

  } catch (error) {
    console.error("Extraction failed", error);
    throw error;
  }
};

export const generateCampaignAssets = async (
  brand: BrandDNA, 
  goal: string, 
  channels: string[]
): Promise<CampaignAsset[]> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Brand Profile: ${JSON.stringify(brand)}

    Campaign Goal: ${goal}
    Target Channels: ${channels.join(', ')}

    Generate 1 high-quality marketing asset for EACH selected channel.
    Each asset must be perfectly aligned with the brand's tone (${brand.tone.personality}) and visual identity.

    Return a JSON array of objects:
    [
      {
        "type": "social" | "email" | "blog",
        "platform": "linkedin" | "twitter" | "instagram" | "email",
        "title": "Hook or Subject Line",
        "content": "Full body content",
        "imagePrompt": "Detailed prompt for an image generator describing the visual",
        "hashtags": ["#tag1", "#tag2"]
      }
    ]
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");

    const rawAssets = JSON.parse(text);

    return rawAssets.map((asset: any) => ({
      id: crypto.randomUUID(),
      status: 'generated',
      ...asset
    }));

  } catch (error) {
    console.error("Generation failed", error);
    throw error;
  }
};

export const sonicChat = async (history: {role: 'user' | 'model', text: string}[], message: string, brandContext?: BrandDNA) => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const systemInstruction = brandContext 
    ? `You are Sonic, an advanced AI Brand Co-Pilot. You are currently analyzing the brand "${brandContext.name}". 
       Your responses should be concise, strategic, and helpful. 
       Brand Context: ${JSON.stringify(brandContext)}`
    : `You are Sonic, an advanced AI Brand Co-Pilot. Guide the user to extract a brand or create a campaign.`;

  const chat = client.chats.create({
    model: 'gemini-2.5-flash-preview',
    config: {
      systemInstruction,
    },
    history: history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }))
  });

  const result = await chat.sendMessage({ message });
  return result.text;
};

