import React, { useState, useEffect, useRef } from 'react';
import { Mic, MicOff, Volume2 } from 'lucide-react';
import { useStore } from '../store';
import { sonicChat } from '../services/geminiService';

export const SonicOrb = () => {
  const [isActive, setIsActive] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [transcript, setTranscript] = useState('');
  const recognitionRef = useRef<any>(null);
  const { currentBrand } = useStore();

  useEffect(() => {
    // Initialize Web Speech API
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;

      recognitionRef.current.onresult = (event: any) => {
        const t = event.results[0][0].transcript;
        setTranscript(t);
      };

      recognitionRef.current.onend = () => {
        setIsActive(false);
        if (transcript) {
          handleVoiceCommand(transcript);
        }
      };
    }
  }, [transcript]);

  const handleVoiceCommand = async (text: string) => {
    setIsProcessing(true);
    try {
      // Send to Gemini
      const response = await sonicChat(
        [{role: 'user', text}], 
        text, 
        currentBrand || undefined
      );

      if (response) {
        speak(response);
      }
    } catch (e) {
      console.error(e);
      speak("I encountered an error connecting to my neural core.");
    } finally {
      setIsProcessing(false);
      setTranscript('');
    }
  };

  const speak = (text: string) => {
    if ('speechSynthesis' in window) {
      setIsSpeaking(true);
      const utterance = new SpeechSynthesisUtterance(text);
      // Try to select a "modern" voice if available
      const voices = window.speechSynthesis.getVoices();
      const preferredVoice = voices.find(v => v.name.includes('Google') || v.name.includes('Samantha'));
      if (preferredVoice) utterance.voice = preferredVoice;

      utterance.pitch = 1;
      utterance.rate = 1.1;

      utterance.onend = () => setIsSpeaking(false);
      window.speechSynthesis.speak(utterance);
    }
  };

  const toggleMic = () => {
    if (isActive) {
      recognitionRef.current?.stop();
      setIsActive(false);
    } else {
      setTranscript('');
      recognitionRef.current?.start();
      setIsActive(true);
    }
  };

  return (
    <div className="relative group">
      {/* Tooltip */}
      <div className="absolute bottom-full right-0 mb-4 px-3 py-1 rounded bg-black border border-zinc-800 text-xs text-zinc-400 whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
        Sonic Co-Pilot
      </div>

      {/* Main Button */}
      <button
        onClick={toggleMic}
        className={`relative w-16 h-16 rounded-full flex items-center justify-center transition-all duration-300 focus:outline-none ${
          isActive || isSpeaking || isProcessing
            ? 'scale-110' 
            : 'hover:scale-105 hover:bg-zinc-800'
        }`}
      >
        {/* Rings */}
        {(isActive || isSpeaking || isProcessing) && (
          <>
            <div className={`absolute inset-0 rounded-full border border-brand-500/50 ${isProcessing ? 'animate-spin-slow' : 'animate-ping'} opacity-20`}></div>
            <div className={`absolute inset-[-4px] rounded-full border border-brand-500/30 ${isSpeaking ? 'animate-pulse' : ''}`}></div>
            <div className="absolute inset-0 bg-brand-500/10 rounded-full blur-md"></div>
          </>
        )}

        <div className={`z-10 rounded-full p-4 ${
          isActive ? 'bg-brand-600 text-white shadow-[0_0_20px_rgba(13,148,136,0.6)]' :
          isProcessing ? 'bg-purple-600 text-white animate-pulse' :
          isSpeaking ? 'bg-amber-500 text-white' :
          'bg-zinc-900 border border-zinc-700 text-zinc-400'
        }`}>
          {isSpeaking ? <Volume2 className="w-6 h-6" /> : <Mic className="w-6 h-6" />}
        </div>
      </button>

      {/* Transcript Pop-up */}
      {transcript && isActive && (
        <div className="absolute bottom-20 right-0 w-64 p-4 bg-black/80 backdrop-blur border border-zinc-800 rounded-lg text-sm text-zinc-200 shadow-xl">
          <p>"{transcript}"</p>
        </div>
      )}
    </div>
  );
};

