import React, { useState } from 'react';
import { useStore } from '../store';
import { checkApiKey, extractBrandDNA } from '../services/geminiService';
import { DNAHelix } from '../components/DNAHelix';
import { ProcessingState } from '../types';
import { Search, AlertCircle, CheckCircle2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const ExtractPage = () => {
  const [url, setUrl] = useState('');
  const [desc, setDesc] = useState('');
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);
  const [error, setError] = useState('');
  const { setBrand, addBrand, currentBrand } = useStore();
  const navigate = useNavigate();

  const handleExtract = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!checkApiKey()) {
      setError("System Error: Neural Core Disconnected (Missing API Key). Check env.");
      return;
    }

    setStatus(ProcessingState.ANALYZING);
    try {
      const brand = await extractBrandDNA(url, desc);
      addBrand(brand);
      setStatus(ProcessingState.COMPLETE);
    } catch (err) {
      setError("Extraction Failed: The target refused connection or analysis timed out.");
      setStatus(ProcessingState.ERROR);
    }
  };

  return (
    <div className="p-8 max-w-5xl mx-auto min-h-screen">
       <div className="mb-8">
        <h1 className="text-3xl font-bold text-white mb-2">Extraction Protocol</h1>
        <p className="text-zinc-400">Enter target coordinates (URL) to begin biological brand analysis.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
        {/* Input Form */}
        <div className="space-y-6">
          <form onSubmit={handleExtract} className="space-y-6 bg-dark-surface p-6 rounded-xl border border-dark-border">
            <div>
              <label className="block text-xs font-bold text-zinc-500 uppercase mb-2">Target URL</label>
              <div className="relative">
                <Search className="absolute left-3 top-3 w-5 h-5 text-zinc-500" />
                <input 
                  type="text" 
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                  placeholder="https://example.com"
                  className="w-full bg-black/40 border border-zinc-700 rounded-lg py-2.5 pl-10 pr-4 text-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-zinc-500 uppercase mb-2">Contextual Data (Optional)</label>
              <textarea 
                value={desc}
                onChange={(e) => setDesc(e.target.value)}
                placeholder="Paste mission statement or brief description to aid the neural engine..."
                className="w-full h-32 bg-black/40 border border-zinc-700 rounded-lg p-4 text-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none resize-none"
              />
            </div>

            <button 
              type="submit"
              disabled={status === ProcessingState.ANALYZING}
              className="w-full py-3 bg-brand-600 hover:bg-brand-500 disabled:bg-zinc-700 text-white rounded-lg font-bold tracking-wide transition-all shadow-[0_0_15px_rgba(13,148,136,0.3)] hover:shadow-[0_0_25px_rgba(13,148,136,0.5)]"
            >
              {status === ProcessingState.ANALYZING ? 'ANALYZING PATTERNS...' : 'INITIATE EXTRACTION'}
            </button>

            {error && (
              <div className="flex items-center gap-2 text-red-400 bg-red-900/10 p-3 rounded border border-red-900/30 text-sm">
                <AlertCircle className="w-4 h-4" /> {error}
              </div>
            )}
          </form>

          {/* Guidelines */}
          <div className="p-4 border border-brand-900/30 bg-brand-900/5 rounded-lg">
            <h4 className="text-brand-400 text-sm font-bold mb-2 flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4" /> System Ready
            </h4>
            <p className="text-xs text-brand-200/60 leading-relaxed">
              The extraction engine uses Gemini 2.5 recursive logic to infer brand archetypes, visual styles, and tonal consistency from limited data points.
            </p>
          </div>
        </div>

        {/* Preview / Results */}
        <div className="flex flex-col gap-6">
          <DNAHelix dna={currentBrand} loading={status === ProcessingState.ANALYZING} />

          {status === ProcessingState.COMPLETE && (
            <div className="bg-green-900/10 border border-green-900/30 p-4 rounded-xl animate-in fade-in slide-in-from-bottom-4">
              <h3 className="text-green-400 font-bold mb-2">Analysis Complete</h3>
              <p className="text-sm text-zinc-400 mb-4">Brand DNA has been successfully mapped and stored in the session memory.</p>
              <div className="flex gap-3">
                <button onClick={() => navigate('/campaigns')} className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white rounded text-sm transition-colors">
                  Forge Campaign
                </button>
                <button onClick={() => navigate('/')} className="px-4 py-2 text-zinc-400 hover:text-white text-sm transition-colors">
                  Return to Hub
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ExtractPage;

