const CampaignsPage = () => {
  const { currentBrand, addCampaign } = useStore();
  const [goal, setGoal] = useState('');
  const [channels, setChannels] = useState<string[]>(['linkedin', 'twitter']);
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);
  const [generatedAssets, setGeneratedAssets] = useState<CampaignAsset[]>([]);

  const toggleChannel = (c: string) => {
    setChannels(prev => prev.includes(c) ? prev.filter(x => x !== c) : [...prev, c]);
  };

  const handleGenerate = async () => {
    if (!currentBrand) return;
    setStatus(ProcessingState.GENERATING);
    try {
      const assets = await generateCampaignAssets(currentBrand, goal, channels);
      setGeneratedAssets(assets);

      const newCampaign: Campaign = {
        id: crypto.randomUUID(),
        name: `Auto-Gen: ${goal.substring(0, 20)}...`,
        goal,
        assets,
        createdAt: new Date().toISOString()
      };
      addCampaign(newCampaign);

      setStatus(ProcessingState.COMPLETE);
    } catch (e) {
      console.error(e);
      setStatus(ProcessingState.ERROR);
    }
  };

  if (!currentBrand) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <div className="text-center max-w-md">
          <Sparkles className="w-12 h-12 text-zinc-700 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-white mb-2">Systems Dormant</h2>
          <p className="text-zinc-500 mb-6">You must extract a Brand DNA before the Campaign Forge can be activated.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto">
      <div className="mb-8 flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-white mb-2">Campaign Forge</h1>
          <p className="text-zinc-400">Autonomous asset generation engine based on <span className="text-brand-500 font-mono">{currentBrand.name}</span> DNA.</p>
        </div>
        <div className="flex items-center gap-2 px-3 py-1 rounded bg-brand-900/10 border border-brand-900/30">
          <span className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></span>
          <span className="text-xs text-brand-400 font-bold">AI READY</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Controls */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-dark-surface p-6 rounded-xl border border-dark-border">
            <h3 className="text-sm font-bold text-white mb-4 uppercase tracking-wider">Configuration</h3>

            <div className="space-y-4">
              <div>
                <label className="block text-xs text-zinc-500 mb-1">Campaign Goal</label>
                <textarea 
                  value={goal}
                  onChange={(e) => setGoal(e.target.value)}
                  placeholder="e.g. Promote our new eco-friendly packaging launch targeting Gen-Z..."
                  className="w-full h-32 bg-black/40 border border-zinc-700 rounded-lg p-3 text-sm text-white focus:border-brand-500 outline-none resize-none"
                />
              </div>

              <div>
                <label className="block text-xs text-zinc-500 mb-2">Target Channels</label>
                <div className="flex flex-wrap gap-2">
                  {['linkedin', 'twitter', 'instagram', 'email'].map(c => (
                    <button
                      key={c}
                      onClick={() => toggleChannel(c)}
                      className={`px-3 py-1.5 rounded text-xs font-medium border transition-all ${
                        channels.includes(c) 
                          ? 'bg-brand-600 border-brand-500 text-white' 
                          : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
                      }`}
                    >
                      {c.charAt(0).toUpperCase() + c.slice(1)}
                    </button>
                  ))}
                </div>
              </div>

              <button
                onClick={handleGenerate}
                disabled={status === ProcessingState.GENERATING || !goal}
                className="w-full py-3 bg-gradient-to-r from-brand-600 to-brand-500 text-white font-bold rounded-lg shadow-lg hover:shadow-brand-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {status === ProcessingState.GENERATING ? (
                  <>
                    <RefreshCw className="w-4 h-4 animate-spin" /> FORGING...
                  </>
                ) : (
                  <>
                    <Sparkles className="w-4 h-4" /> GENERATE ASSETS
                  </>
                )}
              </button>
            </div>
          </div>

          <div className="bg-gradient-to-br from-purple-900/10 to-transparent p-6 rounded-xl border border-purple-500/10">
            <h4 className="text-purple-400 text-sm font-bold mb-2">Paradigm Shift</h4>
            <p className="text-xs text-zinc-400">
              This engine doesn't just write copy. It simulates thousands of potential engagement vectors and selects the one with the highest resonance probability based on the brand's psychographic profile.
            </p>
          </div>
        </div>

