import { BrandDNA, CampaignAsset, UserStory, HealingReport } from "../types";
import { validateAssetQuality, regenerateAsset } from "./geminiService";

export const healAsset = async (
  brand: BrandDNA,
  asset: Partial<CampaignAsset>,
  story: UserStory,
  maxRetries = 2
): Promise<{ asset: Partial<CampaignAsset>, report: HealingReport }> => {

  let currentAsset = { ...asset };
  let attempts = 0;
  let validation = await validateAssetQuality(brand, currentAsset, story);

  const initialScore = validation.score;
  const issues = [...validation.issues];

  while (validation.score < 80 && attempts < maxRetries) {
    console.log(`Healing asset (Attempt ${attempts + 1}). Score: ${validation.score}`);

    // Regenerate
    const fixedAsset = await regenerateAsset(brand, currentAsset, validation.issues);
    currentAsset = { ...currentAsset, ...fixedAsset };

    // Re-validate
    validation = await validateAssetQuality(brand, currentAsset, story);
    attempts++;
  }

  return {
    asset: currentAsset,
    report: {
      originalScore: initialScore,
      issues: issues,
      attempts,
      finalScore: validation.score,
      wasHealed: attempts > 0
    }
  };
};

import { BrandDNA, CampaignPRD, CampaignAsset, UserStory } from "../types";
import { generateAssetFromStory } from "./geminiService";
import { healAsset } from "./selfHealingService";

export type LogCallback = (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
export type ProgressCallback = (completed: number, total: number) => void;
export type AssetCallback = (asset: CampaignAsset) => void;
export type StoryUpdateCallback = (storyId: string, status: UserStory['status']) => void;

export class AutonomousCampaignEngine {
  private brand: BrandDNA;
  private prd: CampaignPRD;
  private onLog: LogCallback;
  private onProgress: ProgressCallback;
  private onAssetGenerated: AssetCallback;
  private onStoryUpdate: StoryUpdateCallback;
  private stopSignal = false;

  constructor(
    brand: BrandDNA,
    prd: CampaignPRD,
    onLog: LogCallback,
    onProgress: ProgressCallback,
    onAssetGenerated: AssetCallback,
    onStoryUpdate: StoryUpdateCallback
  ) {
    this.brand = brand;
    this.prd = prd;
    this.onLog = onLog;
    this.onProgress = onProgress;
    this.onAssetGenerated = onAssetGenerated;
    this.onStoryUpdate = onStoryUpdate;
  }

  public stop() {
    this.stopSignal = true;
  }

  public async start() {
    this.onLog(`Initializing Autonomous Engine for ${this.brand.name}...`, 'info');
    this.onLog(`Loaded PRD: ${this.prd.userStories.length} user stories queued.`, 'info');

    let completed = 0;
    const total = this.prd.userStories.length;

    for (const story of this.prd.userStories) {
      if (this.stopSignal) {
        this.onLog("Process halted by user.", 'warning');
        break;
      }

      await this.executeStory(story);
      completed++;
      this.onProgress(completed, total);
    }

    this.onLog("Campaign Sequence Complete.", 'success');
  }

  private async executeStory(story: UserStory) {
    this.onStoryUpdate(story.id, 'generating');
    this.onLog(`Executing Story [${story.id.slice(0, 4)}]: ${story.role} -> ${story.benefit}`, 'info');

    try {
      // 1. Generate Raw Asset
      const rawAsset = await generateAssetFromStory(this.brand, story);
      this.onLog(`Generated draft for ${story.channel}...`, 'info');

      // 2. Self-Healing / Validation
      this.onStoryUpdate(story.id, 'validating');
      this.onLog(`Validating against Brand DNA & Acceptance Criteria...`, 'info');

      const { asset: finalAssetData, report } = await healAsset(this.brand, rawAsset, story);

      if (report.wasHealed) {
        this.onLog(`Self-Healing Activated: Fixed ${report.attempts} issues. Score improved: ${report.originalScore} -> ${report.finalScore}`, 'success');
      } else {
        this.onLog(`Quality Check Passed: Score ${report.finalScore}/100`, 'success');
      }

      // 3. Finalize
      const finalAsset: CampaignAsset = {
        id: crypto.randomUUID(),
        type: 'social', // simplified for demo
        platform: story.channel,
        title: finalAssetData.title || 'Untitled',
        content: finalAssetData.content || '',
        imagePrompt: finalAssetData.imagePrompt,
        hashtags: finalAssetData.hashtags || [],
        status: 'generated',
        qualityScore: report.finalScore,
        healingReport: report,
        storyId: story.id
      };

      this.onAssetGenerated(finalAsset);
      this.onStoryUpdate(story.id, 'completed');

    } catch (error) {
      this.onLog(`Failed to execute story: ${(error as Error).message}`, 'error');
      this.onStoryUpdate(story.id, 'failed');
    }
  }
}

