        <div className="bg-dark-surface border border-dark-border p-4 rounded-xl">
          <p className="text-zinc-500 text-xs uppercase font-bold mb-1">Success Rate</p>
          <p className="text-2xl font-bold text-green-500">99.8%</p>
        </div>
