import { GoogleGenAI } from "@google/genai";
import { BrandDNA, BattleReport } from "../types";

const API_KEY = process.env.API_KEY || ''; 

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai && API_KEY) {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  }
  return ai;
};

export const generateBattleReport = async (brandA: BrandDNA, brandB: BrandDNA): Promise<BattleReport> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Act as a Ruthless Brand Strategist. Compare these two brands head-to-head.

    BRAND A:
    Name: ${brandA.name}
    Mission: ${brandA.mission}
    Values: ${brandA.coreValues.join(', ')}
    Tone: ${brandA.tone.personality} (${brandA.tone.adjectives.join(', ')})
    Visuals: ${brandA.visualIdentity.styleKeywords.join(', ')}

    BRAND B:
    Name: ${brandB.name}
    Mission: ${brandB.mission}
    Values: ${brandB.coreValues.join(', ')}
    Tone: ${brandB.tone.personality} (${brandB.tone.adjectives.join(', ')})
    Visuals: ${brandB.visualIdentity.styleKeywords.join(', ')}

    Output a JSON object with this EXACT structure:
    {
      "visualAnalysis": {
        "summary": "Compare their visual aesthetics.",
        "winner": "A" or "B" or "Tie"
      },
      "messagingAnalysis": {
        "summary": "Compare their tone and messaging impact.",
        "winner": "A" or "B" or "Tie"
      },
      "marketPositioning": {
        "overlap": "High" or "Medium" or "Low",
        "differentiation": "How they distinguish themselves from each other."
      },
      "scores": {
        "brandA": 85,
        "brandB": 72,
        "breakdown": [
           { "category": "Clarity", "scoreA": 90, "scoreB": 80 },
           { "category": "Consistency", "scoreA": 85, "scoreB": 70 },
           { "category": "Innovation", "scoreA": 70, "scoreB": 85 },
           { "category": "Resonance", "scoreA": 88, "scoreB": 92 }
        ]
      },
      "gapAnalysis": {
        "brandAMissing": ["Gap 1", "Gap 2"],
        "brandBMissing": ["Gap 1", "Gap 2"]
      },
      "critique": "A final paragraph summarizing the battle and advice."
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const data = JSON.parse(response.text || '{}');

    return {
      id: crypto.randomUUID(),
      brandAId: brandA.id,
      brandBId: brandB.id,
      analyzedAt: new Date().toISOString(),
      ...data
    } as BattleReport;

  } catch (error) {
    console.error("Battle analysis failed", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { generateBattleReport } from '../services/competitorAnalysisService';
import { BattleReport, ProcessingState, BrandDNA } from '../types';
import { Swords, Trophy, AlertTriangle, ArrowRight, Activity, TrendingUp, ShieldAlert, Target } from 'lucide-react';
import { Link } from 'react-router-dom';

const BattleModePage = () => {
  const { brands } = useStore();
  const [selectedA, setSelectedA] = useState<string>('');
  const [selectedB, setSelectedB] = useState<string>('');
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);
  const [report, setReport] = useState<BattleReport | null>(null);

  const brandA = brands.find(b => b.id === selectedA);
  const brandB = brands.find(b => b.id === selectedB);

  const handleBattle = async () => {
    if (!brandA || !brandB) return;

    setStatus(ProcessingState.ANALYZING);
    try {
      const result = await generateBattleReport(brandA, brandB);
      setReport(result);
      setStatus(ProcessingState.COMPLETE);
    } catch (e) {
      console.error(e);
      setStatus(ProcessingState.ERROR);
    }
  };

  const reset = () => {
    setReport(null);
    setStatus(ProcessingState.IDLE);
  };

  // --- RENDERING ---

  if (brands.length < 2) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <div className="text-center max-w-md bg-dark-surface p-8 rounded-xl border border-dark-border shadow-2xl">
          <Swords className="w-16 h-16 text-zinc-700 mx-auto mb-6" />
          <h2 className="text-2xl font-bold text-white mb-3">Arena Empty</h2>
          <p className="text-zinc-500 mb-6">Battle Mode requires at least two extracted Brand DNAs to perform a comparative analysis.</p>
