import { GoogleGenAI } from "@google/genai";
import { LeadProfile, CloserPortfolio } from "../types";

const API_KEY = process.env.API_KEY || ''; 

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai && API_KEY) {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  }
  return ai;
};

export const huntLeads = async (industry: string, location: string): Promise<LeadProfile[]> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  // Since we can't actually scrape LinkedIn/Google Maps in this environment,
  // we use Gemini to "Simulate" the results of a high-tech scraper.
  const prompt = `
    Act as an advanced B2B Lead Scraper & Qualifier.
    Generate 4 realistic BUSINESS LEADS for the "${industry}" industry in "${location}".

    Make them varied in quality (some good, some struggling).
    Infer realistic vulnerabilities (e.g., bad website, low reviews, missing social presence).

    Return a JSON array of objects with this structure:
    [
      {
        "companyName": "Name",
        "website": "url",
        "rating": 3.5,
        "contactEmail": "info@domain.com",
        "techStack": ["Wordpress", "jQuery"],
        "vulnerabilities": ["Non-responsive site", "Last post 2021"],
        "opportunityScore": 85
      }
    ]
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const rawLeads = JSON.parse(response.text || '[]');

    return rawLeads.map((lead: any) => ({
      id: crypto.randomUUID(),
      industry,
      location,
      status: 'new',
      ...lead
    })) as LeadProfile[];

  } catch (error) {
    console.error("Lead hunting failed", error);
    return [];
  }
};

export const generateCloserPortfolio = async (lead: LeadProfile): Promise<CloserPortfolio> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Act as a World-Class Sales Copywriter & Closer.
    Create a "Closer Portfolio" to sell marketing/branding services to this specific lead:

    Company: ${lead.companyName}
    Industry: ${lead.industry}
    Vulnerabilities: ${lead.vulnerabilities.join(', ')}
    Opportunity Score: ${lead.opportunityScore}

    Output a JSON object with this structure:
    {
      "subjectLine": "A high-conversion cold email subject line",
      "emailBody": "The cold email body focusing on their specific vulnerabilities",
      "closingScript": "A script for the phone call closing",
      "objections": [
        { "objection": "e.g. We don't have budget", "rebuttal": "Best response..." },
        { "objection": "e.g. We are happy with current agency", "rebuttal": "Best response..." }
      ],
      "followUpSequence": ["Day 1 email summary", "Day 3 nudge summary", "Day 7 breakup summary"]
    }
  `;

  const response = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: prompt,
    config: { responseMimeType: 'application/json' }
  });

  return JSON.parse(response.text || '{}') as CloserPortfolio;
};

