const LeadHunterPage = () => {
  const [industry, setIndustry] = useState('');
  const [location, setLocation] = useState('');
  const [leads, setLeads] = useState<LeadProfile[]>([]);
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);

  const handleHunt = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!industry || !location) return;

    setStatus(ProcessingState.ANALYZING);
    setLeads([]);

    try {
      const results = await huntLeads(industry, location);
      setLeads(results);
      setStatus(ProcessingState.COMPLETE);
    } catch (e) {
      console.error(e);
      setStatus(ProcessingState.ERROR);
    }
  };

  return (
    <div className="p-8 max-w-7xl mx-auto h-full flex flex-col">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-white mb-2 flex items-center gap-3">
          <Target className="w-8 h-8 text-brand-500" /> Lead Hunter
        </h1>
        <p className="text-zinc-400">AI-powered B2B lead scraping and vulnerability analysis.</p>
      </div>

      {/* Search Bar */}
      <div className="bg-dark-surface p-6 rounded-xl border border-dark-border mb-8 shadow-xl">
        <form onSubmit={handleHunt} className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Briefcase className="absolute left-3 top-3.5 w-5 h-5 text-zinc-500" />
            <input 
              type="text" 
              value={industry}
              onChange={(e) => setIndustry(e.target.value)}
              placeholder="Target Industry (e.g. Dental Clinics, SaaS)"
              className="w-full bg-black/40 border border-zinc-700 rounded-lg py-3 pl-10 pr-4 text-white focus:ring-2 focus:ring-brand-500 outline-none"
              required
            />
          </div>
          <div className="flex-1 relative">
            <MapPin className="absolute left-3 top-3.5 w-5 h-5 text-zinc-500" />
            <input 
              type="text" 
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              placeholder="Location (e.g. Austin, TX)"
              className="w-full bg-black/40 border border-zinc-700 rounded-lg py-3 pl-10 pr-4 text-white focus:ring-2 focus:ring-brand-500 outline-none"
              required
            />
          </div>
          <button 
            type="submit"
            disabled={status === ProcessingState.ANALYZING}
            className="px-8 py-3 bg-brand-600 hover:bg-brand-500 disabled:bg-zinc-700 text-white font-bold rounded-lg transition-all flex items-center gap-2 whitespace-nowrap"
          >
            {status === ProcessingState.ANALYZING ? (
              <RefreshCw className="w-5 h-5 animate-spin" />
            ) : (
              <Search className="w-5 h-5" />
            )}
            {status === ProcessingState.ANALYZING ? 'Hunting...' : 'Find Leads'}
          </button>
        </form>
      </div>

      {/* Results Area */}
      <div className="flex-1 min-h-0 overflow-y-auto">
        {status === ProcessingState.COMPLETE && leads.length > 0 && (
           <div className="space-y-4 pb-12 animate-in fade-in slide-in-from-bottom-4">
             <div className="flex justify-between items-center text-sm text-zinc-500 px-2">
                <span>Found {leads.length} potential opportunities</span>
                <span>AI Scraper Status: Idle</span>
             </div>
             {leads.map(lead => (
               <LeadCard key={lead.id} lead={lead} />
             ))}
           </div>
        )}

        {status === ProcessingState.COMPLETE && leads.length === 0 && (
          <div className="text-center py-20 text-zinc-500">
            <Search className="w-12 h-12 mx-auto mb-4 opacity-20" />
            <p>No leads found matching criteria. Try broadening your search.</p>
          </div>
        )}
      </div>
    </div>
  );
};

