);

import { GoogleGenAI } from "@google/genai";
import { VideoEngine, UserTier, VideoJob } from "../types";

const API_KEY = process.env.API_KEY || ''; 

// Helper for calculating costs
export const getEngineCost = (engine: VideoEngine, tier: UserTier): number => {
  if (tier === 'agency') return 0; // Unlimited

  switch (engine) {
    case 'ltx-2': return 1;
    case 'sora-2-pro': return 5;
    case 'veo-3': return 5;
    default: return 1;
  }
};

export const checkVideoLimits = (tier: UserTier, currentJobs: VideoJob[], engine: VideoEngine): { allowed: boolean; reason?: string } => {
  // Simple monthly limit simulation based on array length for demo
  const monthlyCount = currentJobs.length; 

  if (tier === 'free') {
    if (engine !== 'ltx-2') return { allowed: false, reason: "Upgrade to Hunter tier for premium engines." };
    if (monthlyCount >= 5) return { allowed: false, reason: "Free tier limit reached (5/mo)." };
  }

  if (tier === 'pro') {
    if (engine !== 'ltx-2') return { allowed: false, reason: "Upgrade to Hunter tier for premium engines." };
    if (monthlyCount >= 50) return { allowed: false, reason: "Pro tier limit reached (50/mo)." };
  }

  return { allowed: true };
};

// --- Generation Logic ---

export const generateVideo = async (
  prompt: string, 
  engine: VideoEngine,
  onComplete: (url: string) => void
): Promise<void> => {

  console.log(`[VideoService] Generating with ${engine}: ${prompt}`);

  // In a real app, this would call specific APIs.
  // For Veo, we could use the Google GenAI SDK if we had a paid key active in the window.
  // Since we are mocking the "generation" time and result for the demo unless we have specific keys:

  return new Promise((resolve, reject) => {
    // Simulate generation time (faster for LTX, slower for others)
    const delay = engine === 'ltx-2' ? 3000 : 8000;

    setTimeout(() => {
      // Mock result URLs (placeholder videos)
      const mockVideos = [
        "https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4",
        "https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4",
        "https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4",
        "https://storage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4"
      ];

      const randomVideo = mockVideos[Math.floor(Math.random() * mockVideos.length)];

      onComplete(randomVideo);
      resolve();
    }, delay);
  });
};

// Veo specific implementation using the SDK (if we were to enable it fully)
// This serves as the reference implementation for the "Google GenAI" part of the stack.
export const generateVeoVideo = async (prompt: string, apiKey: string) => {
  const ai = new GoogleGenAI({ apiKey });

  // Note: This is a placeholder for the actual Veo call structure based on the prompt's SDK guide.
  // We handle the "waiting" operation in the UI/Service layer usually.
  try {
     const operation = await ai.models.generateVideos({
       model: 'veo-3.1-fast-generate-preview', // using the fast preview model
       prompt: prompt,
       config: {
         numberOfVideos: 1,
         resolution: '720p',
         aspectRatio: '16:9'
       }
     });
     return operation;
  } catch (e) {
    console.error("Veo Generation Error", e);
    throw e;
  }
};

