  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const prompt = `
    Act as a Creative Director. The current brand "${brand.name}" has these visuals:
    Primary: ${brand.visualIdentity.primaryColor}
    Secondary: ${brand.visualIdentity.secondaryColor}
    Font: ${brand.visualIdentity.fontPairing}
    Style: ${brand.visualIdentity.styleKeywords.join(', ')}

    Generate 3 DISTINCT alternative visual identities (variants) that might perform better or target a slightly different angle (e.g., more modern, more trustworthy, more energetic).

    Return JSON array:
    [
      {
        "name": "e.g. Electric Modern",
        "primaryColor": "Hex",
        "secondaryColor": "Hex",
        "fontPairing": "Font names",
        "rationale": "Why this works..."
      }
    ]
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const data = JSON.parse(response.text || '[]');
    return data.map((v: any) => ({ ...v, id: crypto.randomUUID() }));
  } catch (e) {
    console.error(e);
    // Fallback
    return [
      { id: 'v1', name: 'High Contrast', primaryColor: '#000000', secondaryColor: '#FFFF00', fontPairing: 'Helvetica / Roboto', rationale: 'Maximum impact.' },
      { id: 'v2', name: 'Soft Trust', primaryColor: '#3B82F6', secondaryColor: '#EFF6FF', fontPairing: 'Garamond / Open Sans', rationale: 'Builds reliability.' },
      { id: 'v3', name: 'Nature Inspired', primaryColor: '#059669', secondaryColor: '#ECFDF5', fontPairing: 'Inter / Inter', rationale: 'Organic growth feel.' }
    ];
  }
};

// --- Copy Simulator ---
export const generateCopyVariants = async (brand: BrandDNA, originalText: string, type: 'tagline' | 'headline' | 'cta'): Promise<CopyVariant[]> => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const prompt = `
    Act as a Conversion Copywriter.
    Brand: ${brand.name}
    Tone: ${brand.tone.personality}
    Original ${type}: "${originalText}"

    Generate 3 variations of this ${type}.
    1. A safer, clear version.
    2. A bolder, more aggressive version.
    3. A witty/creative version.

    Predict a conversion score (0-100) relative to industry standards.

    Return JSON array:
    [
      {
        "text": "New text...",
        "tone": "Bold",
        "predictedScore": 85,
        "rationale": "Uses power words..."
      }
    ]
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const data = JSON.parse(response.text || '[]');
    return data.map((v: any) => ({ ...v, id: crypto.randomUUID() }));
  } catch (e) {
    return [
       { id: 'c1', text: originalText + " (Improved)", tone: "Clear", predictedScore: 75, rationale: "Added clarity." }
    ];
  }
};

// --- Audience Simulator ---
export const simulateAudienceReaction = async (
  brand: BrandDNA, 
  content: string, 
  personaName: string, 
  personaRole: string
): Promise<AudienceFeedback> => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const prompt = `
    Act as a specific persona: "${personaName}", who is a "${personaRole}".

    You are evaluating content from the brand "${brand.name}".
    Content to review: "${content}"

    Your Goals/Pain Points: ${brand.personas.find(p => p.name === personaName)?.painPoints.join(', ') || 'General user needs'}

    Analyze this content from YOUR perspective. 
    - Do you like it? 
    - Does it solve your problem?
    - Is the tone right?

    Return JSON:
    {
      "sentiment": "positive" | "neutral" | "negative",
      "score": 85, (0-100 satisfaction)
      "comments": "First person feedback like 'I really love how... but I am worried about...'",
      "suggestedImprovement": "What would make you buy/click?"
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const data = JSON.parse(response.text || '{}');
    return {
      id: crypto.randomUUID(),
      personaName,
      ...data
    };
  } catch (e) {
    return {
      id: 'err',
      personaName,
      sentiment: 'neutral',
      score: 50,
      comments: "Simulation unavailable.",
      suggestedImprovement: "Try again later."
    };
  }
};

import React, { useState } from 'react';
