import { DesignVariant, CopyVariant, AudienceFeedback, ProcessingState } from '../types';
import { generateDesignVariants, generateCopyVariants, simulateAudienceReaction } from '../services/simulationService';
import { 
  FlaskConical, 
  Palette, 
  Type, 
  Users, 
  RefreshCw, 
  CheckCircle2, 
  ArrowRight, 
  MessageSquare,
