import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { BrandDNA, Campaign, UserTier, VideoJob, Agent } from './types';

interface AppState {
  currentBrand: BrandDNA | null;
  brands: BrandDNA[];
  campaigns: Campaign[];
  userTier: UserTier;
  credits: number;
  videoJobs: VideoJob[];
  agents: Agent[];

  setBrand: (brand: BrandDNA) => void;
  addBrand: (brand: BrandDNA) => void;
  updateBrand: (id: string, updates: Partial<BrandDNA>) => void;
  addCampaign: (campaign: Campaign) => void;
  updateCampaign: (campaignId: string, updates: Partial<Campaign>) => void;

  // Scheduling
  scheduleAsset: (assetId: string, scheduledAt: string) => void;

  setTier: (tier: UserTier) => void;
  deductCredits: (amount: number) => void;
  addVideoJob: (job: VideoJob) => void;
  updateVideoJob: (id: string, updates: Partial<VideoJob>) => void;

  // Agents
  addAgent: (agent: Agent) => void;
  updateAgent: (id: string, updates: Partial<Agent>) => void;
  deleteAgent: (id: string) => void;

  reset: () => void;
}

export const useStore = create<AppState>()(
  persist(
    (set) => ({
      currentBrand: null,
      brands: [],
      campaigns: [],
      userTier: 'free',
      credits: 50, // Starter credits
      videoJobs: [],
      agents: [
        {
          id: 'a1',
          name: 'Support Sentinel',
          type: 'support',
          role: 'Customer Success Manager',
          personality: 'Empathetic, Patient, Solution-oriented',
          systemInstruction: 'You are a top-tier customer support agent for CoreDNA. Help users with platform issues.',
          guardrails: ['Never admit fault without verification', 'Do not promise refunds'],
          knowledgeBase: ['UserManual.pdf', 'PricingTier.md'],
          status: 'deployed',
          avatar: '🛡️',
          deployedUrl: 'https://api.coredna.ai/agent/a1'
        }
      ],

      setBrand: (brand) => set({ currentBrand: brand }),
      addBrand: (brand) => set((state) => ({ 
        brands: [brand, ...state.brands.filter(b => b.id !== brand.id)],
        currentBrand: brand
      })),
      updateBrand: (id, updates) => set((state) => {
        const updatedBrands = state.brands.map(b => b.id === id ? { ...b, ...updates } : b);
        const updatedCurrent = state.currentBrand?.id === id ? { ...state.currentBrand, ...updates } : state.currentBrand;
        // Need to assert type safely because Partial<BrandDNA> merged with BrandDNA is BrandDNA
        return { brands: updatedBrands, currentBrand: updatedCurrent as BrandDNA | null };
      }),
      addCampaign: (campaign) => set((state) => ({
        campaigns: [campaign, ...state.campaigns]
      })),
      updateCampaign: (id, updates) => set((state) => ({
        campaigns: state.campaigns.map(c => c.id === id ? { ...c, ...updates } : c)
      })),

      scheduleAsset: (assetId, scheduledAt) => set((state) => {
        // Find campaign containing asset
        const newCampaigns = state.campaigns.map(c => {
          const assetIndex = c.assets.findIndex(a => a.id === assetId);
          if (assetIndex > -1) {
            const updatedAssets = [...c.assets];
            updatedAssets[assetIndex] = {
              ...updatedAssets[assetIndex],
              status: 'scheduled',
              scheduledAt
            };
            return { ...c, assets: updatedAssets };
          }
          return c;
        });
        return { campaigns: newCampaigns };
      }),

      setTier: (tier) => set({ userTier: tier }),
      deductCredits: (amount) => set((state) => ({ credits: Math.max(0, state.credits - amount) })),
      addVideoJob: (job) => set((state) => ({ videoJobs: [job, ...state.videoJobs] })),
      updateVideoJob: (id, updates) => set((state) => ({
        videoJobs: state.videoJobs.map(j => j.id === id ? { ...j, ...updates } : j)
      })),

      addAgent: (agent) => set((state) => ({ agents: [agent, ...state.agents] })),
      updateAgent: (id, updates) => set((state) => ({
        agents: state.agents.map(a => a.id === id ? { ...a, ...updates } : a)
      })),
      deleteAgent: (id) => set((state) => ({
        agents: state.agents.filter(a => a.id !== id)
      })),

      reset: () => set({ currentBrand: null, brands: [], campaigns: [], videoJobs: [], agents: [] })
    }),
    {
      name: 'coredna2-storage',
    }
  )
);

import { GoogleGenAI } from "@google/genai";
import { Agent, AgentMessage } from "../types";

const API_KEY = process.env.API_KEY || ''; 

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai && API_KEY) {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  }
  return ai;
};

export const chatWithAgent = async (agent: Agent, history: AgentMessage[], userMessage: string): Promise<string> => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  // Construct System Prompt to enforce Persona and Guardrails
  const systemPrompt = `
    IDENTITY:
    Name: ${agent.name}
    Role: ${agent.role}
    Personality: ${agent.personality}

    CORE INSTRUCTIONS:
    ${agent.systemInstruction}

    GUARDRAILS (You MUST follow these strictly):
    ${agent.guardrails.length > 0 ? agent.guardrails.map(g => `- ${g}`).join('\n') : "No specific guardrails."}

    KNOWLEDGE BASE CONTEXT (Simulated):
    ${agent.knowledgeBase.length > 0 ? `Access to documents: ${agent.knowledgeBase.join(', ')}. Assume you know the contents of these files.` : "No external knowledge base."}

    INSTRUCTION:
    You are chatting with a user. Stay in character at all times. If a guardrail is violated by the user's request, politely decline or redirect.
  `;

  try {
    const chat = client.chats.create({
      model: 'gemini-2.0-flash-exp',
      config: {
        systemInstruction: systemPrompt,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({ message: userMessage });
    return result.text || "I am unable to respond at this moment.";
  } catch (e) {
    console.error("Agent chat error", e);
    return "Connection error. Please check your API key.";
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { useStore } from '../store';
import { Agent, AgentType, AgentMessage } from '../types';
import { chatWithAgent } from '../services/agentService';
import { 
  Bot, 
  Plus, 
  Settings, 
  BookOpen, 
  Shield, 
  MessageSquare, 
  Rocket, 
  Trash2, 
  Save, 
  Upload, 
  Terminal,
  User,
  Send,
  RefreshCw,
  MoreVertical
} from 'lucide-react';

const AgentForgePage = () => {
  const { agents, addAgent, updateAgent, deleteAgent } = useStore();
  const [selectedAgentId, setSelectedAgentId] = useState<string>(agents[0]?.id || '');
  const [activeTab, setActiveTab] = useState<'config' | 'knowledge' | 'test'>('config');

  // Form State
  const [formData, setFormData] = useState<Partial<Agent>>({});
  const [isDirty, setIsDirty] = useState(false);

  // Test Chat State
  const [chatHistory, setChatHistory] = useState<AgentMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize form when selection changes
  useEffect(() => {
    const agent = agents.find(a => a.id === selectedAgentId);
    if (agent) {
      setFormData(agent);
      setIsDirty(false);
      // Reset chat
      setChatHistory([{
        id: 'init',
        role: 'model',
        text: `Hello! I am ${agent.name}. How can I assist you today?`,
        timestamp: new Date().toISOString()
      }]);
    } else {
      setFormData({}); // Creating new
    }
  }, [selectedAgentId, agents]);

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chatHistory, activeTab]);

  const handleCreateNew = () => {
    const newAgent: Agent = {
      id: crypto.randomUUID(),
      name: 'New Agent',
      type: 'custom',
      role: 'Assistant',
      personality: 'Helpful',
      systemInstruction: 'You are a helpful assistant.',
      guardrails: [],
      knowledgeBase: [],
      status: 'draft',
      avatar: '🤖'
    };
    addAgent(newAgent);
    setSelectedAgentId(newAgent.id);
  };

  const handleSave = () => {
    if (selectedAgentId && formData) {
      updateAgent(selectedAgentId, formData);
      setIsDirty(false);
    }
  };

  const handleDelete = () => {
    if (confirm("Are you sure you want to delete this agent?")) {
      deleteAgent(selectedAgentId);
      if (agents.length > 1) {
        setSelectedAgentId(agents.find(a => a.id !== selectedAgentId)?.id || '');
      } else {
        // If it was the last one, we might need to create a default or handle empty state
        // For now, let's just clear selection
        setSelectedAgentId('');
      }
    }
  };

  const handleDeploy = () => {
    if (selectedAgentId) {
      updateAgent(selectedAgentId, { 
        status: 'deployed',
        deployedUrl: `https://api.coredna.ai/agent/${selectedAgentId}`
      });
      alert(`Agent deployed! Endpoint: https://api.coredna.ai/agent/${selectedAgentId}`);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isTyping) return;

    const agent = agents.find(a => a.id === selectedAgentId);
    if (!agent) return;

    const userMsg: AgentMessage = {
      id: crypto.randomUUID(),
      role: 'user',
      text: chatInput,
      timestamp: new Date().toISOString()
    };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsTyping(true);

    try {
      // Use the formData (current config) instead of saved agent to allow testing unsaved changes
      const configToTest = { ...agent, ...formData } as Agent;

      const response = await chatWithAgent(configToTest, chatHistory, userMsg.text);

      const botMsg: AgentMessage = {
        id: crypto.randomUUID(),
        role: 'model',
        text: response,
        timestamp: new Date().toISOString()
      };
      setChatHistory(prev => [...prev, botMsg]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsTyping(false);
    }
  };

  const updateField = (field: keyof Agent, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setIsDirty(true);
  };

  const addGuardrail = () => {
    const current = formData.guardrails || [];
    updateField('guardrails', [...current, 'New Guardrail']);
  };

  const updateGuardrail = (index: number, val: string) => {
    const current = [...(formData.guardrails || [])];
    current[index] = val;
    updateField('guardrails', current);
  };

  const removeGuardrail = (index: number) => {
    const current = [...(formData.guardrails || [])];
    current.splice(index, 1);
    updateField('guardrails', current);
  };

  if (agents.length === 0 && !selectedAgentId) {
     handleCreateNew(); // Auto create if empty
     return null;
  }

  const selectedAgent = agents.find(a => a.id === selectedAgentId);

  return (
    <div className="flex h-full">
      {/* SIDEBAR LIST */}
      <div className="w-72 bg-dark-surface border-r border-dark-border flex flex-col shrink-0">
         <div className="p-4 border-b border-dark-border flex justify-between items-center bg-black/20">
            <h2 className="font-bold text-white flex items-center gap-2">
              <Bot className="w-5 h-5 text-brand-500" /> Agents
            </h2>
            <button onClick={handleCreateNew} className="p-2 hover:bg-brand-600/20 hover:text-brand-500 rounded-lg text-zinc-400 transition-colors">
              <Plus className="w-4 h-4" />
            </button>
         </div>

         <div className="flex-1 overflow-y-auto p-3 space-y-2">
            {agents.map(agent => (
               <div 
                 key={agent.id}
                 onClick={() => setSelectedAgentId(agent.id)}
                 className={`p-3 rounded-lg cursor-pointer border transition-all flex items-center gap-3 ${
                    selectedAgentId === agent.id 
                      ? 'bg-brand-900/20 border-brand-500/50 text-white' 
                      : 'bg-zinc-900/50 border-zinc-800 text-zinc-400 hover:border-zinc-600'
                 }`}
               >
                  <div className="w-8 h-8 rounded-full bg-black/40 flex items-center justify-center text-lg">
                     {agent.avatar}
                  </div>
                  <div className="flex-1 min-w-0">
                     <div className="font-bold text-sm truncate">{agent.name}</div>
                     <div className="text-[10px] text-zinc-500 flex items-center gap-1">
                        {agent.status === 'deployed' && <div className="w-1.5 h-1.5 rounded-full bg-green-500" />}
                        {agent.type}
                     </div>
                  </div>
               </div>
            ))}
         </div>
      </div>

      {/* MAIN CONTENT */}
      {selectedAgent && (
        <div className="flex-1 flex flex-col min-w-0 bg-dark-bg">
           {/* Header */}
           <div className="h-16 border-b border-dark-border bg-dark-surface px-6 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                 <div className="w-10 h-10 rounded-full bg-brand-600 flex items-center justify-center text-xl shadow-lg">
                    {formData.avatar}
                 </div>
                 <div>
                    <h1 className="text-lg font-bold text-white flex items-center gap-2">
                      {formData.name}
                      {isDirty && <span className="text-[10px] bg-amber-900/30 text-amber-500 px-1.5 py-0.5 rounded border border-amber-900/50">Unsaved</span>}
                    </h1>
                    <div className="flex items-center gap-3 text-xs text-zinc-500">
                       <span className="uppercase font-bold tracking-wider">{formData.status}</span>
                       {formData.status === 'deployed' && <span className="text-green-500 flex items-center gap-1"><Rocket className="w-3 h-3" /> Live</span>}
                    </div>
                 </div>
              </div>

              <div className="flex items-center gap-3">
                 <button 
                   onClick={handleDelete}
                   className="p-2 text-zinc-500 hover:text-red-500 hover:bg-red-900/10 rounded-lg transition-colors"
                 >
                   <Trash2 className="w-5 h-5" />
                 </button>
                 <button 
                   onClick={handleSave}
                   disabled={!isDirty}
                   className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-50 text-white text-sm font-bold rounded-lg flex items-center gap-2"
                 >
                   <Save className="w-4 h-4" /> Save
                 </button>
                 <button 
                   onClick={handleDeploy}
                   className="px-4 py-2 bg-brand-600 hover:bg-brand-500 text-white text-sm font-bold rounded-lg flex items-center gap-2 shadow-lg shadow-brand-900/20"
                 >
                   <Rocket className="w-4 h-4" /> Deploy
