import { BrandDNA, WebsiteData, SiteSection } from "../types";
import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || ''; 

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai && API_KEY) {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  }
  return ai;
};

export const generateWebsiteStructure = async (brand: BrandDNA): Promise<WebsiteData> => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const prompt = `
    Act as a UX/UI Web Designer. Create content for a landing page for the brand "${brand.name}".

    Brand Context:
    Tagline: ${brand.tagline}
    Mission: ${brand.mission}
    Values: ${brand.coreValues.join(', ')}
    Visual Style: ${brand.visualIdentity.styleKeywords.join(', ')}

    Generate content for these sections:
    1. Hero (Headline, Subheadline, CTA Label)
    2. Features (3 Key features with titles and descriptions)
    3. About (Short paragraph about the mission)
    4. CTA (Final call to action)

    Return JSON structure:
    {
      "hero": { "headline": "...", "subheadline": "...", "cta": "..." },
      "features": [ { "title": "...", "desc": "..." }, { "title": "...", "desc": "..." }, { "title": "...", "desc": "..." } ],
      "about": { "title": "Our Story", "text": "..." },
      "cta": { "headline": "...", "button": "..." }
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const content = JSON.parse(response.text || '{}');

    // Map to internal structure
    const sections: SiteSection[] = [
      {
        id: 'sec_hero',
        type: 'hero',
        order: 0,
        isVisible: true,
        content: content.hero
      },
      {
        id: 'sec_features',
        type: 'features',
        order: 1,
        isVisible: true,
        content: { items: content.features }
      },
      {
        id: 'sec_about',
        type: 'about',
        order: 2,
        isVisible: true,
        content: content.about
      },
      {
        id: 'sec_cta',
        type: 'cta',
        order: 3,
        isVisible: true,
        content: content.cta
      },
      {
        id: 'sec_footer',
        type: 'footer',
        order: 4,
        isVisible: true,
        content: { copyright: `© ${new Date().getFullYear()} ${brand.name}. All rights reserved.` }
      }
    ];

    return {
      id: crypto.randomUUID(),
      brandId: brand.id,
      subdomain: brand.name.toLowerCase().replace(/[^a-z0-9]/g, '-') + '-' + Math.floor(Math.random()*1000),
      sections,
      status: 'draft'
    };

  } catch (e) {
    console.error(e);
    // Fallback
    return {
      id: crypto.randomUUID(),
      brandId: brand.id,
      subdomain: 'demo-site',
      status: 'draft',
      sections: []
    };
  }
};

export const deployWebsite = async (site: WebsiteData): Promise<string> => {
  // Simulate Vercel/Firebase deployment delay
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(`https://${site.subdomain}.coredna.sites.ai`);
    }, 2000);
  });
};

