          <div className="shrink-0 mt-0.5">{getIcon(t.type)}</div>
          <div className="flex-1">
            <h4 className="text-sm font-bold text-white mb-1">{t.title}</h4>
            <p className="text-xs text-zinc-400 leading-relaxed">{t.message}</p>
