type ToastType = 'success' | 'error' | 'info' | 'warning';

export interface ToastMessage {
  id: string;
  type: ToastType;
  title: string;
  message: string;
  duration?: number;
}

type ToastListener = (toast: ToastMessage) => void;

class ToastService {
  private listeners: ToastListener[] = [];

  subscribe(listener: ToastListener) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  notify(type: ToastType, title: string, message: string, duration = 5000) {
    const toast: ToastMessage = {
      id: crypto.randomUUID(),
      type,
      title,
      message,
      duration
    };
    this.listeners.forEach(l => l(toast));
  }

  success(title: string, message: string) {
    this.notify('success', title, message);
  }

  error(title: string, message: string) {
    this.notify('error', title, message);
  }

  info(title: string, message: string) {
    this.notify('info', title, message);
  }
}

export const toast = new ToastService();

import React, { useState, useEffect } from 'react';
import { toast, ToastMessage } from '../services/toastService';
import { X, CheckCircle, AlertCircle, Info, AlertTriangle } from 'lucide-react';

export const ToastContainer = () => {
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  useEffect(() => {
    return toast.subscribe((newToast) => {
      setToasts((prev) => [...prev, newToast]);
      if (newToast.duration) {
        setTimeout(() => {
          removeToast(newToast.id);
        }, newToast.duration);
      }
    });
  }, []);

  const removeToast = (id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  const getIcon = (type: string) => {
    switch (type) {
      case 'success': return <CheckCircle className="w-5 h-5 text-green-500" />;
      case 'error': return <AlertCircle className="w-5 h-5 text-red-500" />;
      case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-500" />;
      default: return <Info className="w-5 h-5 text-blue-500" />;
    }
  };

  return (
    <div className="fixed top-4 right-4 z-50 flex flex-col gap-3 pointer-events-none">
      {toasts.map((t) => (
        <div 
          key={t.id} 
          className="pointer-events-auto min-w-[320px] max-w-sm bg-dark-surface/90 backdrop-blur-md border border-dark-border rounded-lg shadow-2xl p-4 flex items-start gap-3 animate-in slide-in-from-right-10 fade-in duration-300"
        >
          <div className="shrink-0 mt-0.5">{getIcon(t.type)}</div>
          <div className="flex-1">
            <h4 className="text-sm font-bold text-white mb-1">{t.title}</h4>
            <p className="text-xs text-zinc-400 leading-relaxed">{t.message}</p>
          </div>
          <button 
            onClick={() => removeToast(t.id)}
            className="text-zinc-500 hover:text-white shrink-0"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      ))}
    </div>
  );
};

import React, { useState } from 'react';
import { CampaignAsset } from '../types';
import { X, Sparkles, Save, Copy, RefreshCw } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface AssetEditorProps {
  asset: CampaignAsset;
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedAsset: CampaignAsset) => void;
}

export const AssetEditor: React.FC<AssetEditorProps> = ({ asset, isOpen, onClose, onSave }) => {
  const [content, setContent] = useState(asset.content);
  const [title, setTitle] = useState(asset.title);
  const [isRewriting, setIsRewriting] = useState(false);

  if (!isOpen) return null;

  const handleRewrite = async (tone: 'professional' | 'witty' | 'shorter') => {
    setIsRewriting(true);
    try {
      // Direct call for quick edit - ideally moving this to a service in prod
      const client = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Rewrite the following marketing content to be ${tone}:

      "${content}"

      Return ONLY the rewritten text.`;

      const res = await client.models.generateContent({
        model: 'gemini-2.0-flash-exp',
        contents: prompt
      });

      if (res.text) setContent(res.text);
    } catch (e) {
      console.error(e);
    } finally {
      setIsRewriting(false);
    }
  };

  const handleSave = () => {
    onSave({ ...asset, title, content });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
      <div className="bg-dark-surface border border-dark-border rounded-xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[90vh]">
