export interface RLMStep {
  step: 'root' | 'critique' | 'refinement' | 'synthesis';
  content: string;
}

/**
 * Recursive Language Model (RLM) Executor
 * Performs a Chain-of-Thought style recursive analysis to improve quality.
 */
export const executeRLMAnalysis = async (
  prompt: string, 
  onStep?: (step: string) => void
): Promise<string> => {
  const client = getAI();
  if (!client) throw new Error("API Key missing for RLM Service");

  // Step 1: Root Analysis (Fast & Broad)
  if (onStep) onStep("Initializing Neural Core (Root Analysis)...");

  const rootResponse = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: `
      Phase 1: Root Analysis.
      Task: ${prompt}

      Provide a comprehensive initial analysis. Be broad and cover all bases.
    `
  });
  const rootText = rootResponse.text || '';

  // Step 2: Strategic Critique (The "Critic" Agent)
  if (onStep) onStep("Running Adversarial Critique...");

  const critiqueResponse = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: `
      Phase 2: Adversarial Critique.

      Review the following analysis and identify weaknesses, generic assumptions, or missing strategic depth.
      Be ruthless. Point out what makes this generic and how it could be more specific and "human".

      Analysis to Critique:
      "${rootText}"

      Output strictly the critique points.
    `
  });
  const critiqueText = critiqueResponse.text || '';

  // Step 3: Synthesis & Refinement (The "Architect" Agent)
  if (onStep) onStep("Synthesizing Final DNA Sequence...");

  const synthesisResponse = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: `
      Phase 3: Synthesis.

      Original Task: ${prompt}

      Initial Analysis: "${rootText}"
      Critique: "${critiqueText}"

      Using the critique to fix the initial analysis, generate the FINAL, high-fidelity output.
      Ensure the output is in valid JSON format as originally requested, without markdown block markers.

      The JSON must match the specific BrandDNA schema requested.
    `,
    config: {
      responseMimeType: 'application/json'
    }
  });

  return synthesisResponse.text || '{}';
};

import { BrandDNA } from "../types";
import { executeRLMAnalysis } from "./rlmService";

export const enhanceBrandExtraction = async (
  url: string, 
  description: string,
  onProgress?: (status: string) => void
): Promise<BrandDNA> => {

  const prompt = `
    Analyze the brand based on this URL: ${url} and this user description: "${description}".

    Act as a World-Class Brand Strategist (Ogilvy/McKinsey level). 
    Extract the "Core DNA" of this entity.
    If the URL is generic or not crawlable, infer the most likely brand attributes based on the name and description provided.

    You MUST return a JSON object with the following specific structure.

    Structure:
    {
      "name": "Brand Name",
      "tagline": "Powerful, short tagline",
      "mission": "Mission statement",
      "elevatorPitch": "1-sentence pitch",
      "coreValues": ["Value 1", "Value 2", "Value 3", "Value 4"],
      "keyMessaging": ["Message Pillar 1", "Message Pillar 2"],
      "targetAudience": ["Segment 1", "Segment 2"],
      "personas": [
        { "name": "Persona Name (e.g. Busy Mom)", "role": "Description", "painPoints": ["Pain 1", "Pain 2"] }
      ],
      "swot": {
        "strengths": ["Strength 1", "Strength 2"],
        "weaknesses": ["Weakness 1", "Weakness 2"],
        "opportunities": ["Opp 1", "Opp 2"],
        "threats": ["Threat 1", "Threat 2"]
      },
      "competitors": ["Competitor 1", "Competitor 2"],
      "tone": {
        "adjectives": ["Adj1", "Adj2", "Adj3"],
        "description": "Full tone description",
        "personality": "Archetype (e.g. Sage, Hero, Rebel)"
      },
      "visualIdentity": {
        "primaryColor": "Hex Code",
        "secondaryColor": "Hex Code",
        "fontPairing": "Font names (Header / Body)",
        "styleKeywords": ["Modern", "Clean", "Bold"],
        "designSystem": "Brief description of visual style"
      },
      "sonicIdentity": {
        "voiceType": "e.g. Warm, Professional",
        "musicGenre": "e.g. Lo-fi, Orchestral",
        "soundKeywords": ["Click", "Swoosh"]
      },
      "confidenceScore": 85
    }
  `;

  try {
    const jsonString = await executeRLMAnalysis(prompt, onProgress);
    const data = JSON.parse(jsonString);

    // Hydrate & Sanitize
    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      name: data.name || 'Unknown Brand',
      tagline: data.tagline || 'No tagline detected',
      mission: data.mission || '',
      elevatorPitch: data.elevatorPitch || '',
      coreValues: data.coreValues || [],
      keyMessaging: data.keyMessaging || [],
      targetAudience: data.targetAudience || [],
      personas: data.personas || [],
      swot: data.swot || { strengths: [], weaknesses: [], opportunities: [], threats: [] },
      competitors: data.competitors || [],
      tone: {
        adjectives: data.tone?.adjectives || [],
        description: data.tone?.description || '',
        personality: data.tone?.personality || 'Neutral'
      },
      visualIdentity: {
        primaryColor: data.visualIdentity?.primaryColor || '#000000',
        secondaryColor: data.visualIdentity?.secondaryColor || '#ffffff',
        fontPairing: data.visualIdentity?.fontPairing || 'Sans',
        styleKeywords: data.visualIdentity?.styleKeywords || [],
        designSystem: data.visualIdentity?.designSystem || ''
      },
      sonicIdentity: {
        voiceType: data.sonicIdentity?.voiceType || 'Neutral',
        musicGenre: data.sonicIdentity?.musicGenre || 'Ambient',
        soundKeywords: data.sonicIdentity?.soundKeywords || []
      },
      confidenceScore: data.confidenceScore || 75
    } as BrandDNA;

  } catch (e) {
    console.error("Enhanced Extraction Failed", e);
    throw e;
  }
};

