  latency: number; // ms
  successRate: number; // percentage
}

const PROVIDERS = [
  { id: 'gemini', name: 'Google Gemini API' },
  { id: 'openai', name: 'OpenAI API' },
  { id: 'anthropic', name: 'Anthropic Claude' },
  { id: 'elevenlabs', name: 'ElevenLabs Voice' },
  { id: 'runway', name: 'Runway Gen-2' },
  { id: 'n8n', name: 'n8n Automation Cloud' },
];

export const checkProviderHealth = async (): Promise<ProviderStatus[]> => {
  // Simulate health checks (real app would ping status endpoints)
  const results: ProviderStatus[] = await Promise.all(PROVIDERS.map(async (p) => {
    const latency = Math.floor(Math.random() * 150) + 20; // 20-170ms
    const r = Math.random();
    let status: ProviderStatus['status'] = 'operational';
    let successRate = 99.9;

    if (r > 0.95) {
      status = 'degraded';
      successRate = 85.0;
    } else if (r > 0.99) {
      status = 'down';
      successRate = 0;
    }

    // Force Gemini to look good
    if (p.id === 'gemini') {
      status = 'operational';
      successRate = 100;
    }

    return {
      id: p.id,
      name: p.name,
      status,
      latency,
      successRate
    };
  }));

  return results;
};

