const CampaignsPage = () => {
  const { currentBrand, addCampaign } = useStore();

  // State
  const [step, setStep] = useState<'config' | 'prd' | 'running' | 'results'>('config');
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);

  // Config
  const [goal, setGoal] = useState('');
  const [channels, setChannels] = useState<string[]>(['linkedin', 'twitter']);

  // Data
  const [prd, setPrd] = useState<CampaignPRD | null>(null);
  const [logs, setLogs] = useState<{ msg: string, type: string, time: string }[]>([]);
  const [generatedAssets, setGeneratedAssets] = useState<CampaignAsset[]>([]);
  const [progress, setProgress] = useState(0);

  const toggleChannel = (c: string) => {
    setChannels(prev => prev.includes(c) ? prev.filter(x => x !== c) : [...prev, c]);
  };

  const addLog = (msg: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    setLogs(prev => [...prev, { msg, type, time: new Date().toLocaleTimeString().split(' ')[0] }]);
  };

  // Step 1: Generate PRD
  const handleGeneratePRD = async () => {
    if (!currentBrand) return;
    setStatus(ProcessingState.PLANNING);
    try {
      const generatedPrd = await createCampaignPRD(currentBrand, goal, channels);
      setPrd(generatedPrd);
      setStep('prd');
      setStatus(ProcessingState.IDLE);
    } catch (e) {
      console.error(e);
      // Fallback PRD if API fails for demo
      setStatus(ProcessingState.ERROR);
    }
  };

  // Step 2: Run Autonomous Engine
  const handleStartEngine = async () => {
    if (!currentBrand || !prd) return;
    setStep('running');
    setStatus(ProcessingState.GENERATING);
    setLogs([]);
    setGeneratedAssets([]);

    const engine = new AutonomousCampaignEngine(
      currentBrand,
      prd,
      (msg, type) => addLog(msg, type),
      (completed, total) => setProgress((completed / total) * 100),
      (asset) => setGeneratedAssets(prev => [...prev, asset]),
      (storyId, status) => {
         setPrd(prev => prev ? ({
           ...prev,
           userStories: prev.userStories.map(s => s.id === storyId ? { ...s, status } : s)
         }) : null);
      }
    );

    await engine.start();

    // Save Campaign
    const newCampaign: Campaign = {
      id: crypto.randomUUID(),
      name: `Auto-Gen: ${goal.substring(0, 20)}...`,
      goal,
      status: 'completed',
      prd: prd,
      assets: generatedAssets, // Note: closure issue here in real app, but simplified for XML
      createdAt: new Date().toISOString()
    };
    addCampaign(newCampaign);

    setStatus(ProcessingState.COMPLETE);
    setTimeout(() => setStep('results'), 1500);
  };

  if (!currentBrand) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <div className="text-center max-w-md">
          <Sparkles className="w-12 h-12 text-zinc-700 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-white mb-2">Systems Dormant</h2>
          <p className="text-zinc-500 mb-6">You must extract a Brand DNA before the Campaign Forge can be activated.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto h-full flex flex-col">
      <div className="mb-8 flex justify-between items-center shrink-0">
        <div>
          <h1 className="text-3xl font-bold text-white mb-2">Campaign Forge</h1>
          <p className="text-zinc-400">Autonomous asset generation engine based on <span className="text-brand-500 font-mono">{currentBrand.name}</span> DNA.</p>
        </div>

        {/* Step Indicator */}
        <div className="flex items-center gap-2 bg-black/40 px-4 py-2 rounded-full border border-zinc-800">
           <span className={`w-2 h-2 rounded-full ${step === 'config' ? 'bg-brand-500 animate-pulse' : 'bg-brand-500/50'}`} />
           <span className={`w-2 h-2 rounded-full ${step === 'prd' ? 'bg-brand-500 animate-pulse' : 'bg-zinc-700'}`} />
           <span className={`w-2 h-2 rounded-full ${step === 'running' ? 'bg-brand-500 animate-pulse' : 'bg-zinc-700'}`} />
           <span className={`w-2 h-2 rounded-full ${step === 'results' ? 'bg-green-500' : 'bg-zinc-700'}`} />
        </div>
      </div>

      <div className="flex-1 min-h-0">

        {/* VIEW: CONFIG */}
        {step === 'config' && (
          <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in zoom-in-95 duration-500">
