// --- Brand Extraction ---
export const extractBrandDNA = async (url: string, description: string): Promise<BrandDNA> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Analyze the brand based on this URL: ${url} and this user description: "${description}".

    Act as a World-Class Brand Strategist (Ogilvy/McKinsey level). 
    Extract the "Core DNA" of this entity.
    If the URL is generic or not crawlable, infer the most likely brand attributes based on the name and description provided.

    You MUST return a JSON object with the following specific structure. Do not wrap in markdown code blocks.

    Structure:
    {
      "name": "Brand Name",
      "tagline": "Powerful, short tagline",
      "mission": "Mission statement",
      "elevatorPitch": "1-sentence pitch",
      "coreValues": ["Value 1", "Value 2", "Value 3", "Value 4"],
      "keyMessaging": ["Message Pillar 1", "Message Pillar 2"],
      "targetAudience": ["Segment 1", "Segment 2"],
      "personas": [
        { "name": "Persona Name (e.g. Busy Mom)", "role": "Description", "painPoints": ["Pain 1", "Pain 2"] }
      ],
      "swot": {
        "strengths": ["Strength 1", "Strength 2"],
        "weaknesses": ["Weakness 1", "Weakness 2"],
        "opportunities": ["Opp 1", "Opp 2"],
        "threats": ["Threat 1", "Threat 2"]
      },
      "competitors": ["Competitor 1", "Competitor 2"],
      "tone": {
        "adjectives": ["Adj1", "Adj2", "Adj3"],
        "description": "Full tone description",
        "personality": "Archetype (e.g. Sage, Hero, Rebel)"
      },
      "visualIdentity": {
        "primaryColor": "Hex Code",
        "secondaryColor": "Hex Code",
        "fontPairing": "Font names (Header / Body)",
        "styleKeywords": ["Modern", "Clean", "Bold"],
        "designSystem": "Brief description of visual style (e.g. 'Flat design with high contrast')"
      },
      "sonicIdentity": {
        "voiceType": "e.g. Warm, Professional, Energetic",
        "musicGenre": "e.g. Lo-fi beats, Orchestral, Minimalist electronic",
        "soundKeywords": ["Click", "Swoosh", "Soft"]
      },
      "confidenceScore": 85
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);

    // Defensive defaults to prevent map errors
    const safeData = {
      name: data.name || 'Unknown Brand',
      tagline: data.tagline || '',
      mission: data.mission || '',
      elevatorPitch: data.elevatorPitch || '',
      coreValues: Array.isArray(data.coreValues) ? data.coreValues : [],
      keyMessaging: Array.isArray(data.keyMessaging) ? data.keyMessaging : [],
      targetAudience: Array.isArray(data.targetAudience) ? data.targetAudience : [],
      personas: Array.isArray(data.personas) ? data.personas : [],
      swot: data.swot || { strengths: [], weaknesses: [], opportunities: [], threats: [] },
      competitors: Array.isArray(data.competitors) ? data.competitors : [],
      tone: {
        adjectives: Array.isArray(data.tone?.adjectives) ? data.tone.adjectives : [],
        description: data.tone?.description || '',
        personality: data.tone?.personality || 'Neutral'
      },
      visualIdentity: {
        primaryColor: data.visualIdentity?.primaryColor || '#000000',
        secondaryColor: data.visualIdentity?.secondaryColor || '#ffffff',
        fontPairing: data.visualIdentity?.fontPairing || 'Sans-Serif',
        styleKeywords: Array.isArray(data.visualIdentity?.styleKeywords) ? data.visualIdentity.styleKeywords : [],
        designSystem: data.visualIdentity?.designSystem || 'Standard'
      },
      sonicIdentity: {
        voiceType: data.sonicIdentity?.voiceType || 'Neutral',
        musicGenre: data.sonicIdentity?.musicGenre || 'Ambient',
        soundKeywords: Array.isArray(data.sonicIdentity?.soundKeywords) ? data.sonicIdentity.soundKeywords : []
      },
      confidenceScore: data.confidenceScore || 50
    };

    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      ...safeData
    } as BrandDNA;

  } catch (error) {
    console.error("Extraction failed", error);
    throw error;
  }
};

// --- PRD Generation ---
export const generatePRD = async (brand: BrandDNA, goal: string, channels: string[]): Promise<CampaignPRD> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Act as a Senior Product Manager & Marketing Strategist.
    Create a detailed Campaign PRD (Product Requirements Document) for the following:

    Brand: ${brand.name} (${brand.tagline})
    Mission: ${brand.mission}
    Goal: ${goal}
    Channels: ${channels.join(', ')}
    Target Audience: ${brand.targetAudience.join(', ')}

    Output JSON with this structure:
    {
      "overview": "High level summary of the campaign strategy",
      "campaignType": "e.g. Awareness, Conversion, Retention",
      "targetAudienceSummary": "Specific focus for this campaign",
      "userStories": [
        {
          "role": "e.g. As a potential customer / As a loyal fan",
          "desire": "I want to...",
          "benefit": "So that I...",
          "channel": "One of the selected channels",
          "acceptanceCriteria": ["Criteria 1", "Criteria 2"]
        }
      ]
    }

    Generate at least 3-5 distinct User Stories distributed across the selected channels.
  `;

  const response = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: prompt,
    config: { responseMimeType: 'application/json' }
  });

  const raw = JSON.parse(response.text || '{}');

  // Defensive check: Ensure userStories is an array
  const userStories = Array.isArray(raw.userStories) ? raw.userStories : [];

  // Hydrate with IDs and status
  raw.userStories = userStories.map((s: any) => ({
    ...s,
    id: crypto.randomUUID(),
    status: 'pending',
    acceptanceCriteria: Array.isArray(s.acceptanceCriteria) ? s.acceptanceCriteria : []
  }));

  // Fill missing fields if necessary
  if (!raw.overview) raw.overview = "Generated Campaign Strategy";
  if (!raw.campaignType) raw.campaignType = "General";
  if (!raw.targetAudienceSummary) raw.targetAudienceSummary = "Target Audience";

  return raw as CampaignPRD;
};

// --- Asset Execution ---
export const generateAssetFromStory = async (brand: BrandDNA, story: UserStory): Promise<Partial<CampaignAsset>> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Execute this User Story for Brand: ${brand.name}.

    Story: "As a ${story.role}, I want ${story.desire}, so that ${story.benefit}."
    Channel: ${story.channel}
    Acceptance Criteria: ${story.acceptanceCriteria.join(', ')}

    Brand Voice: ${brand.tone.personality} (${brand.tone.adjectives.join(', ')})
    Visual Style: ${brand.visualIdentity.styleKeywords.join(', ')}

    Generate the marketing asset content.
    Return JSON:
    {
      "title": "Headline/Subject/Hook",
      "content": "The main body content formatted for the platform",
      "imagePrompt": "A highly detailed Stable Diffusion/Midjourney prompt for the visual. Describe lighting, style, composition.",
      "hashtags": ["#tag1", "#tag2"]
    }
  `;

  const response = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: prompt,
    config: { responseMimeType: 'application/json' }
  });

  const result = JSON.parse(response.text || '{}');

  // Defensive checks
  if (!Array.isArray(result.hashtags)) result.hashtags = [];

  // Generate real image using Pollinations AI (free generative API)
  if (result.imagePrompt) {
    const encodedPrompt = encodeURIComponent(`${result.imagePrompt} ${brand.visualIdentity.styleKeywords.join(' ')} high quality`);
    result.imageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1024&height=1024&nologo=true&seed=${Math.floor(Math.random() * 10000)}`;
  }

  return result;
};

// --- Self Healing / Validation ---
export const validateAssetQuality = async (brand: BrandDNA, asset: Partial<CampaignAsset>, story: UserStory): Promise<{ score: number; issues: string[] }> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Act as a strict Brand Compliance Officer. Validate this asset.

    Brand Tone: ${brand.tone.personality}
    Story Criteria: ${story.acceptanceCriteria.join(', ')}

    Asset Title: ${asset.title}
    Asset Content: ${asset.content}

    Score this asset from 0-100 based on alignment with brand voice and story criteria.
    If score < 80, list specific issues.

    Return JSON: { "score": number, "issues": ["issue 1", "issue 2"] }
  `;

  const response = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: prompt,
    config: { responseMimeType: 'application/json' }
  });

  const result = JSON.parse(response.text || '{}');
  return {
    score: typeof result.score === 'number' ? result.score : 50,
    issues: Array.isArray(result.issues) ? result.issues : ["Validation error"]
  };
};

export const regenerateAsset = async (brand: BrandDNA, asset: Partial<CampaignAsset>, issues: string[]): Promise<Partial<CampaignAsset>> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Fix this marketing asset based on the feedback.

    Original Asset:
    Title: ${asset.title}
    Content: ${asset.content}

    Critique/Issues:
    ${issues.join('\n')}

    Brand Voice: ${brand.tone.personality}

    Return fixed JSON: { "title": "...", "content": "...", "imagePrompt": "...", "hashtags": [...] }
  `;

  const response = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: prompt,
    config: { responseMimeType: 'application/json' }
  });

  const result = JSON.parse(response.text || '{}');

  // Re-attach image generation if needed, or keep old one if prompt didn't change much
  // For simplicity, we just pass back the text updates usually, but if prompt changed:
  if (result.imagePrompt && result.imagePrompt !== asset.imagePrompt) {
     const encodedPrompt = encodeURIComponent(`${result.imagePrompt} ${brand.visualIdentity.styleKeywords.join(' ')}`);
     result.imageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1024&height=1024&nologo=true&seed=${Math.floor(Math.random() * 10000)}`;
  } else {
     result.imageUrl = asset.imageUrl;
  }

  return result;
};

// --- Chat ---
export const sonicChat = async (history: {role: 'user' | 'model', text: string}[], message: string, brandContext?: BrandDNA) => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const systemInstruction = brandContext 
    ? `You are Sonic, an advanced AI Brand Co-Pilot. You are currently analyzing the brand "${brandContext.name}". 

       Brand Context:
       - Mission: ${brandContext.mission}
       - Values: ${brandContext.coreValues.join(', ')}
       - Personality: ${brandContext.tone.personality}
       - Messaging: ${brandContext.keyMessaging.join(', ')}

       Your responses should be concise, strategic, and helpful.`
    : `You are Sonic, an advanced AI Brand Co-Pilot. Guide the user to extract a brand or create a campaign.`;

  const chat = client.chats.create({
    model: 'gemini-2.0-flash-exp',
    config: {
      systemInstruction,
    },
    history: history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }))
  });

  const result = await chat.sendMessage({ message });
  return result.text;
};

