  const contextPrompt = brand 
    ? `The user is managing a brand called "${brand.name}" which operates in the industry related to: ${brand.mission}. Target audience: ${brand.targetAudience.join(', ')}.`
    : `The user has not selected a specific brand yet. Provide general high-impact marketing/tech/business trends.`;

  const prompt = `
    ${contextPrompt}

    Act as a "Trend Pulse" engine (Real-time News & Cultural Analysis).
    Identify 3-4 "Rising Trends" that are relevant RIGHT NOW (or simulated as right now) for this context.

    For each trend, providing:
    - Topic Name
    - Category (e.g. Tech, Culture, Finance, Social Media)
    - Search Volume (simulate a realistic number, e.g. "500K+")
    - Relevance Score (0-100) based on the brand context
    - A 1-sentence summary of why it's trending.
    - 2 specific "Angles" or content ideas for the brand to leverage this trend.

    Return a JSON array of objects with this structure:
    [
      {
        "topic": "AI Agents",
        "category": "Technology",
        "volume": "1.2M+",
        "relevanceScore": 95,
        "summary": "Autonomous agents are replacing chatbots...",
        "suggestedAngles": ["How we use agents", "The future of work"]
      }
    ]
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    let rawTrends = JSON.parse(response.text || '[]');

    // Defensive: handle if LLM returns { trends: [...] } instead of [...]
    if (!Array.isArray(rawTrends)) {
       if (rawTrends.trends && Array.isArray(rawTrends.trends)) {
           rawTrends = rawTrends.trends;
       } else {
           rawTrends = [];
       }
    }

    return rawTrends.map((t: any) => ({
      id: crypto.randomUUID(),
      topic: t.topic || 'Unknown Trend',
      category: t.category || 'General',
      volume: t.volume || 'N/A',
      relevanceScore: t.relevanceScore || 50,
      summary: t.summary || '',
      suggestedAngles: Array.isArray(t.suggestedAngles) ? t.suggestedAngles : []
    })) as TrendItem[];

  } catch (error) {
    console.error("Trend Pulse failed", error);
    // Fallback data if API fails
    return [
      {
        id: 'fallback-1',
        topic: 'Minimalist Design',
        category: 'Design',
        volume: '850K',
        relevanceScore: 80,
        summary: 'Clean lines and negative space are dominating 2025 visuals.',
        suggestedAngles: ['Refresh our visual identity', 'Less is more campaign']
      }
    ];
  }
};

