export const huntLeads = async (industry: string, location: string): Promise<LeadProfile[]> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  // Since we can't actually scrape LinkedIn/Google Maps in this environment,
  // we use Gemini to "Simulate" the results of a high-tech scraper.
  const prompt = `
    Act as an advanced B2B Lead Scraper & Qualifier.
    Generate 4 realistic BUSINESS LEADS for the "${industry}" industry in "${location}".

    Make them varied in quality (some good, some struggling).
    Infer realistic vulnerabilities (e.g., bad website, low reviews, missing social presence).

    Return a JSON array of objects with this structure:
    [
      {
        "companyName": "Name",
        "website": "url",
        "rating": 3.5,
        "contactEmail": "info@domain.com",
        "techStack": ["Wordpress", "jQuery"],
        "vulnerabilities": ["Non-responsive site", "Last post 2021"],
        "opportunityScore": 85
      }
    ]
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    let rawLeads = JSON.parse(response.text || '[]');

    if (!Array.isArray(rawLeads)) {
       if (rawLeads.leads && Array.isArray(rawLeads.leads)) rawLeads = rawLeads.leads;
       else rawLeads = [];
    }

    return rawLeads.map((lead: any) => ({
      id: crypto.randomUUID(),
      industry,
      location,
      status: 'new',
      companyName: lead.companyName || 'Unknown Company',
      website: lead.website || '',
      rating: lead.rating || 0,
      contactEmail: lead.contactEmail || '',
      techStack: Array.isArray(lead.techStack) ? lead.techStack : [],
      vulnerabilities: Array.isArray(lead.vulnerabilities) ? lead.vulnerabilities : [],
      opportunityScore: lead.opportunityScore || 50
    })) as LeadProfile[];

  } catch (error) {
    console.error("Lead hunting failed", error);
    return [];
  }
};

