  }, [logs]);

  return (
    <div className="bg-black border border-zinc-800 rounded-lg p-4 h-64 overflow-y-auto font-mono text-xs shadow-inner">
      {logs.length === 0 && <span className="text-zinc-700 animate-pulse">_ Waiting for command sequence...</span>}
      {logs.map((log, i) => (
        <div key={i} className="mb-1.5 flex gap-3">
          <span className="text-zinc-600 select-none">[{log.time}]</span>
          <span className={`${
            log.type === 'error' ? 'text-red-400' :
            log.type === 'success' ? 'text-green-400' :
            log.type === 'warning' ? 'text-amber-400' :
            'text-zinc-300'
          }`}>
            {log.type === 'success' && '✓ '}
            {log.type === 'error' && '✗ '}
            {log.msg}
          </span>
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  );
};

