import { GoogleGenAI } from "@google/genai";
import { BrandDNA, CampaignAsset, UserStory, CampaignPRD, CampaignOverview } from "../types";

const API_KEY = process.env.API_KEY || ''; 

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai && API_KEY) {
    ai = new GoogleGenAI({ apiKey: API_KEY });
  }
  return ai;
};

export const checkApiKey = () => !!API_KEY;

// Helper to strip markdown code blocks from JSON response
const cleanJSON = (text: string) => {
  if (!text) return '{}';
  // Remove markdown code blocks (```json ... ```)
  return text.replace(/```json\n?|```/g, '').trim();
};

// --- Brand Extraction ---
export const extractBrandDNA = async (url: string, description: string): Promise<BrandDNA> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Analyze the brand based on this URL: ${url} and this user description: "${description}".

    Act as a World-Class Brand Strategist. 
    Extract the "Core DNA" of this entity.

    You MUST return a JSON object with the following specific structure.

    Structure:
    {
      "name": "Brand Name",
      "tagline": "Powerful, short tagline",
      "mission": "Mission statement",
      "elevatorPitch": "1-sentence pitch",
      "coreValues": ["Value 1", "Value 2", "Value 3", "Value 4"],
      "keyMessaging": ["Message Pillar 1", "Message Pillar 2"],
      "targetAudience": ["Segment 1", "Segment 2"],
      "personas": [
        { "name": "Persona Name", "role": "Description", "painPoints": ["Pain 1", "Pain 2"] }
      ],
      "swot": {
        "strengths": ["..."],
        "weaknesses": ["..."],
        "opportunities": ["..."],
        "threats": ["..."]
      },
      "competitors": ["Comp 1", "Comp 2"],
      "tone": {
        "adjectives": ["Adj1", "Adj2"],
        "description": "Full tone description",
        "personality": "Archetype"
      },
      "visualIdentity": {
        "primaryColor": "Hex Code",
        "secondaryColor": "Hex Code",
        "fontPairing": "Font names",
        "styleKeywords": ["Modern", "Bold"],
        "designSystem": "Brief description"
      },
      "sonicIdentity": {
        "voiceType": "e.g. Warm",
        "musicGenre": "e.g. Lo-fi",
        "soundKeywords": ["Click"]
      },
      "confidenceScore": 85
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const data = JSON.parse(cleanJSON(response.text || '{}'));
    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      confidenceScore: data.confidenceScore || 70,
      ...data
    } as BrandDNA;

  } catch (error) {
    console.error("Extraction failed", error);
    throw error;
  }
};

// --- Advanced PRD Generation ---
export const generateAdvancedPRD = async (
  brand: BrandDNA, 
  overview: CampaignOverview,
  channels: string[]
): Promise<CampaignPRD> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Act as a Chief Marketing Officer. Create a detailed Campaign Blueprint (PRD).

    BRAND CONTEXT:
    Name: ${brand.name}
    Mission: ${brand.mission}
    Values: ${brand.coreValues.join(', ')}
    Audience: ${brand.targetAudience.join(', ')}

    CAMPAIGN BRIEF:
    Goal: ${overview.goal}
    Timeline: ${overview.timeline}
    Target Segment: ${overview.audienceSegment}
    Constraints: ${overview.constraints.join(', ') || "None"}
    Channels: ${channels.join(', ')}

    YOUR TASK:
    1. Define specific strategies for each channel tailored to this brand.
    2. Create a sequence of "User Stories" (Tasks) that tell a cohesive narrative over the timeline.
    3. Ensure stories have clear dependencies (e.g., "Teaser" comes before "Launch").
    4. Define acceptance criteria for each story based on the Brand DNA.

    Output JSON structure:
    {
      "overview": { ...same as input... },
      "channelStrategies": [
        { 
          "channel": "instagram", 
          "postFrequency": "Daily", 
          "recommendedFormat": "Reels & Carousels", 
          "contentLength": "Short form", 
          "bestTimes": ["09:00", "18:00"] 
        }
      ],
      "sequencingPlan": "Description of how the campaign rolls out...",
      "totalAssetsTarget": 10,
      "userStories": [
        {
          "description": "Create a teaser post hinting at the new arrival",
          "channel": "instagram",
          "assetTypes": ["image", "social_post"],
          "priority": "high",
          "dayOffset": 1,
          "acceptanceCriteria": ["Must be mysterious", "Use brand colors", "No product reveal yet"],
          "dependencies": []
        },
        {
          "description": "Official Launch Announcement with Product Video",
          "channel": "linkedin",
          "assetTypes": ["social_post", "video_prompt"],
          "priority": "high",
          "dayOffset": 3,
          "acceptanceCriteria": ["Professional tone", "Clear CTA", "Highlight value prop"],
          "dependencies": [] // The ID logic will be handled by the backend, just list stories in logical order
        }
      ]
    }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const raw = JSON.parse(cleanJSON(response.text || '{}'));

    // Post-processing to add IDs and manage dependencies
    const stories = Array.isArray(raw.userStories) ? raw.userStories : [];
    const processedStories: UserStory[] = stories.map((s: any, index: number) => ({
      ...s,
      id: `story-${index + 1}`,
      status: 'pending',
      // If it's not the first story, make it dependent on the previous one for simple linear sequencing
      // In a real graph, AI would define this, but linear is safer for now.
      dependencies: index > 0 ? [`story-${index}`] : [] 
    }));

    return {
      overview,
      channelStrategies: raw.channelStrategies || [],
      sequencingPlan: raw.sequencingPlan || "Sequential rollout",
      totalAssetsTarget: processedStories.length,
      userStories: processedStories
    };

  } catch (error) {
    console.error("PRD Generation Failed", error);
    throw error;
  }
};

