    - Channel: ${story.channel}
    - Criteria: ${story.acceptanceCriteria.join(', ')}

    Review This Asset:
    - Headline: ${asset.headline}
    - Body: ${asset.content}
    - Visual Prompt: ${asset.imagePrompt}

    Score from 0-100. Be harsh.
    If score < 85, list specific, actionable issues.

    Return JSON: { "score": number, "issues": ["issue 1", "issue 2"] }
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });
    return JSON.parse(cleanJSON(response.text || '{}'));
  } catch (e) {
    return { score: 90, issues: [] }; // Fallback
  }
};

