export const sonicChat = async (history: {role: 'user' | 'model', text: string}[], message: string, brandContext?: BrandDNA) => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const systemInstruction = brandContext 
    ? `You are Sonic, a Brand Co-Pilot for ${brandContext.name}. 
       Mission: ${brandContext.mission}
       Tone: ${brandContext.tone.personality}`
    : `You are Sonic, an AI Brand Co-Pilot.`;

  const chat = client.chats.create({
    model: 'gemini-2.0-flash-exp',
    config: { systemInstruction },
    history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] }))
  });

  const result = await chat.sendMessage({ message });
  return result.text;
};

export const regenerateAsset = async (brand: BrandDNA, asset: Partial<CampaignAsset>, issues: string[]): Promise<Partial<CampaignAsset>> => {
  const client = getAI();
  if (!client) throw new Error("API Key missing");

  const prompt = `
    Fix this asset based on feedback.

    Original:
    "${asset.content}"

    Issues to Fix:
    ${issues.map(i => `- ${i}`).join('\n')}

    Brand Voice: ${brand.tone.personality}

    Return JSON with FIXED content fields: { "headline": "...", "content": "...", "imagePrompt": "..." }
  `;

  const response = await client.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: prompt,
    config: { responseMimeType: 'application/json' }
  });

  const fixed = JSON.parse(cleanJSON(response.text || '{}'));

  // Re-generate image if prompt changed
  if (fixed.imagePrompt && fixed.imagePrompt !== asset.imagePrompt) {
     const encoded = encodeURIComponent(`${fixed.imagePrompt} ${brand.visualIdentity.styleKeywords.join(' ')}`);
     fixed.imageUrl = `https://image.pollinations.ai/prompt/${encoded}?width=1080&height=1080&nologo=true&seed=${Math.floor(Math.random() * 10000)}`;
  } else {
     fixed.imageUrl = asset.imageUrl;
  }

  return { ...asset, ...fixed };
};

import { BrandDNA, CampaignAsset, UserStory, HealingReport } from "../types";
import { validateAssetStrict, regenerateAsset } from "./geminiService";

/**
 * Strict Self-Healing Loop
 * Attempts to fix an asset up to 5 times if it fails validation.
 */
export const healAsset = async (
  brand: BrandDNA,
  asset: Partial<CampaignAsset>,
  story: UserStory,
  maxRetries = 5,
  onLog?: (msg: string) => void
): Promise<{ asset: Partial<CampaignAsset>, report: HealingReport }> => {

  let currentAsset = { ...asset };
  let attempts = 0;

  // Initial Validation
  if (onLog) onLog("Running initial quality validation...");
  let validation = await validateAssetStrict(brand, currentAsset, story);

  const initialScore = validation.score;
  const history: string[] = [];

  while (validation.score < 85 && attempts < maxRetries) {
    attempts++;
    const issues = validation.issues.join(', ');
    if (onLog) onLog(`Quality Score ${validation.score}/100. Issues: ${issues}. Healing attempt ${attempts}...`);

    history.push(`Attempt ${attempts}: ${issues}`);

    // Regenerate
    try {
      const fixedAsset = await regenerateAsset(brand, currentAsset, validation.issues);
      currentAsset = { ...currentAsset, ...fixedAsset };

      // Re-validate
      validation = await validateAssetStrict(brand, currentAsset, story);
    } catch (e) {
      if (onLog) onLog("Healing failed due to API error. Skipping...");
      break;
    }
  }

  const finalReport: HealingReport = {
    attempt: attempts,
    originalScore: initialScore,
    finalScore: validation.score,
    issuesDetected: history,
    fixApplied: attempts > 0 ? "AI Refinement" : "None required",
    timestamp: new Date().toISOString()
  };

  if (onLog) {
    if (validation.score >= 85) {
      onLog(`Asset APPROVED. Final Score: ${validation.score}`);
    } else {
      onLog(`Asset accepted with warnings. Final Score: ${validation.score}`);
    }
  }

  return {
    asset: currentAsset,
    report: finalReport
  };
};

