        {/* STEP 3: Execution */}
        {step === 3 && (
          <div className="max-w-4xl mx-auto animate-in fade-in">
            <div className="bg-dark-surface border border-dark-border rounded-xl p-8 mb-8 shadow-2xl">
              <div className="flex justify-between items-end mb-6">
                <div>
                  <h2 className="text-2xl font-bold text-white mb-2">Engine Running</h2>
                  <p className="text-sm text-zinc-400">
                    <span className="text-brand-500 font-mono">AUTONOMOUS_MODE</span> :: Executing dependency graph...
                  </p>
                </div>
                <div className="text-right">
                  <div className="text-3xl font-black text-white">{Math.round(progress)}%</div>
                  <div className="text-xs text-zinc-500 uppercase">Completion</div>
                </div>
              </div>

              {/* Progress Bar */}
              <div className="h-4 bg-black/50 rounded-full overflow-hidden mb-8 border border-zinc-800">
                <div 
                  className="h-full bg-gradient-to-r from-brand-600 to-green-500 transition-all duration-500 ease-out"
                  style={{ width: `${progress}%` }}
                />
              </div>

              {/* Terminal */}
              <div className="bg-black rounded-lg border border-zinc-800 p-4 font-mono text-xs h-64 overflow-y-auto">
                {logs.map((log, i) => (
                  <div key={i} className="mb-1.5 flex gap-2">
                    <span className="text-zinc-600">[{new Date().toLocaleTimeString()}]</span>
                    <span className={
                      log.type === 'error' ? 'text-red-400' :
                      log.type === 'success' ? 'text-green-400' :
                      log.type === 'warning' ? 'text-amber-400' : 'text-zinc-300'
                    }>
                      {log.msg}
                    </span>
                  </div>
                ))}
                <div ref={scrollRef} />
              </div>
            </div>

            {/* Live Preview Grid (mini) */}
            <div className="grid grid-cols-4 gap-4">
              {generatedAssets.slice(-4).reverse().map(asset => (
                <div key={asset.id} className="opacity-50 scale-95">
                  <AssetCard asset={asset} />
                </div>
              ))}
            </div>
          </div>
        )}

        {/* STEP 4: Results */}
        {step === 4 && (
          <div className="animate-in slide-in-from-bottom-8">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-bold text-white">Campaign Ready</h2>
              <div className="flex gap-3">
                <button className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg text-sm font-bold">
                  Export JSON
                </button>
                <button className="px-4 py-2 bg-brand-600 hover:bg-brand-500 text-white rounded-lg text-sm font-bold flex items-center gap-2">
                  <Calendar className="w-4 h-4" /> Schedule All
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {generatedAssets.map(asset => (
                <AssetCard key={asset.id} asset={asset} />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

