        </div>

        <div className="flex items-center gap-4">
           <div className="flex bg-black/40 border border-zinc-800 rounded-lg p-1">
             {(['all', 'new', 'contacted'] as const).map(f => (
               <button 
                 key={f}
                 onClick={() => setFilter(f)}
                 className={`px-4 py-1.5 rounded-md text-xs font-bold uppercase transition-all ${
                   filter === f ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'
                 }`}
               >
                 {f}
               </button>
             ))}
           </div>
           <button className="p-2.5 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg transition-all" title="Export All">
             <Download className="w-5 h-5" />
           </button>
