const LeadCard: React.FC<{ lead: LeadProfile }> = ({ lead }) => {
  const { updateLead, deleteLead } = useStore();
  const [expanded, setExpanded] = useState(false);
  const [loadingPortfolio, setLoadingPortfolio] = useState(false);

  const handleGeneratePortfolio = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (lead.portfolio) {
      setExpanded(!expanded);
      return;
    }

    setExpanded(true);
    setLoadingPortfolio(true);
    try {
      const data = await generateCloserPortfolio(lead);
      updateLead(lead.id, { portfolio: data, status: 'contacted' });
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingPortfolio(false);
    }
  };

  return (
    <div className="bg-dark-surface border border-dark-border rounded-xl overflow-hidden hover:border-brand-500/30 transition-all shadow-lg animate-in fade-in zoom-in-95 duration-300">
      {/* Card Header */}
      <div 
        onClick={() => setExpanded(!expanded)}
        className="p-5 cursor-pointer bg-black/20 hover:bg-black/30 transition-colors"
      >
        <div className="flex justify-between items-start">
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center font-bold text-lg ${
              lead.opportunityScore > 80 ? 'bg-green-500/20 text-green-500' : 'bg-amber-500/20 text-amber-500'
            }`}>
              {lead.companyName.charAt(0)}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-lg font-bold text-white">{lead.companyName}</h3>
                {lead.rating > 0 && (
                  <div className="flex items-center gap-1 text-xs text-yellow-500">
                    <Star className="w-3 h-3 fill-current" /> {lead.rating}
                  </div>
                )}
              </div>
              <div className="flex items-center gap-3 text-xs text-zinc-400 mt-1">
                <span className="flex items-center gap-1"><Briefcase className="w-3 h-3" /> {lead.industry}</span>
                <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {lead.location}</span>
                {lead.website && (
                  <a href={lead.website} target="_blank" rel="noreferrer" className="text-brand-400 hover:underline flex items-center gap-1" onClick={e => e.stopPropagation()}>
                    <ExternalLink className="w-3 h-3" /> Visit
                  </a>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-6">
             <div className="text-right">
                <div className={`text-2xl font-black ${
                  lead.opportunityScore > 80 ? 'text-green-500' : 'text-amber-500'
                }`}>
                  {lead.opportunityScore}
                </div>
                <div className="text-[10px] text-zinc-500 uppercase font-bold tracking-wider">Opp. Score</div>
             </div>
             <button 
               onClick={(e) => { e.stopPropagation(); deleteLead(lead.id); }}
               className="p-2 text-zinc-600 hover:text-red-500 transition-colors"
             >
               <Trash2 className="w-4 h-4" />
             </button>
          </div>
        </div>

        {/* Vulnerabilities Pill List */}
        <div className="mt-4 flex flex-wrap gap-2">
           {lead.vulnerabilities.map((v, i) => (
             <span key={i} className="flex items-center gap-1 px-2 py-1 bg-red-900/10 border border-red-900/30 text-red-400 text-[10px] font-bold uppercase rounded-full">
               <AlertTriangle className="w-3 h-3" /> {v}
             </span>
           ))}
           <span className="flex items-center gap-1 px-2 py-1 bg-zinc-800 text-zinc-400 text-[10px] font-bold uppercase rounded-full">
              Tech: {lead.techStack.slice(0, 2).join(', ')}
           </span>
           <span className={`px-2 py-1 text-[10px] font-bold uppercase rounded-full border ${
             lead.status === 'new' ? 'bg-blue-900/20 text-blue-400 border-blue-900/30' : 'bg-green-900/20 text-green-400 border-green-900/30'
           }`}>
             {lead.status}
           </span>
        </div>
      </div>

      {/* Expanded Actions / Portfolio */}
      {expanded && (
        <div className="border-t border-dark-border animate-in slide-in-from-top-2">
          {!lead.portfolio && !loadingPortfolio && (
             <div className="p-8 text-center bg-black/10">
               <p className="text-zinc-400 mb-4 text-sm max-w-md mx-auto">Analyze this lead's vulnerabilities to generate a custom outreach strategy and closing script.</p>
               <button 
                 onClick={handleGeneratePortfolio}
                 className="px-8 py-3 bg-brand-600 hover:bg-brand-500 text-white rounded-lg font-bold flex items-center gap-2 mx-auto shadow-lg shadow-brand-900/20"
               >
                 <Zap className="w-4 h-4" /> Forge Outreach Portfolio
               </button>
             </div>
          )}

          {loadingPortfolio && (
             <div className="p-12 text-center flex flex-col items-center gap-3">
               <RefreshCw className="w-8 h-8 text-brand-500 animate-spin" />
               <p className="text-sm text-brand-400 animate-pulse font-bold uppercase tracking-widest">Designing Strategic Closer Kit...</p>
             </div>
          )}

          {lead.portfolio && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-0 divide-y lg:divide-y-0 lg:divide-x divide-dark-border">
               {/* Left: Email Strategy */}
               <div className="p-6 bg-zinc-900/30">
                 <h4 className="text-sm font-bold text-white mb-4 flex items-center gap-2">
                   <Mail className="w-4 h-4 text-blue-400" /> Outreach Campaign
                 </h4>

                 <div className="space-y-4">
                   <div>
                     <div className="text-[10px] text-zinc-500 uppercase font-bold mb-1">Subject Line</div>
                     <div className="text-sm text-white font-medium bg-black/40 p-3 rounded border border-zinc-800 flex justify-between items-center group/copy">
                       <span>{lead.portfolio.subjectLine}</span>
                       <button className="text-zinc-600 hover:text-white opacity-0 group-hover/copy:opacity-100"><Download className="w-3 h-3"/></button>
                     </div>
                   </div>

                   <div>
                     <div className="text-[10px] text-zinc-500 uppercase font-bold mb-1">Email Body</div>
                     <div className="text-sm text-zinc-300 leading-relaxed whitespace-pre-wrap bg-black/40 p-4 rounded border border-zinc-800 max-h-64 overflow-y-auto custom-scrollbar">
                       {lead.portfolio.emailBody}
                     </div>
                   </div>

                   <div>
                     <div className="text-[10px] text-zinc-500 uppercase font-bold mb-1">Automation Sequence</div>
                     <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                        {lead.portfolio.followUpSequence.map((step: string, i: number) => (
                          <div key={i} className="min-w-[140px] bg-zinc-800 p-2 rounded text-[10px] text-zinc-400 border border-zinc-700">
                            <span className="block font-bold text-brand-500 mb-1">DAY {i * 2 + 1}</span>
                            {step.slice(0, 45)}...
                          </div>
                        ))}
                     </div>
                   </div>
                 </div>
               </div>

               {/* Right: Closing & Rebuttals */}
               <div className="p-6 bg-zinc-900/30">
                  <h4 className="text-sm font-bold text-white mb-4 flex items-center gap-2">
                   <ShieldAlert className="w-4 h-4 text-purple-400" /> Objection Defense & Closing
                 </h4>

                 <div className="space-y-6">
                    <div>
                      <div className="text-[10px] text-zinc-500 uppercase font-bold mb-1">Closing Script Pivot</div>
                      <div className="bg-purple-900/10 border border-purple-500/20 p-4 rounded-lg">
                        <p className="text-sm text-zinc-200 italic leading-relaxed">"{lead.portfolio.closingScript}"</p>
                      </div>
                    </div>

                    <div className="space-y-3">
                       <div className="text-[10px] text-zinc-500 uppercase font-bold mb-1">Live Objection Handling</div>
                       {lead.portfolio.objections.map((obj: any, i: number) => (
                         <div key={i} className="bg-red-900/5 border border-red-900/20 p-3 rounded group/obj">
                            <div className="text-xs text-red-400 font-bold mb-1">STOP: "{obj.objection}"</div>
                            <div className="text-xs text-zinc-300 leading-relaxed">SOLVE: {obj.rebuttal}</div>
                         </div>
                       ))}
                    </div>

                    <div className="flex gap-3">
                      <button className="flex-1 py-3 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg font-bold text-xs flex items-center justify-center gap-2 transition-all">
                        <Download className="w-4 h-4" /> Export CSV
                      </button>
                      <button className="flex-[2] py-3 bg-green-600 hover:bg-green-500 text-white rounded-lg font-bold text-xs flex items-center justify-center gap-2 shadow-lg shadow-green-900/20 transition-all active:scale-95">
                        <PhoneCall className="w-4 h-4" /> SYNC TO CRM & LOG CALL
                      </button>
                    </div>
                 </div>
               </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const LeadHunterPage = () => {
  const { leads, addLeads } = useStore();
  const [industry, setIndustry] = useState('');
  const [location, setLocation] = useState('');
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);
  const [filter, setFilter] = useState<'all' | 'new' | 'contacted'>('all');

  const filteredLeads = useMemo(() => {
    if (filter === 'all') return leads;
    return leads.filter(l => l.status === filter);
  }, [leads, filter]);

  const handleHunt = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!industry || !location) return;

    setStatus(ProcessingState.ANALYZING);

    try {
      const results = await huntLeads(industry, location);
      addLeads(results);
      setStatus(ProcessingState.COMPLETE);
      // Auto scroll to results after a short delay
      setTimeout(() => {
        document.getElementById('results-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 500);
    } catch (e) {
      console.error(e);
      setStatus(ProcessingState.ERROR);
    }
  };

  return (
    <div className="min-h-screen">
      {/* SECTION 1: SEARCH & CONTROL PANEL */}
      <section className="p-8 max-w-7xl mx-auto border-b border-dark-border bg-dark-bg/50 backdrop-blur-sm">
        <div className="flex justify-between items-end mb-8">
          <div>
            <h1 className="text-4xl font-black text-white mb-2 flex items-center gap-3">
              <Target className="w-10 h-10 text-brand-500" /> Lead Hunter
            </h1>
            <p className="text-zinc-400">Autonomous B2B data scraping & vulnerability analysis engine.</p>
          </div>

          <div className="flex items-center gap-4">
             <div className="flex bg-black/40 border border-zinc-800 rounded-lg p-1">
               {(['all', 'new', 'contacted'] as const).map(f => (
                 <button 
                   key={f}
                   onClick={() => setFilter(f)}
                   className={`px-4 py-1.5 rounded-md text-xs font-bold uppercase transition-all ${
                     filter === f ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'
                   }`}
                 >
                   {f}
                 </button>
               ))}
             </div>
             <button className="p-2.5 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg transition-all" title="Export All">
               <Download className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="bg-dark-surface p-8 rounded-2xl border border-dark-border shadow-2xl">
          <form onSubmit={handleHunt} className="grid grid-cols-1 md:grid-cols-12 gap-6">
            <div className="md:col-span-5 relative group">
              <label className="block text-[10px] font-black text-zinc-500 uppercase mb-2 tracking-widest group-focus-within:text-brand-500 transition-colors">Target Industry</label>
              <div className="relative">
                 <Briefcase className="absolute left-3 top-3.5 w-5 h-5 text-zinc-500" />
                 <input 
                   type="text" 
                   value={industry}
                   onChange={(e) => setIndustry(e.target.value)}
                   placeholder="e.g. SaaS Founders, Dental Clinics"
                   className="w-full bg-black/40 border border-zinc-700 rounded-xl py-3.5 pl-12 pr-4 text-white focus:ring-2 focus:ring-brand-500 outline-none transition-all placeholder-zinc-700"
                   required
                 />
              </div>
            </div>

            <div className="md:col-span-4 relative group">
              <label className="block text-[10px] font-black text-zinc-500 uppercase mb-2 tracking-widest group-focus-within:text-brand-500 transition-colors">Geographic Focus</label>
              <div className="relative">
                 <MapPin className="absolute left-3 top-3.5 w-5 h-5 text-zinc-500" />
                 <input 
                   type="text" 
                   value={location}
                   onChange={(e) => setLocation(e.target.value)}
                   placeholder="e.g. Austin, TX (or Remote)"
                   className="w-full bg-black/40 border border-zinc-700 rounded-xl py-3.5 pl-12 pr-4 text-white focus:ring-2 focus:ring-brand-500 outline-none transition-all placeholder-zinc-700"
                   required
                 />
              </div>
            </div>

            <div className="md:col-span-3 flex items-end">
              <button 
                type="submit"
                disabled={status === ProcessingState.ANALYZING}
                className="w-full py-3.5 bg-gradient-to-r from-brand-600 to-brand-500 hover:from-brand-500 hover:to-brand-400 disabled:from-zinc-800 disabled:to-zinc-800 disabled:text-zinc-500 text-white font-black rounded-xl transition-all shadow-xl shadow-brand-900/20 flex items-center justify-center gap-2 group"
              >
                {status === ProcessingState.ANALYZING ? (
                  <RefreshCw className="w-5 h-5 animate-spin" />
                ) : (
                  <Search className="w-5 h-5 group-hover:scale-110 transition-transform" />
                )}
                {status === ProcessingState.ANALYZING ? 'HUNTING...' : 'INITIATE HUNT'}
              </button>
            </div>
          </form>
        </div>
      </section>

      {/* SECTION 2: INTELLIGENCE RESULTS */}
      <section id="results-section" className="p-8 max-w-7xl mx-auto pb-24">
        <div className="flex justify-between items-center mb-8 px-2">
           <div className="flex items-center gap-2">
              <span className="text-sm font-bold text-white uppercase tracking-wider flex items-center gap-2">
                Operational Results <ChevronRight className="w-4 h-4 text-zinc-600" />
              </span>
              <span className="px-3 py-1 bg-brand-900/30 text-brand-400 text-xs font-black rounded-full border border-brand-500/20">
                 {filteredLeads.length} OPPORTUNITIES DETECTED
              </span>
           </div>
           <div className="flex items-center gap-2 text-[10px] font-bold text-zinc-600 uppercase tracking-widest">
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
              Scraper Grid Online
           </div>
        </div>

        {filteredLeads.length > 0 ? (
           <div className="grid grid-cols-1 gap-6">
             {filteredLeads.map(lead => (
               <LeadCard key={lead.id} lead={lead} />
             ))}
           </div>
        ) : (
          <div className="py-32 flex flex-col items-center justify-center text-zinc-700 bg-black/10 rounded-3xl border border-dashed border-zinc-800">
            <Target className="w-20 h-20 mb-6 opacity-10" />
            <p className="text-lg font-medium opacity-50">Enter target coordinates to begin lead extraction.</p>
            <p className="text-xs opacity-30 mt-2 uppercase tracking-widest font-bold">Persistence Engine Ready</p>
          </div>
        )}
      </section>
    </div>
  );
};

