import { GoogleGenAI, Type } from "@google/genai";
import { LeadProfile, CloserPortfolio } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const huntLeads = async (industry: string, location: string): Promise<LeadProfile[]> => {
  const prompt = `
    Act as an advanced B2B Lead Scraper & Qualifier.
    Generate 5 HIGH-FIDELITY, DEEP BUSINESS LEADS for the "${industry}" industry in "${location}".

    For each lead, provide:
    1. Realistic company name and a possible website URL.
    2. Estimated annual revenue and headcount.
    3. The name of a key decision maker (Founder/CEO).
    4. A detailed "Pain Point Description" identifying specific branding, technical, or marketing failures they are likely facing.
    5. A technical stack (e.g., WordPress, outdated jQuery, no SEO meta tags).
    6. A list of 3 specific "Vulnerabilities" (e.g., "Mobile UX is broken", "No social presence since 2022").
    7. A realistic opportunity score from 0-100.

    Make the leads feel like real prospects that need urgent help.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              companyName: { type: Type.STRING },
              website: { type: Type.STRING },
              rating: { type: Type.NUMBER },
              contactEmail: { type: Type.STRING },
              techStack: { type: Type.ARRAY, items: { type: Type.STRING } },
              vulnerabilities: { type: Type.ARRAY, items: { type: Type.STRING } },
              opportunityScore: { type: Type.NUMBER },
              estimatedRevenue: { type: Type.STRING },
              headcount: { type: Type.STRING },
              painPointDescription: { type: Type.STRING },
              founderName: { type: Type.STRING }
            },
            required: ['companyName', 'website', 'opportunityScore', 'painPointDescription', 'vulnerabilities']
          }
        }
      }
    });

    const rawLeads = JSON.parse(response.text || '[]');

    return rawLeads.map((lead: any) => ({
      id: crypto.randomUUID(),
      industry,
      location,
      status: 'new',
      companyName: lead.companyName || 'Unknown Company',
      website: lead.website || '',
      rating: lead.rating || 0,
      contactEmail: lead.contactEmail || `contact@${lead.companyName.toLowerCase().replace(/\s/g, '')}.com`,
      techStack: Array.isArray(lead.techStack) ? lead.techStack : [],
      vulnerabilities: Array.isArray(lead.vulnerabilities) ? lead.vulnerabilities : [],
      opportunityScore: lead.opportunityScore || 50,
      estimatedRevenue: lead.estimatedRevenue || '$500k - $1M',
      headcount: lead.headcount || '1-10',
      painPointDescription: lead.painPointDescription || 'General branding inconsistencies.',
      founderName: lead.founderName || 'Decision Maker'
    })) as LeadProfile[];

  } catch (error) {
    console.error("Lead hunting failed", error);
    return [];
  }
};

export const generateCloserPortfolio = async (lead: LeadProfile): Promise<CloserPortfolio> => {
  const prompt = `
    Act as a World-Class Sales Strategist and High-Ticket Closer.
    Create an IRRESISTIBLE "Closer Portfolio" to sell branding/marketing services to this lead:

    LEAD DOSSIER:
    Company: ${lead.companyName}
    Industry: ${lead.industry}
    Revenue: ${lead.estimatedRevenue}
    Founder: ${lead.founderName}
    Vulnerabilities: ${lead.vulnerabilities.join(', ')}
    Deep Pain Point: ${lead.painPointDescription}

    Your mission: Generate a multi-stage outreach kit.
    1. A cold email with a "pattern interrupt" subject line and a high-empathy body that references their specific pain points.
    2. A closing script for a 15-minute "Exploration Call" that uses the "Challenger Sale" methodology.
    3. A list of 3 likely objections (budget, time, trust) with sophisticated rebuttals.
    4. A 3-step automation follow-up sequence.

    The content MUST be in-depth, professional, and actionable. No generic placeholders.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            subjectLine: { type: Type.STRING },
            emailBody: { type: Type.STRING },
            closingScript: { type: Type.STRING },
            objections: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  objection: { type: Type.STRING },
                  rebuttal: { type: Type.STRING }
                }
              }
            },
            followUpSequence: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ['subjectLine', 'emailBody', 'closingScript', 'objections', 'followUpSequence']
        }
      }
    });

    const data = JSON.parse(response.text || '{}');
    return data as CloserPortfolio;
  } catch (error) {
    console.error("Portfolio generation failed", error);
    throw error;
  }
};

