export const extractBrandDNA = async (url: string, description: string): Promise<BrandDNA> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Analyze the brand based on this URL: ${url} and this user description: "${description}".
    Extract the "Core DNA" of this entity as a world-class strategist.
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            tagline: { type: Type.STRING },
            mission: { type: Type.STRING },
            elevatorPitch: { type: Type.STRING },
            coreValues: { type: Type.ARRAY, items: { type: Type.STRING } },
            keyMessaging: { type: Type.ARRAY, items: { type: Type.STRING } },
