export const generateAssetTextFromStory = async (brand: BrandDNA, story: UserStory): Promise<Partial<CampaignAsset>> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const prompt = `
    Generate high-converting marketing content for ${brand.name}.
    Task: ${story.description}
    Channel: ${story.channel}
    Criteria: ${story.acceptanceCriteria.join(', ')}
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            headline: { type: Type.STRING },
            content: { type: Type.STRING },
            cta: { type: Type.STRING },
            hashtags: { type: Type.ARRAY, items: { type: Type.STRING } },
            imagePrompt: { type: Type.STRING },
            videoPrompt: { type: Type.STRING },
            emailSubject: { type: Type.STRING }
          }
        }
      }
    });

    const result = JSON.parse(response.text || '{}');

    return {
      title: result.headline || 'Untitled Asset',
      headline: result.headline,
      content: result.content,
      cta: result.cta,
      hashtags: result.hashtags || [],
      imagePrompt: result.imagePrompt,
      videoPrompt: result.videoPrompt,
      emailSubject: result.emailSubject
    };
  } catch (error) {
    console.error("Asset Gen Failed", error);
    throw error;
  }
};

// --- Actual Image Generation (Gemini 2.5 Flash Image) ---
export const generateCampaignImage = async (prompt: string, brand: BrandDNA): Promise<string> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const enhancedPrompt = `High-end commercial photography for ${brand.name}. Style: ${brand.visualIdentity.styleKeywords.join(', ')}. Scene: ${prompt}. Colors: ${brand.visualIdentity.primaryColor}, ${brand.visualIdentity.secondaryColor}. 4k, professional lighting, photorealistic.`;

  try {
    // Corrected contents parameter to follow the required format for multimodal/image generation
    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: enhancedPrompt }] },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    // Find the image part in candidates
    for (const candidate of response.candidates || []) {
      for (const part of candidate.content.parts || []) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    // Fallback to pollinations if Gemini fails to return an image part
    return `https://image.pollinations.ai/prompt/${encodeURIComponent(enhancedPrompt)}?width=1080&height=1080&nologo=true&seed=${Math.floor(Math.random() * 1000)}`;
  } catch (error) {
    console.error("Image generation failed", error);
    return `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=1080&height=1080&nologo=true`;
  }
};

