export const chatWithAgent = async (agent: Agent, history: AgentMessage[], userMessage: string): Promise<string> => {

  // --- SPECIALIZED AGENT ROUTING ---

  // 1. Confucius Code Agent (CCA) - Uses Recursive Language Models (RLM)
  if (agent.id === 'cca-1') {
    try {
      // CCA ignores standard chat history to focus purely on the deep structural query via RLM
      const wisdom = await consultConfucius(userMessage);

      return `
> *"${wisdom.aphorism}"*

**🏛️ Architectural Advice:**
${wisdom.architecturalAdvice}

**📜 Technical Directives:**
${wisdom.technicalDirectives.map(d => `- ${d}`).join('\n')}

*(Harmony Score: ${wisdom.harmonyScore}/100)*
      `.trim();
    } catch (e) {
      console.error("CCA Error", e);
      return "The Tao is currently obscured by a system error. Please try again.";
    }
  }

  // 2. Ralph (Snark Tank) - Uses GitHub Tools + Cynical Persona
  if (agent.id === 'ralph-1') {
    const lowerMsg = userMessage.toLowerCase();

    // Tool: Code Review / Roast
    if (lowerMsg.includes('review') || lowerMsg.includes('roast') || lowerMsg.includes('check this code')) {
       const review = await githubService.reviewPullRequest(userMessage);
       return `
**🔥 Snark Score: ${review.score}/10**

${review.roast}
       `.trim();
    }

    // Tool: Commit Message Gen
    if (lowerMsg.includes('commit message') || lowerMsg.includes('git commit')) {
       // Extract imaginary changes from the user prompt
       const changes = [userMessage.replace(/commit message|git commit/gi, '').trim() || 'legacy code updates'];
       const commitMsg = await githubService.generateSnarkyCommitMessage(changes);
       return `\`git commit -m "${commitMsg}"\``;
    }

    // If no specific tool triggered, fall through to standard LLM but ensure the persona is active
  }

  // --- STANDARD AGENT CHAT (Gemini) ---

  const client = getAI();
  if (!client) throw new Error("API Key missing");

  // Construct System Prompt
  const systemPrompt = `
    IDENTITY:
    Name: ${agent.name}
    Role: ${agent.role}
    Personality: ${agent.personality}

    CORE INSTRUCTIONS:
    ${agent.systemInstruction}

    GUARDRAILS:
    ${agent.guardrails.length > 0 ? agent.guardrails.map(g => `- ${g}`).join('\n') : "No specific guardrails."}

    CONTEXT:
    ${agent.knowledgeBase.length > 0 ? `Has access to: ${agent.knowledgeBase.join(', ')}` : ""}

    INSTRUCTION:
    Stay strictly in character.
  `;

  try {
    const chat = client.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: systemPrompt,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({ message: userMessage });
    return result.text || "I am unable to respond at this moment.";
  } catch (e) {
    console.error("Agent chat error", e);
    return "Connection error. Please check your API key.";
  }
};

