    Extract the "Core DNA" of this entity as a world-class strategist.
  `;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            tagline: { type: Type.STRING },
            mission: { type: Type.STRING },
            elevatorPitch: { type: Type.STRING },
            coreValues: { type: Type.ARRAY, items: { type: Type.STRING } },
            keyMessaging: { type: Type.ARRAY, items: { type: Type.STRING } },
            targetAudience: { type: Type.ARRAY, items: { type: Type.STRING } },
            personas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  role: { type: Type.STRING },
                  painPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            },
            swot: {
              type: Type.OBJECT,
              properties: {
                strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                opportunities: { type: Type.ARRAY, items: { type: Type.STRING } },
                threats: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            competitors: { type: Type.ARRAY, items: { type: Type.STRING } },
            tone: {
              type: Type.OBJECT,
              properties: {
                adjectives: { type: Type.ARRAY, items: { type: Type.STRING } },
                description: { type: Type.STRING },
                personality: { type: Type.STRING }
              }
            },
            visualIdentity: {
              type: Type.OBJECT,
              properties: {
                primaryColor: { type: Type.STRING },
                secondaryColor: { type: Type.STRING },
                fontPairing: { type: Type.STRING },
                styleKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
                designSystem: { type: Type.STRING }
              }
            },
            sonicIdentity: {
              type: Type.OBJECT,
              properties: {
                voiceType: { type: Type.STRING },
                musicGenre: { type: Type.STRING },
                soundKeywords: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            confidenceScore: { type: Type.NUMBER }
          }
        }
      }
    });

    const data = JSON.parse(response.text || '{}');
    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      confidenceScore: data.confidenceScore || 85,
      ...data
    } as BrandDNA;
  } catch (error) {
    console.error("Extraction failed", error);
    throw error;
  }
};

