// --- Actual Image Generation (Gemini 2.5 Flash Image) ---
export const generateCampaignImage = async (prompt: string, brand: BrandDNA): Promise<string> => {
  const client = getAI();
  if (!client) throw new Error("API Key not found");

  const enhancedPrompt = `Commercial professional photography. Brand: ${brand.name}. Aesthetic: ${brand.visualIdentity.styleKeywords.join(', ')}. Color Palette: ${brand.visualIdentity.primaryColor}, ${brand.visualIdentity.secondaryColor}. Subject: ${prompt}. High resolution, clean composition, studio lighting.`;

  try {
    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: enhancedPrompt }] },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    // Find the image part in candidates
    for (const candidate of response.candidates || []) {
      for (const part of candidate.content.parts || []) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    // Fallback if image data is missing
    return `https://image.pollinations.ai/prompt/${encodeURIComponent(enhancedPrompt)}?width=1080&height=1080&nologo=true&seed=${Math.floor(Math.random() * 1000)}`;
  } catch (error) {
    console.error("Image generation failed", error);
    return `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=1080&height=1080&nologo=true`;
  }
};

