// --- Main Page ---

const CampaignsPage = () => {
  const { currentBrand, campaigns, addCampaign } = useStore();
  const [step, setStep] = useState(1);
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);
  const [healingCycles, setHealingCycles] = useState(3);
  const [view, setView] = useState<'forge' | 'archive'>('forge');

  // Brief State
  const [overview, setOverview] = useState<CampaignOverview>({
    name: '',
    goal: 'Brand Awareness',
    audienceSegment: currentBrand?.targetAudience[0] || 'General',
    timeline: '7 Days',
    constraints: []
  });
  const [channels, setChannels] = useState<string[]>(['instagram', 'linkedin']);
  const [customConstraint, setCustomConstraint] = useState('');

  // PRD State
  const [prd, setPrd] = useState<CampaignPRD | null>(null);

  // Execution State
  const [logs, setLogs] = useState<{msg: string, type: string}[]>([]);
  const [generatedAssets, setGeneratedAssets] = useState<CampaignAsset[]>([]);
  const [progress, setProgress] = useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const handleAddConstraint = () => {
    if (customConstraint) {
      setOverview(prev => ({ ...prev, constraints: [...prev.constraints, customConstraint] }));
      setCustomConstraint('');
    }
  };

  const handleGeneratePRD = async () => {
    if (!currentBrand) return;
    setStatus(ProcessingState.PLANNING);
    try {
      const generatedPrd = await createCampaignPRD(currentBrand, overview, channels);
      setPrd(generatedPrd);
      setStep(2);
      setStatus(ProcessingState.IDLE);
    } catch (e) {
      console.error(e);
      setStatus(ProcessingState.ERROR);
    }
  };

  const handleStartEngine = async () => {
    if (!currentBrand || !prd) return;
    setStep(3);
    setStatus(ProcessingState.GENERATING);
    setGeneratedAssets([]);

    const localAssets: CampaignAsset[] = [];

    const engine = new AutonomousCampaignEngine(
      currentBrand,
      prd,
      (msg, type) => setLogs(prev => [...prev, { msg, type: type || 'info' }]),
      (completed, total) => setProgress((completed / total) * 100),
      (asset) => {
        localAssets.push(asset);
        setGeneratedAssets([...localAssets]);
      },
      (storyId, status) => {},
      healingCycles
    );

    await engine.start();

    const newCampaign: Campaign = {
      id: crypto.randomUUID(),
      name: overview.name || 'Untitled Campaign',
      goal: overview.goal,
      status: 'completed',
      prd: prd,
      assets: localAssets,
      createdAt: new Date().toISOString()
    };
    addCampaign(newCampaign);

    setStatus(ProcessingState.COMPLETE);
    setTimeout(() => setStep(4), 1000);
  };

  if (!currentBrand) {
    return (
      <div className="h-full flex items-center justify-center p-8 text-center">
        <div className="max-w-md bg-dark-surface p-12 rounded-[3rem] border border-dark-border shadow-2xl animate-in zoom-in-95">
          <Sparkles className="w-16 h-16 text-zinc-800 mx-auto mb-6" />
          <h2 className="text-2xl font-black text-white uppercase tracking-tighter mb-4">No Brand DNA Detected</h2>
          <p className="text-zinc-500 text-sm font-medium leading-relaxed mb-8">The forge requires a strategic brand blueprint to generate campaign narratives. Please extract a brand essence first.</p>
          <button className="px-8 py-3 bg-brand-600 hover:bg-brand-500 text-white rounded-xl font-black uppercase tracking-widest text-xs transition-all shadow-xl shadow-brand-900/20">Go to Extraction</button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto min-h-full flex flex-col">
      <div className="mb-10 flex justify-between items-end">
        <div>
          <h1 className="text-5xl font-black text-white mb-2 tracking-tighter uppercase">CAMPAIGN FORGE</h1>
          <p className="text-zinc-500 font-bold tracking-widest uppercase text-[10px]">Autonomous Multi-Touch Narrative Orchestration</p>
        </div>
        <div className="flex bg-black/40 border border-zinc-800 rounded-xl p-1.5">
           <button 
             onClick={() => setView('forge')}
             className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${view === 'forge' ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-600 hover:text-zinc-400'}`}
           >
             Forge New
           </button>
           <button 
             onClick={() => setView('archive')}
             className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${view === 'archive' ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-600 hover:text-zinc-400'}`}
           >
             Vault ({campaigns.length})
           </button>
        </div>
      </div>

      {view === 'forge' ? (
        <>
          <StepIndicator current={step} steps={['Brief', 'Blueprint', 'Forge', 'Deploy']} />

          <div className="flex-1">
            {/* STEP 1: BRIEF */}
            {step === 1 && (
              <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-12 gap-8 animate-in slide-in-from-bottom-4">
                <div className="md:col-span-8 bg-dark-surface border border-dark-border rounded-3xl p-10 shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-brand-500/5 blur-[60px] rounded-full pointer-events-none" />
                  <h2 className="text-xl font-black text-white mb-10 uppercase tracking-tighter flex items-center gap-3 border-b border-zinc-800 pb-4">
                    <Target className="w-6 h-6 text-brand-500" /> Strategic Campaign Brief
                  </h2>

                  <div className="space-y-8">
                    <div>
                      <label className="block text-[10px] font-black text-zinc-600 uppercase mb-3 tracking-[0.2em] pl-1">Campaign Operational ID</label>
                      <input 
                        type="text" 
                        value={overview.name}
                        onChange={(e) => setOverview({...overview, name: e.target.value})}
                        placeholder="e.g. OPERATION_NEON_FALL"
                        className="w-full bg-black/40 border border-zinc-800 rounded-2xl py-4 px-6 text-white font-bold focus:ring-2 focus:ring-brand-500 outline-none transition-all placeholder-zinc-800"
                      />
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                      <div>
                        <label className="block text-[10px] font-black text-zinc-600 uppercase mb-3 tracking-[0.2em] pl-1">Target KPI / Objective</label>
