                        </select>
                      </div>
                    </div>

                    <div>
                      <label className="block text-[10px] font-black text-zinc-600 uppercase mb-4 tracking-[0.2em] pl-1">Deployment Matrix (Channels)</label>
                      <div className="flex flex-wrap gap-3">
                        {['instagram', 'linkedin', 'twitter', 'email', 'tiktok', 'blog'].map(c => (
                          <button
                            key={c}
                            onClick={() => setChannels(prev => prev.includes(c) ? prev.filter(x => x !== c) : [...prev, c])}
