                      </div>
                    </div>

                    <div>
                      <label className="block text-[10px] font-black text-zinc-600 uppercase mb-4 tracking-[0.2em] pl-1">Operational Constraints</label>
                      <div className="flex gap-3 mb-4">
                        <input 
                          type="text"
                          value={customConstraint}
                          onChange={(e) => setCustomConstraint(e.target.value)}
                          placeholder="e.g. NO_EMOJIS, NO_STOCK_PHOTOS..."
                          className="flex-1 bg-black/40 border border-zinc-800 rounded-2xl py-4 px-6 text-sm text-white font-bold focus:ring-2 focus:ring-brand-500 outline-none placeholder-zinc-800"
                          onKeyDown={(e) => e.key === 'Enter' && handleAddConstraint()}
                        />
                        <button onClick={handleAddConstraint} className="p-4 bg-zinc-800 rounded-2xl hover:bg-zinc-700 text-white transition-all shadow-lg active:scale-95"><Plus className="w-6 h-6"/></button>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        {overview.constraints.map((c, i) => (
                          <span key={i} className="px-4 py-2 bg-red-950/20 text-red-400 text-[9px] font-black uppercase rounded-lg border border-red-900/30 flex items-center gap-3 tracking-widest">
                            {c} <button onClick={() => setOverview(prev => ({...prev, constraints: prev.constraints.filter((_, idx) => idx !== i)}))}><X className="w-3 h-3 hover:text-white" /></button>
                          </span>
                        ))}
                      </div>
                    </div>

                    <button 
                      onClick={handleGeneratePRD}
                      disabled={status === ProcessingState.PLANNING}
                      className="w-full py-5 bg-gradient-to-r from-brand-700 via-brand-600 to-brand-500 hover:scale-[1.01] text-white font-black rounded-2xl shadow-2xl flex items-center justify-center gap-4 transition-all h-[64px]"
                    >
                      {status === ProcessingState.PLANNING ? <RefreshCw className="w-6 h-6 animate-spin" /> : <Scroll className="w-6 h-6" />}
                      <span className="tracking-[0.2em] uppercase text-xs">{status === ProcessingState.PLANNING ? 'INITIALIZING BLUEPRINT...' : 'GENERATE CAMPAIGN BLUEPRINT'}</span>
                    </button>
                  </div>
                </div>

                <div className="md:col-span-4 space-y-6">
                   <div className="bg-dark-surface border border-dark-border rounded-3xl p-8 shadow-xl">
                     <h3 className="text-[10px] font-black text-white uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
