interface ValidationResult {
  isValid: boolean;
  score: number; // 0-100
  critique: string;
  violations: string[];
}

export const validateBrandAlignment = async (
  content: string, 
  brand: BrandDNA
): Promise<ValidationResult> => {
  const ai = getAI();
  const prompt = `
    Act as the Chief Brand Officer for "${brand.name}".

    Evaluate the following content against our Brand DNA.

    Brand Guidelines:
    - Tone: ${brand.tone.personality} (${brand.tone.adjectives.join(', ')})
    - Values: ${brand.coreValues.join(', ')}
    - Mission: ${brand.mission}

    Content to Review:
    "${content}"

    Return a JSON object:
    {
      "score": number (0-100),
      "critique": "Short summary of why",
      "violations": ["List specific misalignments or 'None'"]
    }
  `;

  try {
    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });

    const data = JSON.parse(result.text || '{}');

    return {
      isValid: data.score >= 80,
      score: data.score || 0,
      critique: data.critique || 'Validation failed',
      violations: data.violations || []
    };
  } catch (e) {
    console.error("Brand validation failed", e);
    return {
      isValid: false,
      score: 0,
      critique: "System error during validation",
      violations: ["System offline"]
    };
  }
};

import { GoogleGenAI } from "@google/genai";
import { BrandDNA } from "../types";

const getAI = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

type PolishMode = 'shorten' | 'expand' | 'professional' | 'witty' | 'seo-optimize' | 'grammar-fix';

export const polishContent = async (
  content: string, 
  mode: PolishMode, 
  brand?: BrandDNA
): Promise<string> => {
  const ai = getAI();
  const brandContext = brand 
    ? `Ensure the output matches this Brand Voice: ${brand.tone.personality} (${brand.tone.adjectives.join(', ')}).`
    : '';

  let instruction = '';
  switch (mode) {
    case 'shorten': instruction = 'Make this text 30% shorter while keeping the core message.'; break;
    case 'expand': instruction = 'Expand this text with more detail and examples. Make it 25% longer.'; break;
    case 'professional': instruction = 'Rewrite this to sound ultra-professional, corporate, and trustworthy.'; break;
    case 'witty': instruction = 'Rewrite this to be witty, clever, and engaging. Use humor if appropriate.'; break;
    case 'seo-optimize': instruction = 'Optimize this text for SEO. Include relevant keywords naturally.'; break;
    case 'grammar-fix': instruction = 'Fix any grammar, spelling, or punctuation errors. Do not change the tone.'; break;
  }

  const prompt = `
    Task: ${instruction}
    ${brandContext}

    Input Text:
    "${content}"

    Output ONLY the rewritten text.
  `;

  try {
    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt
    });
    return result.text || content;
  } catch (e) {
    console.error("Refinement failed", e);
    return content;
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { LeadProfile, CloserPortfolio } from "../types";

export const huntLeads = async (industry: string, location: string): Promise<LeadProfile[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `
    Act as an advanced B2B Lead Scraper & Qualifier.
    Generate 5 HIGH-FIDELITY, DEEP BUSINESS LEADS for the "${industry}" industry in "${location}".

    For each lead, provide:
    1. Realistic company name and a possible website URL.
    2. Estimated annual revenue and headcount.
    3. The name of a key decision maker (Founder/CEO).
    4. A detailed "Pain Point Description" identifying specific branding, technical, or marketing failures they are likely facing.
    5. A technical stack (e.g., WordPress, outdated jQuery, no SEO meta tags).
    6. A list of 3 specific "Vulnerabilities" (e.g., "Mobile UX is broken", "No social presence since 2022").
    7. A realistic opportunity score from 0-100.

    Make the leads feel like real prospects that need urgent help.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              companyName: { type: Type.STRING },
              website: { type: Type.STRING },
              rating: { type: Type.NUMBER },
              contactEmail: { type: Type.STRING },
              techStack: { type: Type.ARRAY, items: { type: Type.STRING } },
              vulnerabilities: { type: Type.ARRAY, items: { type: Type.STRING } },
              opportunityScore: { type: Type.NUMBER },
              estimatedRevenue: { type: Type.STRING },
              headcount: { type: Type.STRING },
              painPointDescription: { type: Type.STRING },
              founderName: { type: Type.STRING }
            },
            required: ['companyName', 'website', 'opportunityScore', 'painPointDescription', 'vulnerabilities']
          }
        }
      }
    });

    const rawLeads = JSON.parse(response.text || '[]');

    return rawLeads.map((lead: any) => ({
      id: crypto.randomUUID(),
      industry,
      location,
      status: 'new',
      companyName: lead.companyName || 'Unknown Company',
      website: lead.website || '',
      rating: lead.rating || 0,
      contactEmail: lead.contactEmail || `contact@${lead.companyName.toLowerCase().replace(/\s/g, '')}.com`,
      techStack: Array.isArray(lead.techStack) ? lead.techStack : [],
      vulnerabilities: Array.isArray(lead.vulnerabilities) ? lead.vulnerabilities : [],
      opportunityScore: lead.opportunityScore || 50,
      estimatedRevenue: lead.estimatedRevenue || '$500k - $1M',
      headcount: lead.headcount || '1-10',
      painPointDescription: lead.painPointDescription || 'General branding inconsistencies.',
      founderName: lead.founderName || 'Decision Maker'
    })) as LeadProfile[];

  } catch (error) {
    console.error("Lead hunting failed", error);
    return [];
  }
};

