import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { BrandDNA, Campaign, UserTier, VideoJob, Agent, LeadProfile, ProviderConfig } from './types';

interface AppState {
  currentBrand: BrandDNA | null;
  brands: BrandDNA[];
  campaigns: Campaign[];
  leads: LeadProfile[];
  userTier: UserTier;
  credits: number;
  videoJobs: VideoJob[];
  agents: Agent[];
  providers: ProviderConfig;

  setBrand: (brand: BrandDNA) => void;
  addBrand: (brand: BrandDNA) => void;
  updateBrand: (id: string, updates: Partial<BrandDNA>) => void;
  addCampaign: (campaign: Campaign) => void;
  updateCampaign: (campaignId: string, updates: Partial<Campaign>) => void;

  // Leads
  addLeads: (newLeads: LeadProfile[]) => void;
  updateLead: (id: string, updates: Partial<LeadProfile>) => void;
  deleteLead: (id: string) => void;

  // Scheduling
  scheduleAsset: (assetId: string, scheduledAt: string) => void;

  setTier: (tier: UserTier) => void;
  deductCredits: (amount: number) => void;
  addVideoJob: (job: VideoJob) => void;
  updateVideoJob: (id: string, updates: Partial<VideoJob>) => void;

  // Agents
  addAgent: (agent: Agent) => void;
  updateAgent: (id: string, updates: Partial<Agent>) => void;
  deleteAgent: (id: string) => void;

  // Providers
  updateProviders: (updates: Partial<ProviderConfig>) => void;
  setApiKey: (provider: keyof ProviderConfig['keys'], key: string) => void;

  reset: () => void;
}

export const useStore = create<AppState>()(
  persist(
    (set) => ({
      currentBrand: null,
      brands: [],
      campaigns: [],
      leads: [],
      userTier: 'pro',
      credits: 500,
      videoJobs: [],
      agents: [],
      providers: {
        activeLLM: 'gemini',
        activeImage: 'gemini',
        activeVideo: 'veo',
        activeWorkflow: 'n8n',
        keys: {
          gemini: process.env.API_KEY || ''
        }
      },

      setBrand: (brand) => set({ currentBrand: brand }),
      addBrand: (brand) => set((state) => ({ 
        brands: [brand, ...state.brands.filter(b => b.id !== brand.id)],
        currentBrand: brand
      })),
      updateBrand: (id, updates) => set((state) => {
        const updatedBrands = state.brands.map(b => b.id === id ? { ...b, ...updates } : b);
        const updatedCurrent = state.currentBrand?.id === id ? { ...state.currentBrand, ...updates } : state.currentBrand;
        return { brands: updatedBrands, currentBrand: updatedCurrent as BrandDNA | null };
      }),
      addCampaign: (campaign) => set((state) => ({
        campaigns: [campaign, ...state.campaigns]
      })),
      updateCampaign: (id, updates) => set((state) => ({
        campaigns: state.campaigns.map(c => c.id === id ? { ...c, ...updates } : c)
      })),

      addLeads: (newLeads) => set((state) => ({ leads: [...newLeads, ...state.leads] })),
      updateLead: (id, updates) => set((state) => ({
        leads: state.leads.map(l => l.id === id ? { ...l, ...updates } : l)
      })),
      deleteLead: (id) => set((state) => ({
        leads: state.leads.filter(l => l.id !== id)
      })),

      scheduleAsset: (assetId, scheduledAt) => set((state) => {
        const newCampaigns = state.campaigns.map(c => {
          const assetIndex = c.assets.findIndex(a => a.id === assetId);
          if (assetIndex > -1) {
            const updatedAssets = [...c.assets];
            updatedAssets[assetIndex] = {
              ...updatedAssets[assetIndex],
              metadata: { ...updatedAssets[assetIndex].metadata, status: 'approved', scheduledAt }
            };
            return { ...c, assets: updatedAssets };
          }
          return c;
        });
        return { campaigns: newCampaigns };
      }),

      setTier: (tier) => set({ userTier: tier }),
      deductCredits: (amount) => set((state) => ({ credits: Math.max(0, state.credits - amount) })),
      addVideoJob: (job) => set((state) => ({ videoJobs: [job, ...state.videoJobs] })),
      updateVideoJob: (id, updates) => set((state) => ({
        videoJobs: state.videoJobs.map(j => j.id === id ? { ...j, ...updates } : j)
      })),

      addAgent: (agent) => set((state) => ({ agents: [agent, ...state.agents] })),
      updateAgent: (id, updates) => set((state) => ({
        agents: state.agents.map(a => a.id === id ? { ...a, ...updates } : a)
      })),
      deleteAgent: (id) => set((state) => ({
        agents: state.agents.filter(a => a.id !== id)
      })),

      updateProviders: (updates) => set((state) => ({
        providers: { ...state.providers, ...updates }
      })),
      setApiKey: (provider, key) => set((state) => ({
        providers: {
          ...state.providers,
          keys: { ...state.providers.keys, [provider]: key }
        }
      })),

      reset: () => set({ currentBrand: null, brands: [], campaigns: [], videoJobs: [], agents: [], leads: [] })
    }),
    {
      name: 'coredna2-storage-v2',
    }
  )
);

import { GoogleGenAI, Type } from "@google/genai";
import { useStore } from "../store";

export interface TextGenerationParams {
  systemInstruction?: string;
  prompt: string;
  responseMimeType?: string;
  responseSchema?: any;
}

export const universalAiService = {
  /**
   * Universal Text Generation Router
   */
  async generateText(params: TextGenerationParams): Promise<string> {
    const { providers } = useStore.getState();
    const { activeLLM, keys } = providers;

    switch (activeLLM) {
      case 'openai':
        return await this.generateOpenAI(params, keys.openai);
      case 'anthropic':
        return await this.generateAnthropic(params, keys.anthropic);
      case 'gemini':
      default:
        return await this.generateGemini(params, keys.gemini || process.env.API_KEY || '');
    }
  },

  /**
   * Universal Image Generation Router
   */
  async generateImage(prompt: string): Promise<string> {
    const { providers } = useStore.getState();
    const { activeImage, keys } = providers;

    switch (activeImage) {
      case 'openai':
        return await this.generateDallE(prompt, keys.openai);
      case 'stability':
        return await this.generateStability(prompt, keys.stability);
      case 'gemini':
      default:
        return await this.generateGeminiImage(prompt, keys.gemini || process.env.API_KEY || '');
    }
  },

  // --- Gemini Implementation (SDK) ---

  async generateGemini(params: TextGenerationParams, key: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: params.prompt,
      config: {
        systemInstruction: params.systemInstruction,
        responseMimeType: params.responseMimeType,
        responseSchema: params.responseSchema
      }
    });
    return response.text || '';
  },

  async generateGeminiImage(prompt: string, key: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    });
    for (const candidate of response.candidates || []) {
      for (const part of candidate.content.parts || []) {
        if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data returned from Gemini");
  },

  // --- OpenAI Implementation (REST) ---

  async generateOpenAI(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new Error("OpenAI API Key missing");
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${key}`
      },
      body: JSON.stringify({
        model: 'gpt-4o',
        messages: [
          ...(params.systemInstruction ? [{ role: 'system', content: params.systemInstruction }] : []),
          { role: 'user', content: params.prompt }
        ],
        response_format: params.responseMimeType === 'application/json' ? { type: 'json_object' } : undefined
      })
    });
    const data = await response.json();
    return data.choices[0]?.message?.content || '';
  },

  async generateDallE(prompt: string, key?: string): Promise<string> {
    if (!key) throw new Error("OpenAI API Key missing");
    const response = await fetch('https://api.openai.com/v1/images/generations', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({ model: 'dall-e-3', prompt, n: 1, size: '1024x1024', response_format: 'b64_json' })
    });
    const data = await response.json();
    return `data:image/png;base64,${data.data[0].b64_json}`;
  },

  // --- Anthropic Implementation (REST) ---

  async generateAnthropic(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new Error("Anthropic API Key missing");
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerously-set-custom-headers': JSON.stringify({ 'Access-Control-Allow-Origin': '*' })
      },
      body: JSON.stringify({
        model: 'claude-3-5-sonnet-20240620',
        max_tokens: 4096,
        system: params.systemInstruction,
        messages: [{ role: 'user', content: params.prompt }]
      })
    });
    const data = await response.json();
    return data.content[0]?.text || '';
  },

  // --- Stability Implementation (REST) ---

  async generateStability(prompt: string, key?: string): Promise<string> {
    if (!key) throw new Error("Stability API Key missing");
    const response = await fetch('https://api.stability.ai/v1/generation/stable-diffusion-xl-1024-v1-0/text-to-image', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({ text_prompts: [{ text: prompt }], cfg_scale: 7, height: 1024, width: 1024, samples: 1, steps: 30 })
    });
    const data = await response.json();
    return `data:image/png;base64,${data.artifacts[0].base64}`;
  }
};

