import { GoogleGenAI } from "@google/genai";

export interface ProviderStatus {
  id: string;
  name: string;
  status: 'operational' | 'degraded' | 'down' | 'unauthorized';
  latency: number;
}

export const healthCheckService = {
  async checkGemini(key: string): Promise<ProviderStatus> {
    const start = Date.now();
    try {
      const ai = new GoogleGenAI({ apiKey: key });
      await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: 'ping'
      });
      return { id: 'gemini', name: 'Google Gemini', status: 'operational', latency: Date.now() - start };
    } catch (e: any) {
      const status = e.message?.includes('401') ? 'unauthorized' : 'down';
      return { id: 'gemini', name: 'Google Gemini', status, latency: 0 };
    }
  },

  async checkOpenAI(key: string): Promise<ProviderStatus> {
    const start = Date.now();
    try {
      const response = await fetch('https://api.openai.com/v1/models', {
        headers: { 'Authorization': `Bearer ${key}` }
      });
      if (response.status === 401) return { id: 'openai', name: 'OpenAI', status: 'unauthorized', latency: 0 };
      if (!response.ok) throw new Error();
      return { id: 'openai', name: 'OpenAI', status: 'operational', latency: Date.now() - start };
    } catch {
      return { id: 'openai', name: 'OpenAI', status: 'down', latency: 0 };
    }
  },

  async checkAnthropic(key: string): Promise<ProviderStatus> {
    const start = Date.now();
    try {
      // Smallest possible Anthropic request to check key
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'claude-3-haiku-20240307', max_tokens: 1, messages: [{ role: 'user', content: 'hi' }] })
      });
      if (response.status === 401) return { id: 'anthropic', name: 'Anthropic', status: 'unauthorized', latency: 0 };
      if (!response.ok) throw new Error();
      return { id: 'anthropic', name: 'Anthropic', status: 'operational', latency: Date.now() - start };
    } catch {
      return { id: 'anthropic', name: 'Anthropic', status: 'down', latency: 0 };
    }
  }
};

