          placeholder={placeholder}
          className="w-full bg-black/60 border border-zinc-800 rounded-lg py-2.5 pl-4 pr-24 text-zinc-300 font-mono text-xs focus:ring-1 focus:ring-brand-500 outline-none transition-all"
        />
        <div className="absolute right-1 top-1 bottom-1 flex gap-1">
          <button 
            onClick={() => setShow(!show)}
            className="px-2 text-zinc-500 hover:text-zinc-300 transition-colors"
          >
            {show ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
          </button>
          <button 
            onClick={handleCheck}
            disabled={checking || !value}
            className="px-3 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded text-[9px] font-black uppercase transition-all"
          >
            {checking ? <RefreshCw className="w-3 h-3 animate-spin" /> : 'Check'}
