    IMPORTANT: You must return ONLY a raw JSON object. Do not include markdown code blocks, headers, or any text other than the JSON.
  `;

  try {
    const text = await universalAiService.generateText({
      prompt,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          tagline: { type: Type.STRING },
          mission: { type: Type.STRING },
          elevatorPitch: { type: Type.STRING },
          coreValues: { type: Type.ARRAY, items: { type: Type.STRING } },
          keyMessaging: { type: Type.ARRAY, items: { type: Type.STRING } },
          targetAudience: { type: Type.ARRAY, items: { type: Type.STRING } },
          personas: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                role: { type: Type.STRING },
                painPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            }
          },
          swot: {
            type: Type.OBJECT,
            properties: {
              strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
              weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
              opportunities: { type: Type.ARRAY, items: { type: Type.STRING } },
              threats: { type: Type.ARRAY, items: { type: Type.STRING } }
            }
          },
          competitors: { type: Type.ARRAY, items: { type: Type.STRING } },
          tone: {
            type: Type.OBJECT,
            properties: {
              adjectives: { type: Type.ARRAY, items: { type: Type.STRING } },
              description: { type: Type.STRING },
              personality: { type: Type.STRING }
            }
          },
          visualIdentity: {
            type: Type.OBJECT,
            properties: {
              primaryColor: { type: Type.STRING },
              secondaryColor: { type: Type.STRING },
              fontPairing: { type: Type.STRING },
              styleKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
              designSystem: { type: Type.STRING }
            }
          },
          sonicIdentity: {
            type: Type.OBJECT,
            properties: {
              voiceType: { type: Type.STRING },
              musicGenre: { type: Type.STRING },
              soundKeywords: { type: Type.ARRAY, items: { type: Type.STRING } }
            }
          },
          confidenceScore: { type: Type.NUMBER }
        },
        required: ['name', 'tagline', 'mission', 'elevatorPitch', 'coreValues', 'keyMessaging', 'targetAudience', 'personas', 'swot', 'tone', 'visualIdentity', 'sonicIdentity']
      }
    });

    const data = JSON.parse(text || '{}');
    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      confidenceScore: data.confidenceScore || 85,
      ...data
    } as BrandDNA;
  } catch (error) {
    console.error("Extraction failed", error);
    throw error;
  }
};

// --- Campaign PRD Generation ---
export const generateAdvancedPRD = async (
  brand: BrandDNA, 
  overview: CampaignOverview,
  channels: string[]
): Promise<CampaignPRD> => {
  const prompt = `
    Act as a Chief Marketing Officer. Create a 360-degree, full-blown Campaign Blueprint (PRD) for "${brand.name}".
    Mission: ${brand.mission}
    Goal: ${overview.goal}
    Timeline: ${overview.timeline}
    Channels: ${channels.join(', ')}

    Ensure the userStories are descriptive and cover multiple phases (Teaser, Launch, Sustenance).

    IMPORTANT: You must return ONLY a raw JSON object matching the requested schema. Do NOT include markdown blocks (# or **) or conversational text.
  `;

  try {
    const text = await universalAiService.generateText({
      prompt,
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelStrategies: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                channel: { type: Type.STRING },
                postFrequency: { type: Type.STRING },
                recommendedFormat: { type: Type.STRING },
                contentLength: { type: Type.STRING },
                bestTimes: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            }
          },
          sequencingPlan: { type: Type.STRING },
          totalAssetsTarget: { type: Type.NUMBER },
          userStories: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                description: { type: Type.STRING },
                channel: { type: Type.STRING },
                assetTypes: { type: Type.ARRAY, items: { type: Type.STRING } },
                priority: { type: Type.STRING },
                dayOffset: { type: Type.NUMBER },
                acceptanceCriteria: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            }
          }
        },
        required: ['channelStrategies', 'sequencingPlan', 'totalAssetsTarget', 'userStories']
      }
    });

    const raw = JSON.parse(text || '{}');
    const processedStories: UserStory[] = (raw.userStories || []).map((s: any, index: number) => ({
      ...s,
      id: `story-${index + 1}`,
      status: 'pending',
      dependencies: index > 0 ? [`story-${index}`] : [] 
    }));

    return {
      overview,
      channelStrategies: raw.channelStrategies || [],
      sequencingPlan: raw.sequencingPlan || "Sequential rollout",
      totalAssetsTarget: processedStories.length,
      userStories: processedStories
    };
  } catch (error) {
    console.error("PRD Generation Failed", error);
    throw error;
  }
};

