                      <input type="text" value={overview.name} onChange={(e) => setOverview({...overview, name: e.target.value})} placeholder="e.g. OPERATION_NEON_FALL" className="w-full bg-black/40 border border-zinc-800 rounded-2xl py-4 px-6 text-white font-bold focus:ring-2 focus:ring-brand-500 outline-none transition-all placeholder-zinc-800" />
