import { GoogleGenAI, Type } from "@google/genai";
import { useStore } from "../store";

export interface TextGenerationParams {
  systemInstruction?: string;
  prompt: string;
  responseMimeType?: string;
  responseSchema?: any;
  featureId?: string; // Used to identify which feature is calling for specific mocks
}

export class AiServiceError extends Error {
  constructor(public message: string, public code?: string | number, public status?: string) {
    super(message);
    this.name = 'AiServiceError';
  }
}

/**
 * Utility to strip markdown code blocks and extract valid JSON from LLM responses
 */
const cleanJsonResponse = (text: string): string => {
  if (!text) return '{}';

  let cleaned = text.replace(/```json\n?|```\n?/gi, '').trim();

  const firstBrace = cleaned.indexOf('{');
  const firstBracket = cleaned.indexOf('[');

  let start = -1;
  if (firstBrace !== -1 && firstBracket !== -1) {
    start = Math.min(firstBrace, firstBracket);
  } else {
    start = firstBrace !== -1 ? firstBrace : firstBracket;
  }

  const lastBrace = cleaned.lastIndexOf('}');
  const lastBracket = cleaned.lastIndexOf(']');
  const end = Math.max(lastBrace, lastBracket);

  if (start !== -1 && end !== -1 && end > start) {
    return cleaned.substring(start, end + 1);
  }

  if (cleaned.startsWith('{') || cleaned.startsWith('[')) return cleaned;

  return '{}';
};

export const universalAiService = {
  /**
   * Universal Text Generation Router with Automatic Mock Fallback
   */
  async generateText(params: TextGenerationParams): Promise<string> {
    const { providers } = useStore.getState();
    const { activeLLM, keys } = providers;

    const finalParams = { ...params };
    if (params.responseMimeType === 'application/json' && activeLLM !== 'gemini') {
      finalParams.prompt = `${params.prompt}\n\nCRITICAL: Return ONLY raw JSON. Do not include markdown blocks, headers, or any text before/after the JSON.`;
    }

    try {
      let result = '';
      switch (activeLLM) {
        case 'openai':
          result = await this.generateOpenAI(finalParams, keys.openai);
          break;
        case 'anthropic':
          result = await this.generateAnthropic(finalParams, keys.anthropic);
          break;
        case 'deepseek':
          result = await this.generateDeepSeek(finalParams, keys.deepseek);
          break;
        case 'groq':
          result = await this.generateGroq(finalParams, keys.groq);
          break;
        case 'mistral':
          result = await this.generateMistral(finalParams, keys.mistral);
          break;
        case 'gemini':
        default:
          result = await this.generateGemini(finalParams, keys.gemini || process.env.API_KEY || '');
          break;
      }

      if (params.responseMimeType === 'application/json') {
        const cleaned = cleanJsonResponse(result);
        if (cleaned === '{}' && params.prompt.toLowerCase().includes('json')) {
           throw new AiServiceError("Neural output was malformed.", "MALFORMED_JSON");
        }
        return cleaned;
      }
      return result;
    } catch (error: any) {
      let msg = error.message || String(error);

      // Attempt to parse JSON error strings (Common in Gemini/OpenAI fetch failures)
      try {
        const parsed = JSON.parse(msg);
        if (parsed.error && parsed.error.message) {
          msg = parsed.error.message;
        }
      } catch (e) {
        // Not a JSON string, continue
      }

      const isQuotaError = msg.includes('429') || 
                           msg.toLowerCase().includes('quota') || 
                           msg.toLowerCase().includes('limit') || 
                           msg.toLowerCase().includes('balance') || 
                           msg.toLowerCase().includes('insufficient') ||
                           msg.includes('RESOURCE_EXHAUSTED');

      // If quota is hit, try to return mock data for certain features to keep the app working
      if (isQuotaError && params.featureId) {
        console.warn(`[AI Router] Quota exhausted for ${params.featureId}. Triggering internal failover sequence.`);
        return "FALLBACK_TRIGGERED"; 
      }

      if (isQuotaError) {
        throw new AiServiceError("Neural Quota Exhausted. Check Settings to switch models or update billing.", "QUOTA_EXCEEDED");
      }
      throw new AiServiceError(msg);
    }
  },

  /**
   * Universal Image Generation Router
   */
  async generateImage(prompt: string): Promise<string> {
    const { providers } = useStore.getState();
    const { activeImage, keys } = providers;

    try {
      switch (activeImage) {
        case 'openai':
          return await this.generateDallE(prompt, keys.openai);
        case 'stability':
          return await this.generateStability(prompt, keys.stability);
        case 'fal':
          return await this.generateFal(prompt, keys.fal);
        case 'leonardo':
          return await this.generateLeonardo(prompt, keys.leonardo);
        case 'replicate':
          return await this.generateReplicate(prompt, keys.replicate);
        case 'gemini':
        default:
          return await this.generateGeminiImage(prompt, keys.gemini || process.env.API_KEY || '');
      }
    } catch (error: any) {
      const msg = error.message || String(error);
      if (msg.includes('429') || msg.toLowerCase().includes('quota')) {
        console.warn("[AI Router] Visual Engine Quota Exhausted. Returning fallback static asset.");
        return "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=1000&auto=format&fit=crop";
      }
      throw error;
    }
  },

  // --- Gemini Implementation ---

  async generateGemini(params: TextGenerationParams, key: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: params.prompt,
      config: {
        systemInstruction: params.systemInstruction,
        responseMimeType: params.responseMimeType,
        responseSchema: params.responseSchema,
        temperature: 0.1
      }
    });
    return response.text || '';
  },

  async generateGeminiImage(prompt: string, key: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    });
    for (const candidate of response.candidates || []) {
      for (const part of candidate.content.parts || []) {
        if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data returned from Gemini");
  },

  // --- REST Implementations ---
  async generateOpenAI(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("OpenAI API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({
        model: 'gpt-4o',
        messages: [
          ...(params.systemInstruction ? [{ role: 'system', content: params.systemInstruction }] : []),
          { role: 'user', content: params.prompt }
        ],
        response_format: params.responseMimeType === 'application/json' ? { type: 'json_object' } : undefined
      })
    });
    const data = await response.json();
    if (data.error) throw new Error(JSON.stringify(data)); // Pass whole error for the interceptor
    return data.choices[0]?.message?.content || '';
  },

  async generateDallE(prompt: string, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("OpenAI API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.openai.com/v1/images/generations', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({ model: 'dall-e-3', prompt, n: 1, size: '1024x1024', response_format: 'b64_json' })
    });
    const data = await response.json();
    if (data.error) throw new Error(JSON.stringify(data));
    return `data:image/png;base64,${data.data[0].b64_json}`;
  },

  async generateAnthropic(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Anthropic API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01', 'dangerously-allow-browser': 'true' },
      body: JSON.stringify({
        model: 'claude-3-5-sonnet-20240620',
        max_tokens: 4096,
        system: params.systemInstruction,
        messages: [{ role: 'user', content: params.prompt }]
      })
    });
    const data = await response.json();
    if (data.error) throw new Error(JSON.stringify(data));
    return data.content[0]?.text || '';
  },

  async generateDeepSeek(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("DeepSeek API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.deepseek.com/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({
        model: 'deepseek-chat',
        messages: [
          ...(params.systemInstruction ? [{ role: 'system', content: params.systemInstruction }] : []),
          { role: 'user', content: params.prompt }
        ]
      })
    });
    const data = await response.json();
    if (data.error) throw new Error(JSON.stringify(data));
    return data.choices[0]?.message?.content || '';
  },

  async generateGroq(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Groq API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({
        model: 'llama-3.3-70b-versatile',
        messages: [
          ...(params.systemInstruction ? [{ role: 'system', content: params.systemInstruction }] : []),
          { role: 'user', content: params.prompt }
        ]
      })
    });
    const data = await response.json();
    if (data.error) throw new Error(JSON.stringify(data));
    return data.choices[0]?.message?.content || '';
  },

  async generateMistral(params: TextGenerationParams, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Mistral API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.mistral.ai/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({
        model: 'mistral-large-latest',
        messages: [
          ...(params.systemInstruction ? [{ role: 'system', content: params.systemInstruction }] : []),
          { role: 'user', content: params.prompt }
        ]
      })
    });
    const data = await response.json();
    if (data.error) throw new Error(JSON.stringify(data));
    return data.choices[0]?.message?.content || '';
  },

  async generateStability(prompt: string, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Stability API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.stability.ai/v1/generation/stable-diffusion-xl-1024-v1-0/text-to-image', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({ text_prompts: [{ text: prompt }], cfg_scale: 7, height: 1024, width: 1024, samples: 1, steps: 30 })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(JSON.stringify(data));
    return `data:image/png;base64,${data.artifacts[0].base64}`;
  },

  async generateFal(prompt: string, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Fal API Key missing", "AUTH_MISSING");
    const response = await fetch('https://fal.run/fal-ai/flux/schnell', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Key ${key}` },
      body: JSON.stringify({ prompt, image_size: 'square_hd' })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(JSON.stringify(data));
    return data.images[0].url;
  },

  async generateLeonardo(prompt: string, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Leonardo API Key missing", "AUTH_MISSING");
    const createRes = await fetch('https://cloud.leonardo.ai/api/rest/v1/generations', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({ prompt, modelId: '6bef9f1b-29cb-40c7-b9df-ad2b9fc2d51d', width: 1024, height: 1024, num_images: 1 })
    });
    const createData = await createRes.json();
    if (!createRes.ok) throw new Error(JSON.stringify(createData));

    const genId = createData.sdGenerationJob.generationId;
    for (let i = 0; i < 20; i++) {
      await new Promise(r => setTimeout(r, 2000));
      const pollRes = await fetch(`https://cloud.leonardo.ai/api/rest/v1/generations/${genId}`, {
        headers: { 'Authorization': `Bearer ${key}` }
      });
      const pollData = await pollRes.json();
      if (pollData.generations_by_pk?.generated_images?.length > 0) {
        return pollData.generations_by_pk.generated_images[0].url;
      }
    }
    throw new Error("Leonardo generation timed out");
  },

  async generateReplicate(prompt: string, key?: string): Promise<string> {
    if (!key) throw new AiServiceError("Replicate API Key missing", "AUTH_MISSING");
    const response = await fetch('https://api.replicate.com/v1/predictions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Token ${key}` },
      body: JSON.stringify({
        version: "39ed52f2a78e934b3ba6e2a89f5b1c712de7dfea535525255b1aa35c5565e08b",
        input: { prompt }
      })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(JSON.stringify(data));

    const getUrl = data.urls.get;
    for (let i = 0; i < 25; i++) {
      await new Promise(r => setTimeout(r, 1500));
      const pollRes = await fetch(getUrl, { headers: { 'Authorization': `Token ${key}` } });
      const pollData = await pollRes.json();
      if (pollData.status === 'succeeded') return pollData.output[0];
      if (pollData.status === 'failed') throw new Error("Replicate generation failed");
    }
    throw new Error("Replicate generation timed out");
  }
};

