const getProviderDisplayName = (id: string, type: 'llm' | 'image') => {
  const maps: Record<string, string> = {
    gemini: 'GEMINI 3 FLASH',
    openai: 'GPT-4O TURBO',
    anthropic: 'CLAUDE 3.5 SONNET',
    deepseek: 'DEEPSEEK V3',
    groq: 'GROQ (LLAMA 3.3)',
    mistral: 'MISTRAL LARGE 2',
    stability: 'SDXL / ULTRA',
    fal: 'FAL (FLUX.1)',
    leonardo: 'LEONARDO AI',
    replicate: 'REPLICATE CLOUD'
  };
  if (id === 'openai' && type === 'image') return 'DALL-E 3';
  if (id === 'gemini' && type === 'image') return 'GEMINI 2.5 IMAGE';
  return maps[id] || id.toUpperCase();
};

