        </div>
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto min-h-full flex flex-col">
      <div className="mb-10 flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-black text-white mb-1 uppercase tracking-tighter">Forge</h1>
          <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-widest">Autonomous Engine</p>
        </div>
        <div className="flex bg-black/40 border border-zinc-800 rounded-xl p-1">
           <button onClick={() => setView('forge')} className={`px-5 py-2 rounded-lg text-xs font-bold ${view === 'forge' ? 'bg-zinc-800 text-white' : 'text-zinc-500'}`}>Forge</button>
