        </div>
      </div>
      {view === 'forge' ? (
        <>
          <StepIndicator current={step} steps={['Brief', 'Blueprint', 'Forge', 'Deploy']} />
          <div className="flex-1">
            {step === 1 && (
              <div className="max-w-4xl mx-auto bg-dark-surface border border-dark-border rounded-3xl p-10 shadow-2xl">
                <h2 className="text-xl font-black text-white mb-8 uppercase flex items-center gap-2 border-b border-zinc-800 pb-4">Brief</h2>
                <div className="space-y-6">
                   <div>
                     <label className="text-[10px] font-black text-zinc-600 uppercase mb-2 block">Campaign Name</label>
                     <input type="text" value={overview.name} onChange={(e) => setOverview({...overview, name: e.target.value})} placeholder="OPERATION_X" className="w-full bg-black/40 border border-zinc-800 rounded-xl py-3 px-4 text-white outline-none focus:ring-1 focus:ring-brand-500" />
                   </div>
