import { GoogleGenAI, Type } from "@google/genai";
import { LeadProfile, CloserPortfolio } from "../types";
import { universalAiService } from "./universalAiService";

export interface GroundedLeadResult {
  leads: LeadProfile[];
  sources: { title: string; uri: string }[];
}

export const huntLeads = async (
  industry: string, 
  location: string, 
  coords?: { lat: number; lng: number }
): Promise<GroundedLeadResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const locationContext = coords 
    ? `near geographic coordinates ${coords.lat}, ${coords.lng} (${location})`
    : `in ${location}`;

  const prompt = `
    Find 5 REAL, currently active companies in the "${industry}" sector ${locationContext}.

    For each company:
    1. Identify their official website.
    2. Analyze their likely branding or marketing gaps (e.g., outdated social presence, lack of AI integration, generic messaging).
    3. Determine how CoreDNA (an AI Brand Intelligence platform) would specifically help them scale or fix these issues.
    4. Estimate their size (headcount/revenue) based on available public data.
    5. Identify a key decision maker if possible.

    CRITICAL: You MUST use Google Search to find actual, existing businesses. Do not hallucinate names.

    Return a JSON object with this EXACT structure:
    {
      "leads": [
        {
          "companyName": "string",
          "industry": "string",
          "location": "string",
          "website": "string",
          "founderName": "string",
          "opportunityScore": number (0-100),
          "painPointDescription": "string",
          "vulnerabilities": ["string"],
          "techStack": ["string"],
          "estimatedRevenue": "string",
          "headcount": "string"
        }
      ]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: 'application/json'
      }
    });

    const text = response.text || '{}';
    // Extract grounding chunks for the UI
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .filter((chunk: any) => chunk.web)
      .map((chunk: any) => ({
        title: chunk.web.title,
        uri: chunk.web.uri
      }));

    const data = JSON.parse(text);
    const leads = (data.leads || []).map((l: any) => ({
      ...l,
      id: crypto.randomUUID(),
      status: 'new',
      industry: l.industry || industry,
      location: l.location || location
    })) as LeadProfile[];

    return { leads, sources };

  } catch (error) {
    console.error("Lead hunting grounded search failed", error);
    throw new Error("Neural search failed to index live targets. Please try a more specific sector or check connection.");
  }
};

export const generateCloserPortfolio = async (lead: LeadProfile): Promise<CloserPortfolio> => {
  const prompt = `
