         - Key Messaging: ${currentBrand.keyMessaging.join(' | ')}

         Your goal is to assist users while strictly adhering to this brand identity.`
      : 'You are a helpful assistant.';

    const newAgent: Agent = {
      id: crypto.randomUUID(),
      name: baseName,
      type: 'custom',
      role: baseRole,
      personality: basePersonality,
      systemInstruction: baseInstruction,
      guardrails: currentBrand ? [`Never contradict the brand mission: ${currentBrand.mission.substring(0, 50)}...`] : [],
      knowledgeBase: [],
      status: 'draft',
      avatar: '🤖',
      brandId: currentBrand?.id
    };
    addAgent(newAgent);
    setSelectedAgentId(newAgent.id);
  };

  const handleAutoRecruit = () => {
    if (!currentBrand) return;

    const templates = [
      {
        name: `${currentBrand.name} Sales`,
        role: 'Sales Specialist',
        type: 'sales',
        personality: 'Persuasive, ' + currentBrand.tone.personality,
        avatar: '💼',
        instruction: `You are a top-tier Sales Agent for ${currentBrand.name}. Your Goal: Convert leads by pitching our unique value proposition: "${currentBrand.elevatorPitch}".`
