      {
        name: `${currentBrand.name} Support`,
        role: 'Customer Success',
        type: 'support',
        personality: 'Empathetic, ' + currentBrand.tone.personality,
        avatar: '🛡️',
        instruction: `You are the Head of Support for ${currentBrand.name}. Handle inquiries with a ${currentBrand.tone.personality} tone. Never break character.`
      }
    ];

    templates.forEach(t => {
      addAgent({
        id: crypto.randomUUID(),
        name: t.name,
        role: t.role,
        type: t.type as any,
        personality: t.personality,
        systemInstruction: t.instruction,
