import { BrandDNA } from "../types";
import { executeRLMAnalysis } from "./rlmService";
import { scrapeWebsite, ScrapedData } from "./scraperService";
import { universalAiService } from "./universalAiService";

export const enhanceBrandExtraction = async (
  url: string, 
  description: string,
  onProgress?: (status: string) => void
): Promise<BrandDNA> => {

  if (onProgress) onProgress("Deploying Scraper Bots...");

  let scrapedData: ScrapedData | null = null;
  let scrapeContext = "";

  try {
    scrapedData = await scrapeWebsite(url);
    if (onProgress) onProgress("Parsing HTML DOM...");

    scrapeContext = `
      LIVE WEBSITE DATA (SCRAPED JUST NOW):
      - Page Title: "${scrapedData.title}"
      - Meta Description: "${scrapedData.metaDescription}"
      - Main Headlines (H1/H2): ${[...scrapedData.h1, ...scrapedData.h2].join(' | ')}
      - Social Signals: ${scrapedData.socialLinks.join(', ')}

      CORE BODY CONTENT (From Website):
      """
      ${scrapedData.bodyText}
      """
    `;
  } catch (e) {
    console.warn("Scraping failed, falling back to AI knowledge", e);
    if (onProgress) onProgress("Scraping blocked. Falling back to Neural Memory...");
    scrapeContext = "WARNING: Direct scraping failed. Rely on internal knowledge base for this URL.";
  }

  const prompt = `
    Analyze the brand based on this URL: ${url} and this user description: "${description}".

    ${scrapeContext}

    Act as a World-Class Brand Strategist. 
    Extract the "Core DNA" of this entity.

    Structure:
    {
      "name": "Brand Name",
      "tagline": "Tagline",
      "mission": "Mission statement",
      "elevatorPitch": "Pitch",
      "coreValues": ["Value 1", "Value 2"],
      "keyMessaging": ["Message 1"],
      "targetAudience": ["Segment 1"],
      "personas": [{ "name": "Name", "role": "Role", "painPoints": [] }],
      "swot": { "strengths": [], "weaknesses": [], "opportunities": [], "threats": [] },
      "competitors": [],
      "tone": { "adjectives": [], "description": "", "personality": "" },
      "visualIdentity": {
        "primaryColor": "Hex",
        "secondaryColor": "Hex",
        "fontPairing": "Font",
        "styleKeywords": ["Modern"],
        "designSystem": ""
      },
      "sonicIdentity": { "voiceType": "", "musicGenre": "", "soundKeywords": [] },
      "confidenceScore": 85
    }
  `;

  try {
    const jsonString = await executeRLMAnalysis(prompt, onProgress);

    if (jsonString === "FALLBACK_TRIGGERED") {
      return {
        id: crypto.randomUUID(),
        url,
        extractedAt: new Date().toISOString(),
        name: scrapedData?.title || 'New Brand',
        tagline: 'Heuristic Tagline',
        mission: 'Heuristic Mission',
        elevatorPitch: '',
        coreValues: ['Quality'],
        keyMessaging: ['Reliability'],
        targetAudience: ['General'],
        personas: [],
        swot: { strengths: [], weaknesses: [], opportunities: [], threats: [] },
        competitors: [],
        tone: { adjectives: ['Professional'], description: '', personality: '' },
        visualIdentity: { primaryColor: '#14b8a6', secondaryColor: '#000000', fontPairing: 'Sans', styleKeywords: ['Clean'], designSystem: '' },
        sonicIdentity: { voiceType: 'Neutral', musicGenre: 'Ambient', soundKeywords: [] },
        confidenceScore: 40
      } as BrandDNA;
    }

    const data = JSON.parse(jsonString);

    // Generate Cover Image for Portfolio
    if (onProgress) onProgress("Synthesizing Portfolio Visuals...");
    let coverImage = undefined;
    try {
      coverImage = await universalAiService.generateImage(`Cinematic professional brand header image for ${data.name}, ${data.visualIdentity?.styleKeywords?.join(', ') || 'modern'}. High-fidelity photography style.`);
    } catch (e) {
      console.warn("Cover image synthesis failed", e);
    }

    return {
      id: crypto.randomUUID(),
      url,
      extractedAt: new Date().toISOString(),
      coverImage,
      ...data
    } as BrandDNA;

  } catch (e) {
    console.error("Enhanced Extraction Failed", e);
    throw e;
  }
};

