import React, { useState, useEffect, useRef } from 'react';
import { useStore } from '../store';
import { Agent, AgentType, AgentMessage, BrandDNA } from '../types';
import { chatWithAgent } from '../services/agentService';
import { Link } from 'react-router-dom';
import { 
  Bot, 
  Plus, 
  Settings, 
  BookOpen, 
  Shield, 
  MessageSquare, 
  Rocket, 
  Trash2, 
  Save, 
  Upload, 
  Terminal,
  User,
  Send,
  RefreshCw,
  MoreVertical,
  Briefcase,
  Sparkles,
  Dna,
  ChevronDown,
  Layers,
  CheckCircle2
} from 'lucide-react';

const AgentForgePage = () => {
  const { agents, addAgent, updateAgent, deleteAgent, brands, currentBrand, setBrand } = useStore();
  const [selectedAgentId, setSelectedAgentId] = useState<string>(agents[0]?.id || '');
  const [activeTab, setActiveTab] = useState<'config' | 'knowledge' | 'test'>('config');
  const [showBrandPicker, setShowBrandPicker] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Partial<Agent>>({});
  const [isDirty, setIsDirty] = useState(false);

  // Test Chat State
  const [chatHistory, setChatHistory] = useState<AgentMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize form when selection changes
  useEffect(() => {
    const agent = agents.find(a => a.id === selectedAgentId);
    if (agent) {
      setFormData(agent);
      setIsDirty(false);
      // Reset chat
      setChatHistory([{
        id: 'init',
        role: 'model',
        text: `Hello! I am ${agent.name}. How can I assist you today?`,
        timestamp: new Date().toISOString()
      }]);
    } else {
      setFormData({}); // Creating new
    }
  }, [selectedAgentId, agents]);

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chatHistory, activeTab]);

  const handleCreateNew = () => {
    const baseName = currentBrand ? `${currentBrand.name} Rep` : 'New Agent';
    const baseRole = currentBrand ? 'Brand Representative' : 'Assistant';
    const basePersonality = currentBrand ? currentBrand.tone.personality : 'Helpful';

    const baseInstruction = currentBrand 
      ? `You are an official AI representative for "${currentBrand.name}".

         BRAND CONTEXT:
         - Mission: ${currentBrand.mission}
         - Core Values: ${currentBrand.coreValues.join(', ')}
         - Tone of Voice: ${currentBrand.tone.personality} (${currentBrand.tone.adjectives.join(', ')})
         - Key Messaging: ${currentBrand.keyMessaging.join(' | ')}

         Your goal is to assist users while strictly adhering to this brand identity.`
      : 'You are a helpful assistant.';

    const newAgent: Agent = {
      id: crypto.randomUUID(),
      name: baseName,
      type: 'custom',
      role: baseRole,
      personality: basePersonality,
      systemInstruction: baseInstruction,
      guardrails: currentBrand ? [`Never contradict the brand mission: ${currentBrand.mission.substring(0, 50)}...`] : [],
      knowledgeBase: [],
      status: 'draft',
      avatar: '🤖',
      brandId: currentBrand?.id
    };
    addAgent(newAgent);
    setSelectedAgentId(newAgent.id);
  };

  const handleAutoRecruit = () => {
    if (!currentBrand) return;

    const templates = [
      {
        name: `${currentBrand.name} Sales`,
        role: 'Sales Specialist',
        type: 'sales',
        personality: 'Persuasive, ' + currentBrand.tone.personality,
        avatar: '💼',
        instruction: `You are a top-tier Sales Agent for ${currentBrand.name}. Your Goal: Convert leads by pitching our unique value proposition: "${currentBrand.elevatorPitch}".`
      },
      {
        name: `${currentBrand.name} Support`,
        role: 'Customer Success',
        type: 'support',
        personality: 'Empathetic, ' + currentBrand.tone.personality,
        avatar: '🛡️',
        instruction: `You are the Head of Support for ${currentBrand.name}. Handle inquiries with a ${currentBrand.tone.personality} tone. Never break character.`
      }
    ];

    templates.forEach(t => {
      addAgent({
        id: crypto.randomUUID(),
        name: t.name,
        role: t.role,
        type: t.type as any,
        personality: t.personality,
        systemInstruction: t.instruction,
        guardrails: [`Uphold ${currentBrand.name} values`],
        knowledgeBase: [],
        status: 'deployed',
        avatar: t.avatar,
        brandId: currentBrand.id
      });
    });
  };

  const handleSave = () => {
    if (selectedAgentId && formData) {
      updateAgent(selectedAgentId, { ...formData, brandId: currentBrand?.id });
      setIsDirty(false);
    }
  };

  const handleDelete = () => {
    if (confirm("Are you sure you want to delete this agent?")) {
      deleteAgent(selectedAgentId);
      setSelectedAgentId(agents[0]?.id || '');
    }
  };

  const handleDeploy = () => {
    if (selectedAgentId) {
      updateAgent(selectedAgentId, { status: 'deployed' });
      alert(`Agent deployed!`);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isTyping) return;
    const agent = agents.find(a => a.id === selectedAgentId);
    if (!agent) return;
    const userMsg: AgentMessage = { id: crypto.randomUUID(), role: 'user', text: chatInput, timestamp: new Date().toISOString() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsTyping(true);
    try {
      const response = await chatWithAgent({ ...agent, ...formData } as Agent, chatHistory, userMsg.text);
      setChatHistory(prev => [...prev, { id: crypto.randomUUID(), role: 'model', text: response, timestamp: new Date().toISOString() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const updateField = (field: keyof Agent, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setIsDirty(true);
  };

  if (agents.length === 0 && !selectedAgentId) {
     return (
       <div className="h-full flex items-center justify-center bg-dark-bg p-8 text-center">
          <div className="max-w-md bg-dark-surface p-12 rounded-[3rem] border border-dark-border shadow-2xl animate-in zoom-in-95">
             <Bot className="w-20 h-20 mx-auto mb-8 text-brand-500 opacity-40" />
             <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-4">Neural Barracks Empty</h2>
             <p className="text-zinc-500 font-medium mb-10 leading-relaxed text-sm">Initiate tactical agent deployment by selecting a brand context from your portfolio deck.</p>
             <div className="flex flex-col gap-4">
               {brands.length > 0 && (
                 <button onClick={handleCreateNew} className="w-full py-4 bg-brand-600 hover:bg-brand-500 text-white font-black rounded-2xl shadow-xl transition-all uppercase tracking-widest text-xs">Initialize Manual Operative</button>
               )}
               <Link to="/extract" className="w-full py-4 bg-zinc-800 hover:bg-zinc-700 text-white font-black rounded-2xl transition-all uppercase tracking-widest text-xs">Sequence New Brand DNA</Link>
             </div>
          </div>
       </div>
     );
  }

  const selectedAgent = agents.find(a => a.id === selectedAgentId);

  return (
    <div className="flex h-full bg-dark-bg overflow-hidden relative">
      {/* LEFT SIDEBAR: AGENT REPOSITORY */}
      <div className="w-80 bg-dark-surface border-r border-dark-border flex flex-col shrink-0">
         <div className="p-6 border-b border-dark-border bg-black/20">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
                <Bot className="w-6 h-6 text-brand-500" /> OPERATIVES
              </h2>
              <button onClick={handleCreateNew} className="p-2 bg-brand-900/20 text-brand-400 hover:bg-brand-600 hover:text-white rounded-xl transition-all" title="Deploy New Operative">
                <Plus className="w-4 h-4" />
              </button>
            </div>

            {/* Portfolio Selector in Agent Forge */}
            <div className="relative">
               <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest mb-2 block px-1">Source DNA Context</label>
               <button 
                 onClick={() => setShowBrandPicker(!showBrandPicker)}
                 className="w-full p-3 bg-black/40 border border-zinc-800 rounded-xl flex items-center justify-between group hover:border-brand-500/40 transition-all"
               >
                  <div className="flex items-center gap-2 overflow-hidden">
                     <Dna className="w-4 h-4 text-brand-500 shrink-0" />
                     <span className="text-xs font-black text-white uppercase tracking-tight truncate">{currentBrand?.name || 'Unbound Operative'}</span>
                  </div>
                  <ChevronDown className={`w-4 h-4 text-zinc-600 group-hover:text-brand-500 transition-transform ${showBrandPicker ? 'rotate-180' : ''}`} />
               </button>

               {showBrandPicker && (
                  <div className="absolute top-full left-0 right-0 mt-2 bg-dark-surface border border-dark-border rounded-2xl shadow-2xl z-50 p-2 animate-in fade-in slide-in-from-top-2">
                     {brands.map(b => (
                        <button 
                          key={b.id}
                          onClick={() => { setBrand(b); setShowBrandPicker(false); }}
                          className={`w-full p-3 text-left rounded-xl text-xs font-bold uppercase flex items-center justify-between hover:bg-white/5 transition-colors ${currentBrand?.id === b.id ? 'text-brand-400' : 'text-zinc-500'}`}
                        >
                           <span className="truncate">{b.name}</span>
                           {currentBrand?.id === b.id && <CheckCircle2 className="w-3.5 h-3.5" />}
                        </button>
                     ))}
                  </div>
               )}
            </div>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {agents.map(agent => (
               <div 
                 key={agent.id}
                 onClick={() => setSelectedAgentId(agent.id)}
                 className={`p-4 rounded-2xl cursor-pointer border transition-all flex items-center gap-4 ${
                    selectedAgentId === agent.id 
                      ? 'bg-brand-900/10 border-brand-500/50 shadow-xl shadow-brand-900/10' 
                      : 'bg-black/20 border-zinc-800/50 text-zinc-400 hover:border-zinc-700'
                 }`}
               >
                  <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-xl shadow-inner ${selectedAgentId === agent.id ? 'bg-brand-600 text-white' : 'bg-zinc-900 text-zinc-500'}`}>
                     {agent.avatar}
                  </div>
                  <div className="flex-1 min-w-0">
                     <div className="font-black text-sm truncate text-white uppercase tracking-tighter">{agent.name}</div>
                     <div className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mt-0.5">{agent.type} • {agent.status}</div>
                  </div>
               </div>
            ))}
         </div>
      </div>

      {/* CENTER: FORGE INTERFACE */}
      {selectedAgent && (
        <div className="flex-1 flex flex-col min-w-0">
           {/* Forge Header */}
           <div className="h-20 border-b border-dark-border bg-dark-surface/50 backdrop-blur-xl px-8 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-6">
                 <div className="w-12 h-12 rounded-2xl bg-brand-600 flex items-center justify-center text-2xl shadow-xl shadow-brand-900/30">
                    {formData.avatar}
                 </div>
                 <div>
                    <div className="flex items-center gap-3">
                       <h1 className="text-2xl font-black text-white uppercase tracking-tighter">{formData.name}</h1>
                       {isDirty && <span className="text-[9px] bg-amber-500 text-black px-2 py-0.5 rounded font-black uppercase tracking-widest">Modified</span>}
                    </div>
                    <div className="flex items-center gap-4 text-[10px] font-black uppercase tracking-widest text-zinc-500 mt-1">
                       <span className="flex items-center gap-1.5"><Layers className="w-3 h-3 text-brand-500" /> {formData.type} Segment</span>
                       {formData.status === 'deployed' && <span className="text-green-500 flex items-center gap-1.5"><Rocket className="w-3 h-3" /> Mission Live</span>}
                    </div>
                 </div>
              </div>

              <div className="flex items-center gap-3">
                 <button onClick={handleDelete} className="p-3 text-zinc-600 hover:text-red-500 transition-colors" title="Decommission Operative"><Trash2 className="w-5 h-5" /></button>
                 <div className="h-8 w-px bg-zinc-800 mx-2" />
                 <button onClick={handleSave} disabled={!isDirty} className="px-6 py-3 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-50 text-white text-xs font-black uppercase tracking-widest rounded-xl transition-all shadow-lg">Save Config</button>
                 <button onClick={handleDeploy} className="px-8 py-3 bg-brand-600 hover:bg-brand-500 text-white text-xs font-black uppercase tracking-widest rounded-xl shadow-xl shadow-brand-900/40 transition-all hover:scale-105 active:scale-95">Ignite Deployment</button>
              </div>
           </div>

           {/* Tabs */}
           <div className="flex border-b border-dark-border bg-black/40 px-8 shrink-0">
              {[
                { id: 'config', label: 'Instruction Matrix', icon: Settings },
                { id: 'knowledge', label: 'Neural Synapse', icon: BookOpen },
                { id: 'test', label: 'Combat Simulation', icon: Terminal }
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`px-8 py-4 text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border-b-2 transition-all ${activeTab === tab.id ? 'border-brand-500 text-brand-500 bg-brand-500/5' : 'border-transparent text-zinc-500 hover:text-zinc-300'}`}
