import React, { useState, useEffect, useRef } from 'react';
import { useStore } from '../store';
import { Agent, AgentType, AgentMessage, BrandDNA } from '../types';
import { chatWithAgent } from '../services/agentService';
import { Link } from 'react-router-dom';
import { 
  Bot, 
  Plus, 
  Settings, 
  BookOpen, 
  Shield, 
  MessageSquare, 
  Rocket, 
  Trash2, 
  Save, 
  Terminal,
  User,
  Send,
  RefreshCw,
  Dna,
  ChevronDown,
  Layers,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';

const AgentForgePage = () => {
  const { agents, addAgent, updateAgent, deleteAgent, brands, currentBrand, setBrand } = useStore();
  const [selectedAgentId, setSelectedAgentId] = useState<string>(agents[0]?.id || '');
  const [activeTab, setActiveTab] = useState<'config' | 'knowledge' | 'test'>('config');
  const [showBrandPicker, setShowBrandPicker] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Partial<Agent>>({});
  const [isDirty, setIsDirty] = useState(false);

  // Test Chat State
  const [chatHistory, setChatHistory] = useState<AgentMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize form when selection changes
  useEffect(() => {
    const agent = agents.find(a => a.id === selectedAgentId);
    if (agent) {
      setFormData(agent);
      setIsDirty(false);
      // Reset chat
      setChatHistory([{
        id: 'init',
        role: 'model',
        text: `Hello! I am ${agent.name}. My neural parameters are synced with ${currentBrand?.name || 'Global Core'}. How can I assist you today?`,
        timestamp: new Date().toISOString()
      }]);
    } else {
      setFormData({});
    }
  }, [selectedAgentId, agents, currentBrand?.id]);

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chatHistory, activeTab]);

  const handleCreateNew = () => {
    const baseName = currentBrand ? `${currentBrand.name} Rep` : 'New Agent';
    const baseRole = currentBrand ? 'Brand Representative' : 'Assistant';
    const basePersonality = currentBrand ? currentBrand.tone.personality : 'Helpful';

    const baseInstruction = currentBrand 
      ? `You are an official AI representative for "${currentBrand.name}". Adhere to our mission: ${currentBrand.mission}`
      : 'You are a helpful assistant.';

    const newAgent: Agent = {
      id: crypto.randomUUID(),
      name: baseName,
      type: 'custom',
      role: baseRole,
      personality: basePersonality,
      systemInstruction: baseInstruction,
      guardrails: currentBrand ? [`Never contradict the brand mission: ${currentBrand.mission.substring(0, 50)}...`] : [],
      knowledgeBase: [],
      status: 'draft',
      avatar: '🤖',
      brandId: currentBrand?.id
    };
    addAgent(newAgent);
    setSelectedAgentId(newAgent.id);
  };

  const handleSave = () => {
    if (selectedAgentId && formData) {
      updateAgent(selectedAgentId, { ...formData, brandId: currentBrand?.id });
      setIsDirty(false);
    }
  };

  const handleDelete = () => {
    if (confirm("Decommission this operative?")) {
      deleteAgent(selectedAgentId);
      setSelectedAgentId(agents[0]?.id || '');
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isTyping) return;
    const agent = agents.find(a => a.id === selectedAgentId);
    if (!agent) return;
    const userMsg: AgentMessage = { id: crypto.randomUUID(), role: 'user', text: chatInput, timestamp: new Date().toISOString() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsTyping(true);
    try {
      const response = await chatWithAgent({ ...agent, ...formData } as Agent, chatHistory, userMsg.text);
      setChatHistory(prev => [...prev, { id: crypto.randomUUID(), role: 'model', text: response, timestamp: new Date().toISOString() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const updateField = (field: keyof Agent, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setIsDirty(true);
  };

  if (agents.length === 0 && !selectedAgentId) {
     return (
       <div className="h-full flex items-center justify-center bg-dark-bg p-8 text-center">
          <div className="max-w-md bg-dark-surface p-16 rounded-[4rem] border border-dark-border shadow-2xl animate-in zoom-in-95">
             <Bot className="w-20 h-20 mx-auto mb-10 text-brand-500 opacity-20" />
             <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-4">Neural Barracks Empty</h2>
             <p className="text-zinc-500 font-medium mb-12 leading-relaxed text-sm">Select a client portfolio context from the dashboard to initialize automated agent recruitment.</p>
             <div className="flex flex-col gap-4">
               {brands.length > 0 && (
                 <button onClick={handleCreateNew} className="w-full py-4 bg-brand-600 hover:bg-brand-500 text-white font-black rounded-2xl shadow-xl transition-all uppercase tracking-widest text-xs">RECRUIT MANUAL OPERATIVE</button>
               )}
               <Link to="/extract" className="w-full py-4 bg-zinc-800 hover:bg-zinc-700 text-white font-black rounded-2xl transition-all uppercase tracking-widest text-xs">SEQUENCE NEW BRAND DNA</Link>
             </div>
          </div>
       </div>
     );
  }

  return (
    <div className="flex h-full bg-dark-bg overflow-hidden relative">
      {/* SIDEBAR: AGENT REPOSITORY */}
      <div className="w-80 bg-dark-surface border-r border-dark-border flex flex-col shrink-0">
         <div className="p-6 border-b border-dark-border bg-black/20">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-black text-white uppercase tracking-widest flex items-center gap-3">
                <Bot className="w-5 h-5 text-brand-500" /> OPERATIVES
              </h2>
              <button onClick={handleCreateNew} className="p-2 bg-brand-900/20 text-brand-400 hover:bg-brand-600 hover:text-white rounded-xl transition-all">
                <Plus className="w-4 h-4" />
              </button>
            </div>

            {/* Portfolio Context Switcher */}
            <div className="relative">
               <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest mb-2.5 block px-1">DNA CONTEXT</label>
               <button 
                 onClick={() => setShowBrandPicker(!showBrandPicker)}
                 className="w-full p-4 bg-black/40 border border-zinc-800 rounded-2xl flex items-center justify-between group hover:border-brand-500/40 transition-all shadow-inner"
               >
                  <div className="flex items-center gap-3 overflow-hidden">
                     <Dna className="w-4 h-4 text-brand-500 shrink-0" />
                     <span className="text-xs font-black text-white uppercase tracking-tight truncate">{currentBrand?.name || 'Unlinked Core'}</span>
                  </div>
                  <ChevronDown className={`w-4 h-4 text-zinc-600 transition-transform ${showBrandPicker ? 'rotate-180' : ''}`} />
               </button>

               {showBrandPicker && (
                  <div className="absolute top-full left-0 right-0 mt-3 bg-dark-surface border border-dark-border rounded-2xl shadow-2xl z-50 p-2 animate-in fade-in slide-in-from-top-2 border-brand-500/20">
                     {brands.map(b => (
                        <button 
                          key={b.id}
                          onClick={() => { setBrand(b); setShowBrandPicker(false); }}
                          className={`w-full p-4 text-left rounded-xl text-xs font-bold uppercase flex items-center justify-between hover:bg-brand-900/10 transition-colors ${currentBrand?.id === b.id ? 'text-brand-400 bg-brand-900/5' : 'text-zinc-500'}`}
                        >
                           <span className="truncate">{b.name}</span>
                           {currentBrand?.id === b.id && <CheckCircle2 className="w-3.5 h-3.5" />}
                        </button>
                     ))}
                  </div>
               )}
            </div>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {agents.map(agent => (
               <div 
                 key={agent.id}
                 onClick={() => setSelectedAgentId(agent.id)}
                 className={`p-5 rounded-[1.5rem] cursor-pointer border transition-all flex items-center gap-4 ${
                    selectedAgentId === agent.id 
                      ? 'bg-brand-900/10 border-brand-500 shadow-2xl shadow-brand-500/10 scale-[1.02]' 
                      : 'bg-black/20 border-zinc-800/50 text-zinc-400 hover:border-zinc-700'
                 }`}
               >
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl shadow-inner ${selectedAgentId === agent.id ? 'bg-brand-600 text-white' : 'bg-zinc-900 text-zinc-500'}`}>
                     {agent.avatar}
                  </div>
                  <div className="flex-1 min-w-0">
                     <div className="font-black text-sm truncate text-white uppercase tracking-tight">{agent.name}</div>
                     <div className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest mt-1">{agent.type} • {agent.status}</div>
                  </div>
               </div>
            ))}
         </div>
      </div>

      {/* CENTER: FORGE INTERFACE */}
      {selectedAgentId && (
        <div className="flex-1 flex flex-col min-w-0">
           {/* Forge Header */}
           <div className="h-24 border-b border-dark-border bg-dark-surface/50 backdrop-blur-2xl px-10 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-8">
                 <div className="w-14 h-14 rounded-2xl bg-brand-600 flex items-center justify-center text-3xl shadow-2xl shadow-brand-600/30">
                    {formData.avatar}
                 </div>
                 <div>
                    <div className="flex items-center gap-4">
                       <h1 className="text-3xl font-black text-white uppercase tracking-tighter">{formData.name}</h1>
                       {isDirty && <span className="text-[8px] bg-amber-500 text-black px-2 py-0.5 rounded-sm font-black uppercase tracking-[0.2em]">UNSAVED</span>}
                    </div>
                    <div className="flex items-center gap-6 text-[10px] font-black uppercase tracking-widest text-zinc-500 mt-2">
                       <span className="flex items-center gap-2"><Layers className="w-3.5 h-3.5 text-brand-500" /> {formData.type} Matrix</span>
                       {formData.status === 'deployed' && <span className="text-green-500 flex items-center gap-2"><Rocket className="w-3.5 h-3.5" /> Deployed</span>}
                    </div>
                 </div>
              </div>

              <div className="flex items-center gap-4">
                 <button onClick={handleDelete} className="p-4 text-zinc-700 hover:text-red-500 transition-colors"><Trash2 className="w-5.5 h-5.5" /></button>
                 <div className="h-10 w-px bg-zinc-800 mx-2" />
                 <button onClick={handleSave} disabled={!isDirty} className="px-8 py-3.5 bg-zinc-900 hover:bg-zinc-800 disabled:opacity-30 text-white text-[10px] font-black uppercase tracking-widest rounded-xl transition-all border border-zinc-800">SAVE PROTOCOL</button>
                 <button className="px-10 py-3.5 bg-brand-600 hover:bg-brand-500 text-white text-[10px] font-black uppercase tracking-widest rounded-xl shadow-2xl shadow-brand-500/20 transition-all active:scale-95">ACTIVATE OPERATIVE</button>
              </div>
           </div>

           {/* Tabs & Simulation Body */}
           <div className="flex border-b border-dark-border bg-black/40 px-10 shrink-0">
              {[
                { id: 'config', label: 'Instruction Set', icon: Settings },
                { id: 'knowledge', label: 'Neural Base', icon: BookOpen },
                { id: 'test', label: 'Simulation Grid', icon: Terminal }
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`px-10 py-5 text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 border-b-2 transition-all ${activeTab === tab.id ? 'border-brand-500 text-brand-500 bg-brand-500/5' : 'border-transparent text-zinc-600 hover:text-zinc-300'}`}
                >
                   <tab.icon className="w-4 h-4" /> {tab.label}
                </button>
              ))}
           </div>

           <div className="flex-1 overflow-y-auto p-12 bg-dark-bg/30">
              {activeTab === 'config' && (
                 <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-6 duration-700">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                       <div className="space-y-8">
                          <div>
                             <label className="block text-[10px] font-black text-zinc-600 uppercase mb-3 tracking-[0.2em] pl-1">Operational ID</label>
                             <input type="text" value={formData.name || ''} onChange={(e) => updateField('name', e.target.value)} className="w-full bg-black/60 border border-zinc-800 rounded-2xl py-4.5 px-6 text-white font-bold focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-inner" />
                          </div>
                          <div>
                             <label className="block text-[10px] font-black text-zinc-600 uppercase mb-3 tracking-[0.2em] pl-1">Primary Mandate</label>
                             <input type="text" value={formData.role || ''} onChange={(e) => updateField('role', e.target.value)} className="w-full bg-black/60 border border-zinc-800 rounded-2xl py-4.5 px-6 text-white font-bold focus:ring-1 focus:ring-brand-500 outline-none transition-all shadow-inner" />
                          </div>
                       </div>
                       <div className="bg-brand-900/10 border border-brand-500/20 p-10 rounded-[2.5rem] flex flex-col justify-center relative overflow-hidden group shadow-2xl">
                          <div className="absolute top-0 right-0 p-6 opacity-5 group-hover:opacity-10 transition-opacity"><Dna className="w-32 h-32 text-brand-500" /></div>
                          <h3 className="text-xs font-black text-brand-400 uppercase tracking-[0.3em] mb-3">Neural Alignment</h3>
                          <p className="text-sm text-zinc-400 leading-relaxed font-medium">Syncing directive logic with <span className="text-white font-black">{currentBrand?.name || 'Unlinked Core'}</span>. Any adjustments here will refine the operative's decision-making matrix.</p>
                          <div className="flex items-center gap-3 mt-6">
                             <div className="px-4 py-1.5 bg-brand-500 text-black text-[9px] font-black uppercase rounded shadow-xl tracking-widest">98% Accuracy</div>
                             <span className="text-[9px] text-zinc-600 font-bold uppercase tracking-widest flex items-center gap-1.5"><RefreshCw className="w-3 h-3" /> Live Link</span>
                          </div>
                       </div>
                    </div>

                    <div>
                       <label className="block text-[10px] font-black text-zinc-600 uppercase mb-4 tracking-[0.2em] pl-1">Core Directives (System Instruction)</label>
                       <textarea 
                         value={formData.systemInstruction || ''}
                         onChange={(e) => updateField('systemInstruction', e.target.value)}
                         className="w-full h-96 bg-black/40 border border-zinc-800 rounded-[2.5rem] p-10 text-zinc-300 font-mono text-sm focus:ring-1 focus:ring-brand-500 outline-none resize-none leading-relaxed shadow-inner custom-scrollbar"
                         placeholder="Paste operational guidelines..."
                       />
