                 </div>
              )}

              {activeTab === 'test' && (
                 <div className="h-full max-w-5xl mx-auto flex flex-col bg-black/40 border border-zinc-800 rounded-[3rem] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-500">
