                       <div className="flex items-center gap-4">
                          <div className="w-3 h-3 rounded-full bg-green-500 animate-pulse shadow-[0_0_12px_#22c55e]"></div>
                          <span className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em]">Live Simulation Grid</span>
                       </div>
                       <button onClick={() => setChatHistory([])} className="p-3 hover:bg-white/5 rounded-xl text-zinc-700 hover:text-white transition-all"><RefreshCw className="w-5 h-5" /></button>
                    </div>

                    <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-8 custom-scrollbar">
                       {chatHistory.map((msg) => (
                          <div key={msg.id} className={`flex gap-6 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-in fade-in slide-in-from-bottom-2`}>
                             <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-2xl ${msg.role === 'user' ? 'bg-zinc-900 text-zinc-600 border border-zinc-800' : 'bg-brand-600 text-white shadow-brand-500/20'}`}>
                                {msg.role === 'user' ? <User className="w-6 h-6" /> : <Bot className="w-6 h-6" />}
                             </div>
                             <div className={`max-w-[75%] rounded-[2rem] p-7 text-sm leading-relaxed shadow-2xl ${
                                msg.role === 'user' 
                                  ? 'bg-zinc-900 border border-zinc-800 text-zinc-200 rounded-tr-none' 
                                  : 'bg-dark-surface border border-brand-500/20 text-zinc-200 rounded-tl-none'
                             }`}>
                                {msg.text}
                             </div>
                          </div>
                       ))}
                    </div>

                    <form onSubmit={handleSendMessage} className="p-8 border-t border-zinc-800 bg-dark-surface/50">
                       <div className="relative max-w-4xl mx-auto">
                          <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder={`Command ${formData.name || 'Operative'}...`} className="w-full bg-black/60 border border-zinc-800 rounded-2xl py-5 pl-8 pr-16 text-white font-bold focus:ring-2 focus:ring-brand-500 outline-none transition-all shadow-inner placeholder-zinc-700" />
                          <button type="submit" className="absolute right-2 top-2 p-4 bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-2xl transition-all active:scale-90"><Send className="w-5 h-5" /></button>
                       </div>
                    </form>
                 </div>
              )}
           </div>
        </div>
      )}
    </div>
  );
};

