import React, { useEffect, useState, useCallback, useRef } from 'react';
import { BrandDNA, TrendItem } from '../types';
import { getBrandTrends } from '../services/rocketNewService';
import { useStore } from '../store';
import { TrendingUp, RefreshCw, Flame, AlertCircle, Cpu, Activity, Zap, ZapOff, Power } from 'lucide-react';

interface TrendPulseProps {
  currentBrand: BrandDNA | null;
}

export const TrendPulse: React.FC<TrendPulseProps> = ({ currentBrand }) => {
  const { showTrendPulse, toggleTrendPulse } = useStore();
  const [trends, setTrends] = useState<(TrendItem & { isSimulated?: boolean })[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<{message: string, code?: string} | null>(null);
  const lastFetchedBrandId = useRef<string | undefined>(undefined);

  const fetchTrends = useCallback(async (force = false) => {
    // Prevent execution if feature is toggled OFF
    if (!showTrendPulse) return;

    // Prevent spam if already loading or if brand hasn't changed (unless forced)
    if (loading) return;
    if (!force && currentBrand?.id === lastFetchedBrandId.current && trends.length > 0) return;

    setLoading(true);
    setError(null);
    try {
      const data = await getBrandTrends(currentBrand || undefined, force);
      setTrends(data);
      lastFetchedBrandId.current = currentBrand?.id;
    } catch (e: any) {
      console.error(e);
      setError({ message: e.message || "Failed to pulse trends", code: e.code });
    } finally {
      setLoading(false);
    }
  }, [currentBrand?.id, loading, trends.length, showTrendPulse]);

  useEffect(() => {
    if (showTrendPulse) {
      fetchTrends();
    }
  }, [fetchTrends, showTrendPulse]);

  const hasSimulatedData = trends.some(t => t.isSimulated);

  // Hibernation state UI
  if (!showTrendPulse) {
    return (
      <div className="w-full bg-dark-surface/20 border border-dark-border border-dashed rounded-[2rem] p-8 flex flex-col md:flex-row items-center justify-between gap-6 group hover:bg-dark-surface/30 transition-all">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 rounded-xl bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-700">
            <ZapOff className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-lg font-black text-zinc-500 uppercase tracking-tighter">Signal Processing Hibernating</h2>
            <p className="text-zinc-700 text-xs font-bold uppercase tracking-tight mt-0.5">Macro intelligence feed suppressed to conserve neural tokens.</p>
          </div>
        </div>
        <button 
          onClick={toggleTrendPulse}
          className="px-8 py-3 bg-zinc-800 hover:bg-brand-600 text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-xl transition-all shadow-xl flex items-center gap-3 group/btn active:scale-95"
        >
          <Zap className="w-4 h-4 fill-current group-hover/btn:scale-110 transition-transform" /> 
          Activate Feed
        </button>
      </div>
    );
  }

  return (
    <div className="w-full bg-dark-surface/50 border border-dark-border rounded-[2rem] p-8 shadow-2xl relative overflow-hidden group">
      {/* Background Decor */}
      <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
        <Activity className="w-32 h-32 text-brand-500" />
      </div>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 relative z-10">
        <div className="flex items-center gap-4">
          <div>
            <h2 className="text-xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
              <Flame className="w-5 h-5 text-orange-500" /> Real-time Trend Pulse
            </h2>
            <div className="flex items-center gap-4 mt-1">
               <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">Macro Market Signals Integrated</p>
               <span className="flex items-center gap-1.5 px-2 py-0.5 bg-amber-900/20 text-amber-500 text-[8px] font-black rounded border border-amber-500/20">
                 <Cpu className="w-2.5 h-2.5" /> {hasSimulatedData ? 'CACHED INTELLIGENCE' : 'LIVE NEURAL FEED'}
               </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {/* Toggle inside component */}
           <div className="flex items-center gap-3 px-4 py-2 bg-black/40 border border-zinc-800 rounded-2xl mr-2">
              <span className="text-[9px] font-black text-brand-500 uppercase tracking-widest">Active Link</span>
              <button 
                onClick={toggleTrendPulse}
                className="relative w-10 h-5 rounded-full bg-brand-600 border border-brand-400 shadow-[0_0_10px_#14b8a655]"
              >
                <div className="absolute right-0.5 top-0.5 w-3.5 h-3.5 bg-white rounded-full flex items-center justify-center shadow-lg">
                  <Power className="w-2 h-2 text-brand-600" />
                </div>
              </button>
           </div>

          <button 
            onClick={() => fetchTrends(true)} 
            disabled={loading}
            className="p-3 bg-zinc-900 border border-zinc-800 rounded-xl text-zinc-500 hover:text-white hover:border-brand-500 transition-all shadow-lg group/btn"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : 'group-hover/btn:rotate-180 transition-transform duration-500'}`} />
          </button>
        </div>
      </div>

      {error ? (
        <div className="flex flex-col items-center justify-center p-12 text-center bg-red-950/5 rounded-2xl border border-red-900/20">
           <AlertCircle className="w-10 h-10 text-red-500/50 mb-4" />
           <p className="text-sm font-bold text-zinc-300">Pulse Transmission Interrupted</p>
           <p className="text-xs text-zinc-500 mt-1">{error.message}</p>
           <button onClick={() => fetchTrends(true)} className="mt-6 text-[10px] font-black text-brand-500 uppercase tracking-widest hover:text-white transition-colors">Re-establish Link</button>
        </div>
      ) : loading && trends.length === 0 ? (
        <div className="py-24 flex flex-col items-center justify-center gap-4">
           <RefreshCw className="w-8 h-8 text-brand-500 animate-spin" />
           <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Scanning Global Neural Signals...</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative z-10">
          {trends.map((trend) => (
            <div key={trend.id} className="bg-black/40 border border-zinc-800 hover:border-brand-500/40 rounded-2xl p-6 transition-all group/card shadow-xl flex flex-col">
              <div className="flex justify-between items-start mb-4">
                <span className="px-2 py-0.5 bg-zinc-900 text-zinc-500 text-[8px] font-black uppercase rounded border border-zinc-800">{trend.category}</span>
