                          <span className={autoAnimate ? 'text-brand-400 font-black' : 'text-zinc-600 font-bold uppercase'}>{autoAnimate ? 'ENABLED' : 'MANUAL'}</span>
                       </div>
                    </div>
                    <button onClick={handleStartEngine} className="w-full mt-auto py-5 bg-green-600 hover:bg-green-500 text-white font-black rounded-2xl flex items-center justify-center gap-4 shadow-2xl transition-all active:scale-95 group">
                      <Play className="w-6 h-6 fill-current group-hover:scale-110 transition-transform" />
                      <span className="tracking-[0.2em] uppercase text-xs">IGNITE FORGE ENGINE</span>
                    </button>
                 </div>
                 <div className="lg:col-span-8 bg-black/20 border border-zinc-800 rounded-[2rem] p-10 overflow-y-auto max-h-[600px] shadow-inner">
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter mb-8">{prd.userStories.length} Operation Segments Locked</h3>
                    <div className="space-y-4">
                       {prd.userStories.map((story, i) => (
                         <div key={i} className="bg-dark-surface p-6 rounded-2xl border border-zinc-800/50 flex gap-6 items-center group hover:border-brand-500/40 transition-all">
                            <div className="flex flex-col items-center justify-center min-w-[3.5rem] h-14 bg-zinc-900 rounded-xl border border-zinc-800 text-[10px] font-black text-zinc-500 uppercase tracking-tighter">
                               <span>PHASE</span>
                               <span className="text-xl text-white">{story.dayOffset}</span>
                            </div>
                            <div className="flex-1">
                               <div className="flex justify-between items-center mb-2">
                                  <h4 className="text-sm font-black text-zinc-200 uppercase tracking-tight truncate max-w-md">{safeRender(story.description)}</h4>
                                  <span className="text-[9px] uppercase font-black bg-brand-950/40 text-brand-400 px-3 py-1 rounded-md border border-brand-500/20">{story.channel}</span>
                               </div>
                               <div className="flex gap-2">
                                  {story.assetTypes.map(t => (
                                    <span key={t} className="text-[8px] text-zinc-600 bg-black/40 px-2 py-0.5 rounded border border-zinc-800 font-black uppercase tracking-widest">{t}</span>
                                  ))}
                               </div>
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
            )}

            {step === 3 && (
              <div className="max-w-4xl mx-auto pt-10 animate-in fade-in">
                <div className="bg-dark-surface border border-dark-border rounded-[2.5rem] p-12 relative overflow-hidden shadow-2xl">
                   <div className="absolute top-0 left-0 w-full h-1.5 bg-zinc-900">
                      <div className="h-full bg-brand-500 transition-all duration-700 ease-out" style={{ width: `${progress}%` }} />
                   </div>
                   <div className="flex justify-between items-end mb-10">
                      <div>
                        <h2 className="text-4xl font-black text-white uppercase tracking-tighter mb-2">FORGING...</h2>
                        <div className="flex items-center gap-2">
                           <div className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></div>
                           <span className="text-[10px] font-black text-brand-500 uppercase tracking-widest">Autonomous Synthesis in Progress</span>
                        </div>
                      </div>
                      <span className="text-6xl font-black text-white tabular-nums tracking-tighter">{Math.round(progress)}%</span>
                   </div>

                   {error.message && (
                    <div className="mb-6 p-4 bg-red-950/20 border border-red-500/30 rounded-2xl flex flex-col gap-3">
                       <p className="text-red-400 text-xs font-bold uppercase tracking-widest flex items-center gap-2"><AlertTriangle className="w-4 h-4" /> Forge Disruption: {error.message}</p>
                       <Link to="/settings" className="text-[10px] text-red-500 underline uppercase font-black tracking-widest hover:text-white transition-colors">Switch Provider to Resume Forge</Link>
                    </div>
                  )}

                   <div className="bg-black/60 p-8 rounded-3xl font-mono text-[11px] text-zinc-500 h-72 overflow-y-auto custom-scrollbar border border-zinc-800 shadow-inner">
                      {logs.map((log, i) => (
                        <div key={i} className={`mb-2 animate-in fade-in slide-in-from-left-2 ${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-green-500' : 'text-brand-500/70'}`}>
                           [{new Date().toLocaleTimeString([], { hour12: false })}] {">"} {safeRender(log.msg)}
                        </div>
                      ))}
                   </div>
                </div>
              </div>
            )}

            {step === 4 && (
              <div className="space-y-12 animate-in slide-in-from-bottom-8">
                 <div className="bg-brand-900/10 border border-brand-500/20 p-10 rounded-[3rem] flex justify-between items-center shadow-xl">
                    <div>
                      <h2 className="text-4xl font-black text-white uppercase tracking-tighter mb-2">{safeRender(overview.name)}</h2>
                      <div className="flex items-center gap-6">
                        <p className="text-zinc-500 font-bold uppercase tracking-[0.3em] text-xs flex items-center gap-3"><CheckCircle2 className="w-4 h-4 text-green-500" /> Synthesis Finalized • {generatedAssets.length} Precision Assets</p>
                        {autoAnimate && <span className="px-3 py-1 bg-brand-500 text-black text-[9px] font-black uppercase rounded-full shadow-lg flex items-center gap-1.5"><Film className="w-3 h-3" /> Motion Applied</span>}
                      </div>
                    </div>
                    <button onClick={() => setStep(1)} className="px-10 py-4 bg-white text-black font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all">INITIATE NEW FORGE</button>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                    {generatedAssets.map(asset => (
                      <AssetCard 
                        key={asset.id} 
                        asset={asset} 
                        onAnimate={handleAnimateAsset}
                        animatingAssets={animatingAssets}
                      />
                    ))}
                 </div>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 animate-in fade-in">
           {campaigns.length > 0 ? campaigns.map(c => (
             <div key={c.id} className="bg-dark-surface border border-dark-border rounded-3xl p-8 hover:border-brand-500/30 transition-all flex flex-col shadow-xl">
                <div className="mb-6">
                  <h3 className="text-2xl font-black text-white uppercase tracking-tighter mb-2 truncate">{safeRender(c.name)}</h3>
                  <div className="flex items-center gap-3 text-[10px] text-zinc-500 font-black uppercase tracking-widest">
                    <span>{c.assets.length} Assets</span>
                    <span>•</span>
                    <span className="text-brand-500">{c.goal}</span>
                    {c.assets.some(a => a.videoUrl) && <span className="flex items-center gap-1 text-purple-400 font-black tracking-[0.2em]"><Film className="w-3 h-3" /> MOTION</span>}
                  </div>
                </div>
                <div className="mt-auto flex justify-between items-center">
                   <span className="text-[10px] text-zinc-600 uppercase font-black tracking-widest">{new Date(c.createdAt).toLocaleDateString()}</span>
                   <button onClick={() => { setGeneratedAssets(c.assets); setOverview({ name: c.name, goal: c.goal, audienceSegment: '', timeline: '', constraints: [] }); setStep(4); setView('forge'); }} className="text-brand-500 text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-2 hover:text-white transition-colors">Inspect <Eye className="w-4 h-4" /></button>
                </div>
             </div>
           )) : (
             <div className="col-span-full py-32 flex flex-col items-center justify-center text-zinc-800 bg-black/10 rounded-[4rem] border border-dashed border-zinc-900 group">
                <Box className="w-20 h-20 mb-6 opacity-20 group-hover:scale-110 transition-transform duration-700" />
                <p className="text-xl font-black opacity-30 uppercase tracking-[0.2em]">The Vault is Empty</p>
                <button onClick={() => setView('forge')} className="text-xs text-brand-500 underline font-black uppercase tracking-widest mt-4 hover:text-white transition-colors">Start your first Forge</button>
             </div>
           )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { useStore } from '../store';
import { Agent, AgentType, AgentMessage, BrandDNA } from '../types';
import { chatWithAgent } from '../services/agentService';
import { universalAiService } from '../services/universalAiService';
import { Link } from 'react-router-dom';
import { 
  Bot, 
  Plus, 
  Settings, 
  BookOpen, 
  Shield, 
  MessageSquare, 
  Rocket, 
  Trash2, 
  Save, 
  Terminal,
  User,
  Send,
  RefreshCw,
  Dna,
  ChevronDown,
  Layers,
  CheckCircle2,
  AlertCircle,
  ChevronLeft,
  ChevronRight,
  Sliders,
  Mic,
  Database,
  ShieldCheck,
  Brain,
  Zap,
  Activity,
  UserCheck,
  Globe,
  Info,
  History,
  Lock,
  Search,
  Sparkles,
  Wand2
} from 'lucide-react';

const AgentForgePage = () => {
  const { agents, addAgent, updateAgent, deleteAgent, brands, currentBrand, setBrand } = useStore();
  const [selectedAgentId, setSelectedAgentId] = useState<string>(agents[0]?.id || '');
  const [activeTab, setActiveTab] = useState<'config' | 'knowledge' | 'guardrails' | 'tuning' | 'test'>('config');
  const [showBrandPicker, setShowBrandPicker] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Form State
  const [formData, setFormData] = useState<Partial<Agent>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [isGeneratingInstruction, setIsGeneratingInstruction] = useState(false);

  // Test Chat State
  const [chatHistory, setChatHistory] = useState<AgentMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [simulationMetrics, setSimulationMetrics] = useState({ latency: 0, tokens: 0, fromCache: false });
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize form when selection changes
  useEffect(() => {
    const agent = agents.find(a => a.id === selectedAgentId);
    if (agent) {
      setFormData(agent);
      setIsDirty(false);
      // Reset chat only if agent changed or is empty
      if (chatHistory.length === 0) {
        setChatHistory([{
          id: 'init',
          role: 'model',
          text: `Neural link established. Callsign: ${agent.name}. Sync status: ${currentBrand?.name || 'Global'}. Ready for simulation.`,
          timestamp: new Date().toISOString()
        }]);
      }
    } else {
      setFormData({});
    }
  }, [selectedAgentId, agents, currentBrand?.id]);

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chatHistory, activeTab, isTyping]);

  const handleCreateNew = () => {
    const baseName = currentBrand ? `${currentBrand.name} Rep` : 'New Agent';
    const baseRole = currentBrand ? 'Brand Representative' : 'Assistant';
    const basePersonality = currentBrand ? currentBrand.tone.personality : 'Helpful';

    const baseInstruction = currentBrand 
      ? `You are an official AI representative for "${currentBrand.name}". Adhere to our mission: ${currentBrand.mission}`
      : 'You are a helpful assistant.';

    const newAgent: Agent = {
      id: crypto.randomUUID(),
      name: baseName,
      type: 'custom',
      role: baseRole,
      personality: basePersonality,
      systemInstruction: baseInstruction,
      guardrails: currentBrand ? [`Always maintain ${currentBrand.name} brand safety standards.`] : [],
      knowledgeBase: currentBrand ? [`Primary Objective: ${currentBrand.mission}`] : [],
      status: 'draft',
      avatar: '🤖',
      brandId: currentBrand?.id
    };
    addAgent(newAgent);
    setSelectedAgentId(newAgent.id);
  };

  const handleAutoAlign = () => {
    if (!currentBrand) return;
    const alignedInstruction = `IDENTITY: ${formData.name || 'Operative'}
ROLE: ${formData.role || 'Brand Envoy'}
BRAND CONTEXT: ${currentBrand.name}
MISSION: ${currentBrand.mission}
TONE: ${currentBrand.tone.personality} (${currentBrand.tone.adjectives.join(', ')})
CORE VALUES: ${currentBrand.coreValues.join(', ')}
KEY MESSAGING: ${currentBrand.keyMessaging.join(' | ')}

DIRECTIVES:
1. Always maintain the brand persona.
2. Prioritize user problems related to our target segments: ${currentBrand.targetAudience.join(', ')}.
3. Use language consistent with our design system aesthetic: ${currentBrand.visualIdentity.styleKeywords.join(', ')}.`;

    updateField('systemInstruction', alignedInstruction);
  };

  const handleAiGenInstruction = async () => {
    if (isGeneratingInstruction) return;
    setIsGeneratingInstruction(true);

    const brandCtx = currentBrand ? `
      BRAND: ${currentBrand.name}
      MISSION: ${currentBrand.mission}
      TONE: ${currentBrand.tone.personality}
      CORE VALUES: ${currentBrand.coreValues.join(', ')}
      TARGET AUDIENCE: ${currentBrand.targetAudience.join(', ')}
    ` : 'General Context (No specific brand linked).';

    const prompt = `
      Act as a Prompt Engineering Expert. Generate a sophisticated and comprehensive "System Instruction" for an AI agent.

      AGENT NAME: ${formData.name || 'Operative'}
      AGENT ROLE: ${formData.role || 'Representative'}
      ${brandCtx}

      REQUIREMENTS:
      1. Define a strong persona and identity.
      2. Establish clear operational constraints and behavioral guidelines.
      3. Use a structured, modular format (Identity, Directives, Tone, Response Patterns).
      4. Ensure it perfectly aligns with the mission and target audience provided.
      5. Output ONLY the instruction text, no conversational filler.
    `;

    try {
      const result = await universalAiService.generateText({
        prompt,
        featureId: 'agent-prompt-gen',
        bypassCache: true
      });

      if (result && result !== "FALLBACK_TRIGGERED") {
        updateField('systemInstruction', result);
      }
    } catch (e) {
      console.error("Failed to generate AI instruction", e);
    } finally {
      setIsGeneratingInstruction(false);
    }
  };

  const handleSave = () => {
    if (selectedAgentId && formData) {
      updateAgent(selectedAgentId, { ...formData, brandId: currentBrand?.id });
      setIsDirty(false);
    }
  };

  const handleDelete = () => {
    if (confirm("Decommission this operative? This action cannot be undone.")) {
      deleteAgent(selectedAgentId);
      setSelectedAgentId(agents[0]?.id || '');
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isTyping) return;
    const agent = agents.find(a => a.id === selectedAgentId);
    if (!agent) return;

    const userMsg: AgentMessage = { id: crypto.randomUUID(), role: 'user', text: chatInput, timestamp: new Date().toISOString() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsTyping(true);

    const startTime = Date.now();
    try {
      const response = await chatWithAgent({ ...agent, ...formData } as Agent, chatHistory, userMsg.text);
      const latency = Date.now() - startTime;

      setSimulationMetrics({
        latency,
        tokens: Math.round(response.length / 4), // Rough estimate
        fromCache: latency < 100 // Cache hits are usually near-instant
      });

      setChatHistory(prev => [...prev, { id: crypto.randomUUID(), role: model', text: response, timestamp: new Date().toISOString() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const updateField = (field: keyof Agent, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setIsDirty(true);
  };

  if (agents.length === 0 && !selectedAgentId) {
     return (
       <div className="h-full flex items-center justify-center bg-dark-bg p-8 text-center">
          <div className="max-w-md bg-dark-surface p-16 rounded-[4rem] border border-dark-border shadow-2xl animate-in zoom-in-95">
             <Bot className="w-20 h-20 mx-auto mb-10 text-brand-500 opacity-20" />
             <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-4">Neural Barracks Empty</h2>
             <p className="text-zinc-500 font-medium mb-12 leading-relaxed text-sm">Select a client portfolio context from the dashboard to initialize automated agent recruitment.</p>
             <div className="flex flex-col gap-4">
               {brands.length > 0 && (
                 <button onClick={handleCreateNew} className="w-full py-4 bg-brand-600 hover:bg-brand-500 text-white font-black rounded-2xl shadow-xl transition-all uppercase tracking-widest text-xs">RECRUIT MANUAL OPERATIVE</button>
               )}
               <Link to="/extract" className="w-full py-4 bg-zinc-800 hover:bg-zinc-700 text-white font-black rounded-2xl transition-all uppercase tracking-widest text-xs">SEQUENCE NEW BRAND DNA</Link>
             </div>
          </div>
       </div>
     );
  }

  return (
    <div className="flex h-full bg-dark-bg overflow-hidden relative">
      {/* SIDEBAR: COLLAPSIBLE OPERATIVE MATRIX */}
      <div className={`bg-dark-surface border-r border-dark-border flex flex-col shrink-0 transition-all duration-300 relative z-20 ${isSidebarOpen ? 'w-80' : 'w-0 opacity-0 invisible overflow-hidden'}`}>
         <div className="p-6 border-b border-dark-border bg-black/20">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-black text-white uppercase tracking-widest flex items-center gap-3">
                <Bot className="w-5 h-5 text-brand-500" /> OPERATIVES
              </h2>
              <button onClick={handleCreateNew} className="p-2 bg-brand-900/20 text-brand-400 hover:bg-brand-600 hover:text-white rounded-xl transition-all shadow-lg">
                <Plus className="w-4 h-4" />
              </button>
            </div>

            {/* Portfolio Switcher - Inline Sidebar */}
            <div className="relative">
               <label className="text-[9px] font-black text-zinc-600 uppercase tracking-widest mb-2.5 block px-1">DNA CONTEXT</label>
               <button 
                 onClick={() => setShowBrandPicker(!showBrandPicker)}
                 className="w-full p-4 bg-black/40 border border-zinc-800 rounded-2xl flex items-center justify-between group hover:border-brand-500/40 transition-all shadow-inner"
               >
                  <div className="flex items-center gap-3 overflow-hidden">
                     <Dna className="w-4 h-4 text-brand-500 shrink-0" />
                     <span className="text-xs font-black text-white uppercase tracking-tight truncate">{currentBrand?.name || 'Unlinked Core'}</span>
                  </div>
                  <ChevronDown className={`w-4 h-4 text-zinc-600 transition-transform ${showBrandPicker ? 'rotate-180' : ''}`} />
               </button>

               {showBrandPicker && (
                  <div className="absolute top-full left-0 right-0 mt-3 bg-dark-surface border border-dark-border rounded-2xl shadow-2xl z-[100] p-2 animate-in fade-in slide-in-from-top-2 border-brand-500/20">
                     {brands.map(b => (
                        <button 
                          key={b.id}
                          onClick={() => { setBrand(b); setShowBrandPicker(false); }}
                          className={`w-full p-4 text-left rounded-xl text-xs font-bold uppercase flex items-center justify-between hover:bg-brand-900/10 transition-colors ${currentBrand?.id === b.id ? 'text-brand-400 bg-brand-900/5' : 'text-zinc-500'}`}
                        >
                           <span className="truncate">{b.name}</span>
                           {currentBrand?.id === b.id && <CheckCircle2 className="w-3.5 h-3.5" />}
                        </button>
                     ))}
                  </div>
               )}
            </div>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {agents.map(agent => (
               <div 
                 key={agent.id}
                 onClick={() => setSelectedAgentId(agent.id)}
                 className={`p-5 rounded-[1.5rem] cursor-pointer border transition-all flex items-center gap-4 ${
                    selectedAgentId === agent.id 
                      ? 'bg-brand-900/10 border-brand-500 shadow-2xl shadow-brand-500/10 scale-[1.02]' 
                      : 'bg-black/20 border-zinc-800/50 text-zinc-400 hover:border-zinc-700'
                 }`}
               >
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl shadow-inner ${selectedAgentId === agent.id ? 'bg-brand-600 text-white' : 'bg-zinc-900 text-zinc-500'}`}>
                     {agent.avatar}
                  </div>
                  <div className="flex-1 min-w-0">
                     <div className="font-black text-sm truncate text-white uppercase tracking-tight">{agent.name}</div>
                     <div className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest mt-1">{agent.type} • {agent.status}</div>
                  </div>
               </div>
            ))}
         </div>
      </div>

      {/* Sidebar Toggle Button */}
      <button 
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className={`absolute z-50 top-1/2 -translate-y-1/2 p-1.5 bg-dark-surface border border-dark-border text-zinc-500 hover:text-brand-500 rounded-full shadow-2xl transition-all ${isSidebarOpen ? 'left-[304px]' : 'left-4'}`}
      >
        {isSidebarOpen ? <ChevronLeft className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
      </button>

      {/* MAIN PLAYGROUND */}
      {selectedAgentId && (
        <div className="flex-1 flex flex-col min-w-0 bg-dark-bg/20">
           {/* Forge Header */}
           <div className={`h-24 border-b border-dark-border bg-dark-surface/50 backdrop-blur-2xl px-10 flex justify-between items-center shrink-0 transition-all ${!isSidebarOpen ? 'pl-16' : ''}`}>
              <div className="flex items-center gap-8">
                 <div className="w-14 h-14 rounded-2xl bg-brand-600 flex items-center justify-center text-3xl shadow-2xl shadow-brand-600/30">
                    {formData.avatar}
                 </div>
                 <div>
                    <div className="flex items-center gap-4">
                       <h1 className="text-3xl font-black text-white uppercase tracking-tighter">{formData.name}</h1>
                       {isDirty && <span className="text-[8px] bg-amber-500 text-black px-2 py-0.5 rounded-sm font-black uppercase tracking-[0.2em]">MODIFIED</span>}
                    </div>
                    <div className="flex items-center gap-6 text-[10px] font-black uppercase tracking-widest text-zinc-500 mt-2">
                       <span className="flex items-center gap-2"><Layers className="w-3.5 h-3.5 text-brand-500" /> {formData.type} Segment</span>
                       {formData.status === 'deployed' && <span className="text-green-500 flex items-center gap-2"><Rocket className="w-3.5 h-3.5" /> Mission Live</span>}
                       <span className="text-zinc-700">|</span>
                       <span className="flex items-center gap-2 text-zinc-400"><Activity className="w-3.5 h-3.5" /> Health: Optimal</span>
                    </div>
                 </div>
              </div>

              <div className="flex items-center gap-4">
                 <button onClick={handleDelete} className="p-4 text-zinc-700 hover:text-red-500 transition-colors" title="Decommission Operative"><Trash2 className="w-5.5 h-5.5" /></button>
                 <div className="h-10 w-px bg-zinc-800 mx-2" />
                 <button onClick={handleSave} disabled={!isDirty} className="px-8 py-3.5 bg-zinc-900 hover:bg-zinc-800 disabled:opacity-30 text-white text-[10px] font-black uppercase tracking-widest rounded-xl transition-all border border-zinc-800 shadow-lg">SAVE CONFIG</button>
                 <button className="px-10 py-3.5 bg-brand-600 hover:bg-brand-500 text-white text-[10px] font-black uppercase tracking-widest rounded-xl shadow-2xl shadow-brand-500/20 transition-all active:scale-95">IGNITE DEPLOYMENT</button>
              </div>
           </div>

           {/* Workspace Tabs */}
           <div className={`flex border-b border-dark-border bg-black/40 px-10 shrink-0 transition-all ${!isSidebarOpen ? 'pl-16' : ''}`}>
              {[
                { id: 'config', label: 'Instruction Matrix', icon: Settings },
                { id: 'knowledge', label: 'Neural Base', icon: BookOpen },
                { id: 'guardrails', label: 'Safety Protocols', icon: ShieldCheck },
                { id: 'tuning', label: 'Inference Tuning', icon: Sliders },
                { id: 'test', label: 'Simulation Grid', icon: Terminal }
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`px-10 py-5 text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 border-b-2 transition-all ${activeTab === tab.id ? 'border-brand-500 text-brand-500 bg-brand-500/5' : 'border-transparent text-zinc-600 hover:text-zinc-300'}`}
                >
                   <tab.icon className="w-4 h-4" /> {tab.label}
                </button>
