  Bot, 
  Plus, 
  Settings, 
  BookOpen, 
  Shield, 
  MessageSquare, 
  Rocket, 
  Trash2, 
  Save, 
  Terminal,
  User,
  Send,
  RefreshCw,
  Dna,
  ChevronDown,
  Layers,
  CheckCircle2,
  AlertCircle,
  ChevronLeft,
  ChevronRight,
